action.command:
cd /workspace && python3 - <<'EOF'
import json
c=json.load(open('contracts/openapi.contract.json'))
out=open('/tmp/contract_summary.txt','w')
def dump(s,ind=0):
    pre='  '*ind
    if not isinstance(s,dict): 
        out.write(pre+repr(s)+'\n'); return
    t=s.get('type')
    if t=='object' or 'properties' in s:
        req=s.get('required',[])
        out.write(pre+'object req='+str(req)+(' addlProps=%s'%s.get('additionalProperties'))+'\n')
        for k,v in (s.get('properties') or {}).items():
            out.write(pre+' '+k+': ')
            dump(v,ind+1)
    elif t=='array':
        out.write(pre+'array of:\n'); dump(s.get('items',{}),ind+1)
    else:
        keys={k:v for k,v in s.items() if k not in('description',)}
        out.write(pre+json.dumps(keys)+'\n')
for p,ops in c['paths'].items():
    for m,op in ops.items():
        out.write('\n=== %s %s %s ===\n'%(m.upper(),p,op.get('operationId')))
        rb=op.get('requestBody')
        if rb:
            sch=rb['content']['application/json']['schema']
            out.write('REQUEST:\n'); dump(sch,1)
        for code,r in op.get('responses',{}).items():
            out.write('RESP %s:\n'%code)
            cont=r.get('content',{}).get('application/json',{}).get('schema')
            if cont: dump(cont,1)
out.close()
print('done')
EOF
wc -l /tmp/contract_summary.txt

