import json
c=json.load(open('/workspace/contracts/openapi.contract.json'))
out=open('/tmp/components.txt','w')
def dump(s,ind=0):
    pre='  '*ind
    if not isinstance(s,dict):
        out.write(pre+repr(s)+'\n'); return
    if '$ref' in s:
        out.write(pre+json.dumps(s)+'\n'); return
    t=s.get('type')
    if t=='object' or 'properties' in s:
        req=s.get('required',[])
        out.write(pre+'object req='+str(req)+(' addlProps=%s'%s.get('additionalProperties'))+'\n')
        for k,v in (s.get('properties') or {}).items():
            out.write(pre+' '+k+':\n')
            dump(v,ind+1)
    elif t=='array':
        out.write(pre+'array of:\n'); dump(s.get('items',{}),ind+1)
    else:
        out.write(pre+json.dumps(s)+'\n')
for name,sch in c.get('components',{}).get('schemas',{}).items():
    out.write('\n### %s ###\n'%name)
    dump(sch,0)
out.close()
print('done')

