package main

import (
	"context"
	"encoding/json"
	"log"
	"sync"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

type App struct {
	mu     sync.Mutex
	state  *State
	db     *pgxpool.Pool
	dirty  bool
	evSubs map[chan struct{}]struct{}
}

const schemaDDL = `
CREATE TABLE IF NOT EXISTS app_state (
  id INTEGER PRIMARY KEY,
  doc JSONB NOT NULL,
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS schema_meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS app_state_id_idx ON app_state (id);
`

func NewApp(db *pgxpool.Pool) *App {
	return &App{db: db, evSubs: map[chan struct{}]struct{}{}}
}

func (a *App) EnsureSchema(ctx context.Context) error {
	_, err := a.db.Exec(ctx, schemaDDL)
	return err
}

func (a *App) Load(ctx context.Context) error {
	a.state = NewState()
	var doc []byte
	err := a.db.QueryRow(ctx, `SELECT doc FROM app_state WHERE id=1`).Scan(&doc)
	if err == nil {
		st := NewState()
		if uerr := json.Unmarshal(doc, st); uerr == nil {
			a.state = st
		}
	}
	return nil
}

// persistLocked writes the state snapshot; caller holds the lock.
func (a *App) persistLocked() {
	a.dirty = true
	doc, err := json.Marshal(a.state)
	if err != nil {
		log.Printf("marshal state: %v", err)
		return
	}
	ctx, cancel := context.WithTimeout(context.Background(), 10*time.Second)
	defer cancel()
	_, err = a.db.Exec(ctx, `INSERT INTO app_state (id, doc, updated_at) VALUES (1, $1, now())
		ON CONFLICT (id) DO UPDATE SET doc = EXCLUDED.doc, updated_at = now()`, doc)
	if err != nil {
		log.Printf("persist state: %v", err)
	}
	a.dirty = false
}

// mutate runs fn under lock; if fn returns nil error, persists state.
func (a *App) mutate(fn func(*State) *apiError) *apiError {
	a.mu.Lock()
	defer a.mu.Unlock()
	if e := fn(a.state); e != nil {
		return e
	}
	a.state.StateVersion++
	a.persistLocked()
	a.notifyLocked()
	return nil
}

func (a *App) read(fn func(*State)) {
	a.mu.Lock()
	defer a.mu.Unlock()
	fn(a.state)
}

func (a *App) notifyLocked() {
	for ch := range a.evSubs {
		select {
		case ch <- struct{}{}:
		default:
		}
	}
}

func (a *App) subscribe() chan struct{} {
	ch := make(chan struct{}, 1)
	a.mu.Lock()
	a.evSubs[ch] = struct{}{}
	a.mu.Unlock()
	return ch
}

func (a *App) unsubscribe(ch chan struct{}) {
	a.mu.Lock()
	delete(a.evSubs, ch)
	a.mu.Unlock()
}

func (a *App) auditLocked(actorID, role, action, entityType, entityID string, success bool, details map[string]interface{}) {
	if details == nil {
		details = map[string]interface{}{}
	}
	a.state.Audit = append(a.state.Audit, AuditEntry{
		AuditID: newUUID(), ActorID: actorID, Role: role, Action: action,
		EntityType: entityType, EntityID: entityID, Success: success,
		OccurredAt: time.Now().UTC(), Details: details,
	})
	if len(a.state.Audit) > 200000 {
		a.state.Audit = a.state.Audit[len(a.state.Audit)-100000:]
	}
}

func (a *App) emitLocked(typ, entityType, entityID string, payload map[string]interface{}, audience []string) {
	a.state.EventSeq++
	a.state.Events = append(a.state.Events, Event{
		ID: a.state.EventSeq, Type: typ, EntityType: entityType, EntityID: entityID,
		Payload: payload, Audience: audience, CreatedAt: time.Now().UTC(),
	})
	if len(a.state.Events) > 50000 {
		a.state.Events = a.state.Events[len(a.state.Events)-25000:]
	}
}

