// ---------- routing ----------

type routeResult struct {
	Found        bool
	LocationIDs  []string // includes start and end
	ConnectionIDs []string
	TravelMinutes int
	CostUnits    float64
}

// dijkstra over active connections; cooledRequired restricts to cooled connections.
func findRoute(st *State, fromLocationID string, cooledRequired bool, acceptLab func(locID string) bool) *routeResult {
	dist := map[string]int{fromLocationID: 0}
	prevLoc := map[string]string{}
	prevConn := map[string]string{}
	visited := map[string]bool{}
	best := ""
	for {
		// pick unvisited min
		cur := ""
		curD := math.MaxInt32
		for id, d := range dist {
			if !visited[id] && d < curD {
				cur, curD = id, d
			}
		}
		if cur == "" {
			break
		}
		visited[cur] = true
		loc := st.Locations[cur]
		if loc == nil || !loc.Active {
			continue
		}
		if cur != fromLocationID && acceptLab(cur) {
			best = cur
			break
		}
		for _, c := range st.Connections {
			if !c.Active || c.FromLocationID != cur {
				continue
			}
			if cooledRequired && !c.Cooled {
				continue
			}
			to := st.Locations[c.ToLocationID]
			if to == nil || !to.Active {
				continue
			}
			// intermediate nodes must provide transfer/hub function
			if !acceptLab(c.ToLocationID) && !(to.Functions.TransferPoint || to.Functions.Hub || to.Functions.CollectionPoint) {
				continue
			}
			nd := curD + c.TravelMinutes + to.HandlingMinutes
			if ex, ok := dist[c.ToLocationID]; !ok || nd < ex {
				dist[c.ToLocationID] = nd
				prevLoc[c.ToLocationID] = cur
				prevConn[c.ToLocationID] = c.ConnectionID
			}
		}
	}
	if best == "" {
		return nil
	}
	res := &routeResult{Found: true, TravelMinutes: dist[best]}
	cur := best
	for cur != fromLocationID {
		res.LocationIDs = append([]string{cur}, res.LocationIDs...)
		res.ConnectionIDs = append([]string{prevConn[cur]}, res.ConnectionIDs...)
		res.CostUnits += st.Connections[prevConn[cur]].CostUnits
		cur = prevLoc[cur]
	}
	res.LocationIDs = append([]string{fromLocationID}, res.LocationIDs...)
	return res
}

func labAccepts(st *State, loc *Location, sampleTypeID string) bool {
	if loc == nil || !loc.Active || !loc.Functions.Laboratory {
		return false
	}
	return loc.AcceptedTypes[sampleTypeID]
}

// nearest active collection point within coverage
func nearestCollectionPoint(st *State, origin Coordinate) *Location {
	var best *Location
	bestD := math.MaxFloat64
	for _, l := range st.Locations {
		if !l.Active || !l.Functions.CollectionPoint {
			continue
		}
		d := haversineKm(origin, l.Coordinate)
		if d <= l.CoverageKm && d < bestD {
			best, bestD = l, d
		}
	}
	return best
}

func hasCapacity(cap Capacity, cooled bool) bool {
	if cooled {
		return cap.CooledCapacityUnits-cap.CooledReservedUnits >= 1
	}
	return cap.CapacityUnits-cap.ReservedUnits >= 1
}

func routeHasCapacity(st *State, r *routeResult, cooled bool) bool {
	for _, cid := range r.ConnectionIDs {
		if !hasCapacity(st.Connections[cid].Capacity, cooled) {
			return false
		}
	}
	for _, lid := range r.LocationIDs {
		if !hasCapacity(st.Locations[lid].Capacity, cooled) {
			return false
		}
	}
	return true
}

type serviceabilityResult struct {
	Serviceable   bool
	Reason        string
	EntryNodeID   string
	LaboratoryID  string
	Route         *routeResult
	EstimatedArrival time.Time
}

func computeServiceability(st *State, origin Coordinate, originType, originNodeID, sampleTypeID string, earliest, deadline time.Time) *serviceabilityResult {
	res := &serviceabilityResult{Reason: "serviceable"}
	st2 := st.SampleTypes[sampleTypeID]
	if st2 == nil {
		res.Reason = "handling_rules_unsatisfiable"
		return res
	}
	cooled := st2.RequiresCooledRoute
	var entry *Location
	if originType == "node" && originNodeID != "" {
		entry = st.Locations[originNodeID]
		if entry == nil || !entry.Active || !entry.Functions.CollectionPoint {
			res.Reason = "outside_service_coverage"
			return res
		}
	} else {
		entry = nearestCollectionPoint(st, origin)
		if entry == nil {
			res.Reason = "outside_service_coverage"
			return res
		}
	}
	res.EntryNodeID = entry.LocationID
	accept := func(lid string) bool { return labAccepts(st, st.Locations[lid], sampleTypeID) }
	// any accepting lab at all?
	anyLab := false
	for _, l := range st.Locations {
		if labAccepts(st, l, sampleTypeID) {
			anyLab = true
			break
		}
	}
	if !anyLab {
		res.Reason = "no_accepting_laboratory"
		return res
	}
	if accept(entry.LocationID) {
		res.LaboratoryID = entry.LocationID
		res.Route = &routeResult{Found: true, LocationIDs: []string{entry.LocationID}}
	} else {
		r := findRoute(st, entry.LocationID, cooled, accept)
		if r == nil {
			res.Reason = "no_route"
			return res
		}
		res.Route = r
		res.LaboratoryID = r.LocationIDs[len(r.LocationIDs)-1]
	}
	if !routeHasCapacity(st, res.Route, cooled) {
		res.Reason = "insufficient_capacity"
		return res
	}
	arr := earliest.Add(time.Duration(res.Route.TravelMinutes) * time.Minute)
	res.EstimatedArrival = arr
	if arr.After(deadline) {
		res.Reason = "deadline_unreachable"
		return res
	}
	res.Serviceable = true
	return res
}

func recomputeServiceabilitySnapshot(st *State) {
	regions := []ServiceabilityRegion{}
	for _, l := range st.Locations {
		if l.Active && l.Functions.CollectionPoint {
			regions = append(regions, ServiceabilityRegion{
				LocationID: l.LocationID, Name: l.Name,
				Latitude: l.Coordinate.Latitude, Longitude: l.Coordinate.Longitude,
				CoverageKm: l.CoverageKm,
			})
		}
	}
	sort.Slice(regions, func(i, j int) bool { return regions[i].Name < regions[j].Name })
	st.Serviceability = ServiceabilitySnapshot{
		Version: st.Serviceability.Version + 1, Status: "complete",
		ComputedAt: time.Now().UTC(), NetworkRevision: st.NetworkRevision,
		Regions: regions, ActiveCollectionPointCount: len(regions),
	}
}

// ---------- capacity ----------

func reserveCapacityLocked(st *State, r *routeResult, cooled bool, n int) {
	for _, cid := range r.ConnectionIDs {
		c := st.Connections[cid]
		if cooled {
			c.Capacity.CooledReservedUnits += n
		} else {
			c.Capacity.ReservedUnits += n
		}
		c.Capacity.AvailableUnits = c.Capacity.CapacityUnits - c.Capacity.ReservedUnits
		c.Capacity.CooledAvailableUnits = c.Capacity.CooledCapacityUnits - c.Capacity.CooledReservedUnits
	}
	for _, lid := range r.LocationIDs {
		l := st.Locations[lid]
		if cooled {
			l.Capacity.CooledReservedUnits += n
		} else {
			l.Capacity.ReservedUnits += n
		}
		l.Capacity.AvailableUnits = l.Capacity.CapacityUnits - l.Capacity.ReservedUnits
		l.Capacity.CooledAvailableUnits = l.Capacity.CooledCapacityUnits - l.Capacity.CooledReservedUnits
	}
}

func releaseCapacityLocked(st *State, r *routeResult, cooled bool, n int) {
	reserveCapacityLocked(st, r, cooled, -n)
}

// ---------- worker offering ----------

func workerActiveAssignmentCount(st *State, userID string) int {
	n := 0
	for _, as := range st.Assignments {
		if as.WorkerID == userID && (as.Status == "accepted" || as.Status == "in_progress") {
			n++
		}
	}
	return n
}

func (a *App) eligibleWorkersLocked(st *State, as *Assignment, sample *Sample) []*User {
	var out []*User
	for _, u := range st.Users {
		if !u.Active || containsStr(as.DeclinedBy, u.UserID) {
			continue
		}
		if u.DeclinePenaltyTill != nil && time.Now().Before(*u.DeclinePenaltyTill) {
			continue
		}
		switch as.Kind {
		case "collection":
			if !containsStr(u.Roles, "collection_professional") || !u.Available {
				continue
			}
			stype := st.SampleTypes[sample.SampleTypeID]
			if stype != nil && stype.QualifiedCollectorRequired {
				ok := containsStr(u.Qualifications, stype.RequiredQualification)
				for _, c := range u.Certifications {
					if c.Code == stype.RequiredQualification && c.Active && (c.ExpiresAt == nil || c.ExpiresAt.After(time.Now())) {
						ok = true
					}
				}
				if !ok {
					continue
				}
			}
		case "transport":
			if !containsStr(u.Roles, "delivery_partner") || !u.Available {
				continue
			}
		case "node":
			if !containsStr(u.Roles, "node_handler") || u.AssignedLocationID != as.NodeID {
				continue
			}
		case "laboratory":
			if !containsStr(u.Roles, "laboratory_team") || u.AssignedLocationID != as.LaboratoryID {
				continue
			}
		}
		out = append(out, u)
	}
	sort.Slice(out, func(i, j int) bool {
		ci, cj := workerActiveAssignmentCount(st, out[i].UserID), workerActiveAssignmentCount(st, out[j].UserID)
		if ci != cj {
			return ci < cj
		}
		ti := out[i].LastOfferedAt
		tj := out[j].LastOfferedAt
		if ti == nil && tj != nil {
			return true
		}
		if ti != nil && tj == nil {
			return false
		}
		if ti != nil && tj != nil && !ti.Equal(*tj) {
			return ti.Before(*tj)
		}
		return out[i].Username < out[j].Username
	})
	return out
}

// offerAssignmentLocked offers the assignment to the next eligible worker.
// Returns the worker offered to, or nil if none available.
func (a *App) offerAssignmentLocked(st *State, as *Assignment, sample *Sample) *User {
	workers := a.eligibleWorkersLocked(st, as, sample)
	if len(workers) == 0 {
		as.OfferedTo = ""
		as.OfferExpiresAt = nil
		// flag exception if nobody qualified exists at all
		as.DeclinedBy = nil
		if len(a.eligibleWorkersLocked(st, as, sample)) == 0 {
			if sample != nil && sample.Status != "received" && sample.Status != "exception" {
				sample.Status = "exception"
				sample.ExceptionReason = "no_qualified_worker_available"
				a.emitLocked("sample.exception", "sample", sample.SampleID, map[string]interface{}{"reason": "no_qualified_worker_available"}, nil)
			}
		}
		return nil
	}
	w := workers[0]
	as.Status = "pending"
	as.OfferedTo = w.UserID
	exp := time.Now().Add(5 * time.Minute)
	as.OfferExpiresAt = &exp
	now := time.Now()
	w.LastOfferedAt = &now
	a.emitLocked("assignment.offered", "assignment", as.AssignmentID, map[string]interface{}{
		"workerId": w.UserID, "kind": as.Kind, "sampleId": as.SampleID, "journeyId": as.JourneyID,
	}, nil)
	return w
}

// expireOffersLocked treats timed-out offers as declines and re-offers.
func (a *App) expireOffersLocked(st *State) {
	now := time.Now()
	for _, as := range st.Assignments {
		if as.Status == "pending" && as.OfferedTo != "" && as.OfferExpiresAt != nil && as.OfferExpiresAt.Before(now) {
			w := st.Users[as.OfferedTo]
			as.DeclinedBy = append(as.DeclinedBy, as.OfferedTo)
			if w != nil {
				w.RecentDeclines++
				if w.RecentDeclines >= 3 {
					t := now.Add(10 * time.Minute)
					w.DeclinePenaltyTill = &t
					w.RecentDeclines = 0
				}
			}
			a.auditLocked(as.OfferedTo, "", "assignment.offer_expired", "assignment", as.AssignmentID, true, nil)
			sample := st.Samples[as.SampleID]
			a.offerAssignmentLocked(st, as, sample)
		}
	}
}

// ---------- journey construction ----------

// buildJourneyLocked creates a journey for a single sample following svc route.
// alreadySealed: skip collection assignment; holder is current holder.
func (a *App) buildJourneyLocked(st *State, sample *Sample, svc *serviceabilityResult, alreadySealed bool) *Journey {
	j := &Journey{
		JourneyID: newUUID(), PlanVersion: 1, Status: "planned",
		SampleIDs: []string{sample.SampleID}, CreatedAt: time.Now().UTC(),
		TargetLaboratoryID: svc.LaboratoryID,
		TotalCostUnits: svc.Route.CostUnits,
	}
	est := svc.EstimatedArrival
	j.EstimatedDeliveryAt = &est
	locs := svc.Route.LocationIDs
	stype := st.SampleTypes[sample.SampleTypeID]
	cooled := stype != nil && stype.RequiresCooledRoute

	seq := 0
	addStop := func(locID, typ string) {
		seq++
		st_ := Stop{StopID: newUUID(), LocationID: locID, StopType: typ, Sequence: seq}
		if l := st.Locations[locID]; l != nil {
			c := l.Coordinate
			st_.Coordinate = &c
			st_.DwellMinutes = l.HandlingMinutes
		}
		j.Stops = append(j.Stops, st_)
	}

	// collection assignment
	if !alreadySealed {
		ca := &Assignment{
			AssignmentID: newUUID(), Kind: "collection", JourneyID: j.JourneyID,
			SampleID: sample.SampleID, SampleIDs: []string{sample.SampleID},
			Sequence: 0, Status: "pending", ToLocationID: svc.EntryNodeID,
			CreatedAt: time.Now().UTC(),
		}
		st.Assignments[ca.AssignmentID] = ca
		j.CollectionAssignmentIDs = append(j.CollectionAssignmentIDs, ca.AssignmentID)
		sample.ActiveAssignmentIDs = append(sample.ActiveAssignmentIDs, ca.AssignmentID)
	}

	if len(locs) == 1 {
		// entry node is the laboratory
		addStop(locs[0], "delivery")
		la := &Assignment{
			AssignmentID: newUUID(), Kind: "laboratory", JourneyID: j.JourneyID,
			SampleID: sample.SampleID, SampleIDs: []string{sample.SampleID},
			Sequence: 1, Status: "pending", LaboratoryID: locs[0],
			CreatedAt: time.Now().UTC(),
		}
		st.Assignments[la.AssignmentID] = la
		j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, la.AssignmentID)
		sample.ActiveAssignmentIDs = append(sample.ActiveAssignmentIDs, la.AssignmentID)
		j.RouteMode = "direct"
	} else {
		addStop(locs[0], "pickup")
		for i := 0; i < len(locs)-1; i++ {
			ta := &Assignment{
				AssignmentID: newUUID(), Kind: "transport", JourneyID: j.JourneyID,
				SampleID: sample.SampleID, SampleIDs: []string{sample.SampleID},
				Sequence: i + 1, Status: "pending",
				FromLocationID: locs[i], ToLocationID: locs[i+1],
				CreatedAt: time.Now().UTC(),
			}
			st.Assignments[ta.AssignmentID] = ta
			j.LegAssignmentIDs = append(j.LegAssignmentIDs, ta.AssignmentID)
			sample.ActiveAssignmentIDs = append(sample.ActiveAssignmentIDs, ta.AssignmentID)
			if i < len(locs)-2 {
				addStop(locs[i+1], "handoff")
				na := &Assignment{
					AssignmentID: newUUID(), Kind: "node", JourneyID: j.JourneyID,
					SampleID: sample.SampleID, SampleIDs: []string{sample.SampleID},
					Sequence: i + 1, Status: "pending", NodeID: locs[i+1],
					CreatedAt: time.Now().UTC(),
				}
				st.Assignments[na.AssignmentID] = na
				j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, na.AssignmentID)
				sample.ActiveAssignmentIDs = append(sample.ActiveAssignmentIDs, na.AssignmentID)
			}
		}
		addStop(locs[len(locs)-1], "delivery")
		la := &Assignment{
			AssignmentID: newUUID(), Kind: "laboratory", JourneyID: j.JourneyID,
			SampleID: sample.SampleID, SampleIDs: []string{sample.SampleID},
			Sequence: len(locs), Status: "pending", LaboratoryID: locs[len(locs)-1],
			CreatedAt: time.Now().UTC(),
		}
		st.Assignments[la.AssignmentID] = la
		j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, la.AssignmentID)
		sample.ActiveAssignmentIDs = append(sample.ActiveAssignmentIDs, la.AssignmentID)
		if len(locs) == 2 {
			j.RouteMode = "direct"
		} else {
			j.RouteMode = "multi_stop"
		}
	}
	st.Journeys[j.JourneyID] = j
	sample.ActiveJourneyID = j.JourneyID
	sample.TargetLaboratoryID = svc.LaboratoryID
	reserveCapacityLocked(st, svc.Route, cooled, 1)

	// offer the first actionable assignment
	if alreadySealed {
		if len(j.LegAssignmentIDs) > 0 {
			a.offerAssignmentLocked(st, st.Assignments[j.LegAssignmentIDs[0]], sample)
		} else if len(j.LaboratoryAssignmentIDs) > 0 {
			a.offerAssignmentLocked(st, st.Assignments[j.LaboratoryAssignmentIDs[0]], sample)
		}
	} else if len(j.CollectionAssignmentIDs) > 0 {
		a.offerAssignmentLocked(st, st.Assignments[j.CollectionAssignmentIDs[0]], sample)
	}
	return j
}

// offerNextAfterLocked offers the next pending assignment in journey order after one completes.
func (a *App) offerNextAfterLocked(st *State, j *Journey, sample *Sample) {
	order := append([]string{}, j.CollectionAssignmentIDs...)
	order = append(order, j.LegAssignmentIDs...)
	// interleave: simpler global order by sequence then kind priority
	var pend []*Assignment
	for _, id := range append(append(append([]string{}, j.CollectionAssignmentIDs...), j.LegAssignmentIDs...), append(append([]string{}, j.NodeAssignmentIDs...), j.LaboratoryAssignmentIDs...)...) {
		as := st.Assignments[id]
		if as != nil && as.Status == "pending" && as.OfferedTo == "" {
			pend = append(pend, as)
		}
	}
	_ = order
	if len(pend) == 0 {
		return
	}
	sort.Slice(pend, func(i, j int) bool { return pend[i].Sequence < pend[j].Sequence })
	a.offerAssignmentLocked(st, pend[0], sample)
}

// journeyRoute reconstructs the routeResult for capacity release from journey legs.
func journeyRoute(st *State, j *Journey) *routeResult {
	r := &routeResult{Found: true}
	prev := ""
	for _, aid := range j.LegAssignmentIDs {
		as := st.Assignments[aid]
		if as == nil {
			continue
		}
		if prev == "" {
			r.LocationIDs = append(r.LocationIDs, as.FromLocationID)
		}
		r.LocationIDs = append(r.LocationIDs, as.ToLocationID)
		for _, c := range st.Connections {
			if c.FromLocationID == as.FromLocationID && c.ToLocationID == as.ToLocationID {
				r.ConnectionIDs = append(r.ConnectionIDs, c.ConnectionID)
				break
			}
		}
		prev = as.ToLocationID
	}
	if len(r.LocationIDs) == 0 && len(j.LaboratoryAssignmentIDs) > 0 {
		r.LocationIDs = append(r.LocationIDs, st.Assignments[j.LaboratoryAssignmentIDs[0]].LaboratoryID)
	}
	return r
}
"}

