package main

import "time"

func capJSON(c Capacity) map[string]interface{} {
	return map[string]interface{}{
		"capacityUnits": c.CapacityUnits, "reservedUnits": c.ReservedUnits,
		"availableUnits": c.CapacityUnits - c.ReservedUnits,
		"cooledCapacityUnits": c.CooledCapacityUnits, "cooledReservedUnits": c.CooledReservedUnits,
		"cooledAvailableUnits": c.CooledCapacityUnits - c.CooledReservedUnits,
	}
}

func funcJSON(f FunctionStates) map[string]interface{} {
	return map[string]interface{}{
		"collection_point": f.CollectionPoint, "transfer_point": f.TransferPoint,
		"hub": f.Hub, "laboratory": f.Laboratory,
	}
}

func locationJSON(l *Location) map[string]interface{} {
	return map[string]interface{}{
		"locationId": l.LocationID, "name": l.Name, "coordinate": l.Coordinate,
		"coverageKm": l.CoverageKm, "handlingMinutes": l.HandlingMinutes,
		"active": l.Active, "functions": funcJSON(l.Functions),
	}
}

func sampleTypeJSON(t *SampleType) map[string]interface{} {
	incomp := t.IncompatibleSampleTypes
	if incomp == nil {
		incomp = []string{}
	}
	return map[string]interface{}{
		"sampleTypeId": t.SampleTypeID, "name": t.Name,
		"qualifiedCollectorRequired": t.QualifiedCollectorRequired,
		"requiredQualification": t.RequiredQualification,
		"containerType": t.ContainerType, "temperatureMinC": t.TemperatureMinC,
		"temperatureMaxC": t.TemperatureMaxC, "incompatibleSampleTypes": incomp,
		"requiresCooledRoute": t.RequiresCooledRoute, "batchingAllowed": t.BatchingAllowed,
	}
}

func userJSON(u *User) map[string]interface{} {
	quals := u.Qualifications
	if quals == nil {
		quals = []string{}
	}
	certs := u.Certifications
	if certs == nil {
		certs = []Certification{}
	}
	roles := u.Roles
	if roles == nil {
		roles = []string{}
	}
	m := map[string]interface{}{
		"userId": u.UserID, "username": u.Username, "roles": roles,
		"qualifications": quals, "certifications": certs, "active": u.Active,
	}
	if u.Email != "" {
		m["email"] = u.Email
	}
	if u.FullName != "" {
		m["fullName"] = u.FullName
	}
	if u.Phone != "" {
		m["phone"] = u.Phone
	}
	return m
}

func tptr(t *time.Time) interface{} {
	if t == nil {
		return nil
	}
	return timeStr(*t)
}

func stopJSON(s Stop) map[string]interface{} {
	m := map[string]interface{}{
		"stopId": s.StopID, "locationId": s.LocationID, "location_id": s.LocationID,
		"stopType": s.StopType, "stop_type": s.StopType, "sequence": s.Sequence,
	}
	if s.EstimatedAt != nil {
		m["estimatedAt"] = timeStr(*s.EstimatedAt)
		m["estimated_at"] = timeStr(*s.EstimatedAt)
	}
	if s.DwellMinutes != 0 {
		m["dwellMinutes"] = s.DwellMinutes
	}
	if s.Coordinate != nil {
		m["coordinate"] = s.Coordinate
	}
	if s.CompletedAt != nil {
		m["completedAt"] = timeStr(*s.CompletedAt)
	}
	return m
}

func legJSON(st *State, assignmentID string, seq int) map[string]interface{} {
	as := st.Assignments[assignmentID]
	m := map[string]interface{}{
		"assignmentId": assignmentID, "assignment_id": assignmentID,
		"sequence": seq, "status": "pending",
	}
	if as != nil {
		m["status"] = as.Status
		if as.FromLocationID != "" {
			m["fromLocationId"] = as.FromLocationID
			m["from_location_id"] = as.FromLocationID
		}
		if as.ToLocationID != "" {
			m["toLocationId"] = as.ToLocationID
			m["to_location_id"] = as.ToLocationID
		}
		if as.WorkerID != "" {
			m["workerId"] = as.WorkerID
			m["worker_id"] = as.WorkerID
		}
		if as.SampleID != "" {
			m["sampleId"] = as.SampleID
		}
	}
	return m
}

func journeyPlanJSON(st *State, j *Journey) map[string]interface{} {
	stops := []interface{}{}
	for _, s := range j.Stops {
		stops = append(stops, stopJSON(s))
	}
	legs := []interface{}{}
	for i, aid := range j.LegAssignmentIDs {
		legs = append(legs, legJSON(st, aid, i+1))
	}
	workers := []string{}
	seen := map[string]bool{}
	for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegAssignmentIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
		for _, id := range ids {
			if as := st.Assignments[id]; as != nil && as.WorkerID != "" && !seen[as.WorkerID] {
				seen[as.WorkerID] = true
				workers = append(workers, as.WorkerID)
			}
		}
	}
	if j.CollectionAssignmentIDs == nil {
		j.CollectionAssignmentIDs = []string{}
	}
	if j.NodeAssignmentIDs == nil {
		j.NodeAssignmentIDs = []string{}
	}
	if j.LaboratoryAssignmentIDs == nil {
		j.LaboratoryAssignmentIDs = []string{}
	}
	m := map[string]interface{}{
		"journeyId": j.JourneyID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode,
		"status": j.Status, "sampleIds": j.SampleIDs, "orderedStops": stops, "legs": legs,
		"totalCostUnits": j.TotalCostUnits,
		"collectionAssignmentIds": j.CollectionAssignmentIDs,
		"nodeAssignmentIds":       j.NodeAssignmentIDs,
		"laboratoryAssignmentIds": j.LaboratoryAssignmentIDs,
		"assignedWorkerIds":       workers,
	}
	if j.ParentJourneyID != "" {
		m["parentJourneyId"] = j.ParentJourneyID
	}
	if j.EstimatedDeliveryAt != nil {
		m["estimatedDeliveryAt"] = timeStr(*j.EstimatedDeliveryAt)
	}
	if len(j.CollectionAssignmentIDs) > 0 {
		m["collectionAssignmentId"] = j.CollectionAssignmentIDs[0]
	}
	if len(j.LegAssignmentIDs) > 0 {
		m["firstTransportAssignmentId"] = j.LegAssignmentIDs[0]
		m["finalTransportAssignmentId"] = j.LegAssignmentIDs[len(j.LegAssignmentIDs)-1]
	}
	if len(j.LegAssignmentIDs) > 2 {
		m["middleTransportAssignmentId"] = j.LegAssignmentIDs[1]
	}
	if j.ReplanStatus != "" {
		m["replanStatus"] = j.ReplanStatus
	}
	return m
}

func requesterJourneyPlanJSON(st *State, j *Journey) map[string]interface{} {
	stops := []interface{}{}
	for _, s := range j.Stops {
		stops = append(stops, stopJSON(s))
	}
	legs := []interface{}{}
	for i, aid := range j.LegAssignmentIDs {
		legs = append(legs, legJSON(st, aid, i+1))
	}
	m := map[string]interface{}{
		"journeyId": j.JourneyID, "sampleIds": j.SampleIDs, "legs": legs,
		"planVersion": j.PlanVersion, "routeMode": j.RouteMode, "status": j.Status,
		"orderedStops": stops, "totalCostUnits": j.TotalCostUnits,
	}
	if j.ParentJourneyID != "" {
		m["parentJourneyId"] = j.ParentJourneyID
	}
	if j.EstimatedDeliveryAt != nil {
		m["estimatedDeliveryAt"] = timeStr(*j.EstimatedDeliveryAt)
	}
	return m
}

func workerJourneyPlanJSON(st *State, j *Journey, userID string) map[string]interface{} {
	mine := []string{}
	for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegAssignmentIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
		for _, id := range ids {
			if as := st.Assignments[id]; as != nil && (as.WorkerID == userID || as.OfferedTo == userID) {
				mine = append(mine, id)
			}
		}
	}
	legs := []interface{}{}
	for i, aid := range j.LegAssignmentIDs {
		if containsStr(mine, aid) {
			legs = append(legs, legJSON(st, aid, i+1))
		}
	}
	stops := []interface{}{}
	for _, s := range j.Stops {
		stops = append(stops, stopJSON(s))
	}
	workers := []string{}
	for _, id := range mine {
		if as := st.Assignments[id]; as != nil && as.WorkerID != "" {
			workers = append(workers, as.WorkerID)
		}
	}
	m := map[string]interface{}{
		"journeyId": j.JourneyID, "planVersion": j.PlanVersion, "routeMode": j.RouteMode,
		"status": j.Status, "scope": "assigned_legs", "assignmentIds": mine,
		"legs": legs, "orderedStops": stops, "sampleIds": j.SampleIDs,
		"collectionAssignmentIds": j.CollectionAssignmentIDs,
		"nodeAssignmentIds":       j.NodeAssignmentIDs,
		"laboratoryAssignmentIds": j.LaboratoryAssignmentIDs,
		"assignedWorkerIds":       workers,
	}
	if j.ParentJourneyID != "" {
		m["parentJourneyId"] = j.ParentJourneyID
	}
	if j.EstimatedDeliveryAt != nil {
		m["estimatedDeliveryAt"] = timeStr(*j.EstimatedDeliveryAt)
	}
	return m
}

func auditJSON(e AuditEntry) map[string]interface{} {
	return map[string]interface{}{
		"auditId": e.AuditID, "audit_id": e.AuditID,
		"actorId": e.ActorID, "actor_id": e.ActorID,
		"role": e.Role, "actorRole": e.Role,
		"action": e.Action, "entityType": e.EntityType, "entity_type": e.EntityType,
		"entityId": e.EntityID, "entity_id": e.EntityID,
		"success": e.Success, "occurredAt": timeStr(e.OccurredAt), "occurred_at": timeStr(e.OccurredAt),
		"details": e.Details,
	}
}

func timeline(actor, role, action, entityType, entityID string, at time.Time, details map[string]interface{}) map[string]interface{} {
	if details == nil {
		details = map[string]interface{}{}
	}
	return map[string]interface{}{
		"action": action, "actorId": actor, "role": role,
		"entityType": entityType, "entityId": entityID,
		"success": true, "occurredAt": timeStr(at), "details": details,
	}
}

