// ---------- users ----------

type createUserReq struct {
	Username           string          `json:"username"`
	InitialPassword    string          `json:"initialPassword"`
	Email              string          `json:"email"`
	FullName           string          `json:"fullName"`
	Phone              string          `json:"phone"`
	Roles              []string        `json:"roles"`
	Qualifications     []string        `json:"qualifications"`
	Certifications     []Certification `json:"certifications"`
	Active             bool            `json:"active"`
	AssignedLocationID string          `json:"assignedLocationId"`
}

func (a *App) createUser(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req createUserReq
	if !decodeBody(w, r, &req) {
		return
	}
	var out *User
	e := a.mutate(func(st *State) *apiError {
		if req.Username == "" || req.InitialPassword == "" {
			return errAPI(400, "invalid_user", "username and initialPassword are required")
		}
		for _, ro := range req.Roles {
			if !validRoles[ro] {
				return errAPI(400, "invalid_user", "unknown role "+ro)
			}
		}
		for _, c := range req.Certifications {
			if c.Code == "" {
				return errAPI(400, "invalid_certification", "certification code required")
			}
		}
		for _, u := range st.Users {
			if u.Username == req.Username {
				return errAPI(409, "username_exists", "username already exists")
			}
		}
		u := &User{
			UserID: newUUID(), Username: req.Username, PasswordHash: hashPassword(req.InitialPassword),
			Email: req.Email, FullName: req.FullName, Phone: req.Phone,
			Roles: req.Roles, Qualifications: req.Qualifications, Certifications: req.Certifications,
			Active: req.Active, AssignedLocationID: req.AssignedLocationID,
			Available: true, CapacityUnits: 1, CreatedAt: time.Now().UTC(),
		}
		st.Users[u.UserID] = u
		a.auditLocked(getUser(r).UserID, roleOf(r), "user.create", "user", u.UserID, true, map[string]interface{}{"username": u.Username, "roles": u.Roles})
		out = u
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 201, userJSON(out))
}

type updateUserAccessReq struct {
	UserID             string           `json:"userId"`
	Roles              []string         `json:"roles"`
	Qualifications     []string         `json:"qualifications"`
	Certifications     []Certification  `json:"certifications"`
	Active             *bool            `json:"active"`
	AssignedLocationID *string          `json:"assignedLocationId"`
}

func (a *App) updateUserAccess(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req updateUserAccessReq
	if !decodeBody(w, r, &req) {
		return
	}
	var out *User
	e := a.mutate(func(st *State) *apiError {
		u := st.Users[req.UserID]
		if u == nil {
			return errAPI(404, "not_found", "user not found")
		}
		for _, ro := range req.Roles {
			if !validRoles[ro] {
				return errAPI(400, "invalid_certification", "unknown role "+ro)
			}
		}
		if req.Roles != nil {
			u.Roles = req.Roles
		}
		if req.Qualifications != nil {
			u.Qualifications = req.Qualifications
		}
		if req.Certifications != nil {
			for _, c := range req.Certifications {
				if c.Code == "" {
					return errAPI(400, "invalid_certification", "certification code required")
				}
			}
			u.Certifications = req.Certifications
		}
		if req.Active != nil {
			u.Active = *req.Active
		}
		if req.AssignedLocationID != nil {
			u.AssignedLocationID = *req.AssignedLocationID
		}
		a.auditLocked(getUser(r).UserID, roleOf(r), "user.update_access", "user", u.UserID, true, map[string]interface{}{"roles": u.Roles, "active": u.Active})
		out = u
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 201, map[string]interface{}{
		"userId": out.UserID, "roles": out.Roles, "qualifications": out.Qualifications,
		"certifications": out.Certifications, "active": out.Active,
	})
}

func (a *App) readUser(w http.ResponseWriter, r *http.Request) {
	id := r.PathValue("userId")
	me := getUser(r)
	if me.UserID != id && roleOf(r) != "administrator" {
		writeErr(w, errAPI(403, "forbidden", "cannot read other users"))
		return
	}
	var u *User
	a.read(func(st *State) { u = st.Users[id] })
	if u == nil {
		writeErr(w, errAPI(404, "not_found", "user not found"))
		return
	}
	writeData(w, 200, userJSON(u))
}

// ---------- locations ----------

type locationReq struct {
	LocationID      string     `json:"locationId"`
	Name            string     `json:"name"`
	Coordinate      Coordinate `json:"coordinate"`
	CoverageKm      *float64   `json:"coverageKm"`
	HandlingMinutes *int       `json:"handlingMinutes"`
	Active          bool       `json:"active"`
	Functions       []string   `json:"functions"`
}

func validateLocationReq(req *locationReq) *apiError {
	if req.Name == "" {
		return errAPI(400, "invalid_json", "name required")
	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		return errAPI(400, "invalid_coordinate", "coordinate out of range")
	}
	if req.CoverageKm != nil && (*req.CoverageKm <= 0 || *req.CoverageKm > 5) {
		return errAPI(400, "invalid_node_coverage", "coverageKm must be in (0,5]")
	}
	if req.HandlingMinutes != nil && (*req.HandlingMinutes < 0 || *req.HandlingMinutes > 1440) {
		return errAPI(400, "invalid_handling_time", "handlingMinutes must be in [0,1440]")
	}
	for _, f := range req.Functions {
		if !validFunctions[f] {
			return errAPI(400, "invalid_location_function", "unknown function "+f)
		}
	}
	return nil
}

func statesFromFunctions(fns []string) FunctionStates {
	var fs FunctionStates
	for _, f := range fns {
		switch f {
		case "collection_point":
			fs.CollectionPoint = true
		case "transfer_point":
			fs.TransferPoint = true
		case "hub":
			fs.Hub = true
		case "laboratory":
			fs.Laboratory = true
		}
	}
	return fs
}

func (a *App) createLocation(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req locationReq
	if !decodeBody(w, r, &req) {
		return
	}
	if e := validateLocationReq(&req); e != nil {
		writeErr(w, e)
		return
	}
	var out *Location
	e := a.mutate(func(st *State) *apiError {
		cov := 5.0
		if req.CoverageKm != nil {
			cov = *req.CoverageKm
		}
		hm := 0
		if req.HandlingMinutes != nil {
			hm = *req.HandlingMinutes
		}
		l := &Location{
			LocationID: newUUID(), Name: req.Name, Coordinate: req.Coordinate,
			CoverageKm: cov, HandlingMinutes: hm, Active: req.Active,
			Functions: statesFromFunctions(req.Functions),
			Capacity: Capacity{CapacityUnits: 10, AvailableUnits: 10, CooledCapacityUnits: 5, CooledAvailableUnits: 5},
			AcceptedTypes: map[string]bool{},
		}
		st.Locations[l.LocationID] = l
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		a.auditLocked(getUser(r).UserID, roleOf(r), "location.create", "location", l.LocationID, true, map[string]interface{}{"name": l.Name})
		a.emitLocked("location.created", "location", l.LocationID, locationJSON(l), nil)
		out = l
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 201, locationJSON(out))
}

