// ---------- capacity & acceptance ----------

func (a *App) configureCapacity(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator", "dispatcher", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	if req.CapacityUnits < 0 || cooled < 0 {
		writeErr(w, errAPI(400, "invalid_capacity", "capacity must be >= 0"))
		return
	}
	e := a.mutate(func(st *State) *apiError {
		var cap *Capacity
		if l := st.Locations[req.ResourceID]; l != nil {
			// node handlers / lab operators may only configure their own location
			role := roleOf(r)
			if role == "node_handler" || role == "laboratory_team" {
				if getUser(r).AssignedLocationID != l.LocationID {
					return errAPI(403, "forbidden", "not assigned to this location")
				}
			}
			cap = &l.Capacity
		} else if c := st.Connections[req.ResourceID]; c != nil {
			if roleOf(r) == "node_handler" || roleOf(r) == "laboratory_team" {
				return errAPI(403, "forbidden", "cannot configure connection capacity")
			}
			cap = &c.Capacity
		} else {
			return errAPI(400, "invalid_capacity", "unknown resource")
		}
		if req.CapacityUnits < cap.ReservedUnits || cooled < cap.CooledReservedUnits {
			return errAPI(409, "capacity_reserved", "capacity below currently reserved units")
		}
		cap.CapacityUnits = req.CapacityUnits
		cap.CooledCapacityUnits = cooled
		cap.AvailableUnits = cap.CapacityUnits - cap.ReservedUnits
		cap.CooledAvailableUnits = cap.CooledCapacityUnits - cap.CooledReservedUnits
		a.auditLocked(getUser(r).UserID, roleOf(r), "capacity.configure", "resource", req.ResourceID, true, map[string]interface{}{"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled})
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{
		"resourceId": req.ResourceID, "capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled,
	})
}

func (a *App) configureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var accID string
	e := a.mutate(func(st *State) *apiError {
		l := st.Locations[req.LaboratoryID]
		if l == nil || !l.Functions.Laboratory {
			return errAPI(400, "invalid_acceptance", "laboratory not found")
		}
		if st.SampleTypes[req.SampleTypeID] == nil {
			return errAPI(400, "invalid_acceptance", "sample type not found")
		}
		key := req.LaboratoryID + "|" + req.SampleTypeID
		acc := st.Acceptances[key]
		if acc == nil {
			acc = &Acceptance{AcceptanceID: newUUID(), LaboratoryID: req.LaboratoryID, SampleTypeID: req.SampleTypeID}
			st.Acceptances[key] = acc
		}
		acc.Accepts = req.Accepts
		l.AcceptedTypes[req.SampleTypeID] = req.Accepts
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		a.auditLocked(getUser(r).UserID, roleOf(r), "laboratory.configure_acceptance", "laboratory", req.LaboratoryID, true, map[string]interface{}{"sampleTypeId": req.SampleTypeID, "accepts": req.Accepts})
		accID = acc.AcceptanceID
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{"acceptanceId": accID, "accepts": req.Accepts})
}

func (a *App) setWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator", "dispatcher", "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits *int   `json:"capacityUnits"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.CapacityUnits != nil && *req.CapacityUnits < 0 {
		writeErr(w, errAPI(400, "invalid_capacity", "capacityUnits must be >= 0"))
		return
	}
	e := a.mutate(func(st *State) *apiError {
		u := st.Users[req.WorkerID]
		if u == nil {
			return errAPI(404, "not_found", "worker not found")
		}
		role := roleOf(r)
		if role != "administrator" && role != "dispatcher" && getUser(r).UserID != u.UserID {
			return errAPI(403, "forbidden", "cannot change another worker's availability")
		}
		u.Available = req.Available
		if req.CapacityUnits != nil {
			u.CapacityUnits = *req.CapacityUnits
		}
		a.auditLocked(getUser(r).UserID, role, "worker.set_availability", "user", u.UserID, true, map[string]interface{}{"available": req.Available})
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	cu := 0
	if req.CapacityUnits != nil {
		cu = *req.CapacityUnits
	}
	writeData(w, 200, map[string]interface{}{"workerId": req.WorkerID, "available": req.Available, "capacityUnits": cu})
}
"}

