// ---------- locations ----------

type locationReq struct {
	LocationID      string     `json:"locationId"`
	Name            string     `json:"name"`
	Coordinate      Coordinate `json:"coordinate"`
	CoverageKm      *float64   `json:"coverageKm"`
	HandlingMinutes *int       `json:"handlingMinutes"`
	Active          bool       `json:"active"`
	Functions       []string   `json:"functions"`
}

func validateLocationReq(req *locationReq) *apiError {
	if req.Name == "" {
		return errAPI(400, "invalid_json", "name required")
	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		return errAPI(400, "invalid_coordinate", "coordinate out of range")
	}
	if req.CoverageKm != nil && (*req.CoverageKm <= 0 || *req.CoverageKm > 5) {
		return errAPI(400, "invalid_node_coverage", "coverageKm must be in (0,5]")
	}
	if req.HandlingMinutes != nil && (*req.HandlingMinutes < 0 || *req.HandlingMinutes > 1440) {
		return errAPI(400, "invalid_handling_time", "handlingMinutes must be in [0,1440]")
	}
	for _, f := range req.Functions {
		if !validFunctions[f] {
			return errAPI(400, "invalid_location_function", "unknown function "+f)
		}
	}
	return nil
}

func statesFromFunctions(fns []string) FunctionStates {
	var fs FunctionStates
	for _, f := range fns {
		switch f {
		case "collection_point":
			fs.CollectionPoint = true
		case "transfer_point":
			fs.TransferPoint = true
		case "hub":
			fs.Hub = true
		case "laboratory":
			fs.Laboratory = true
		}
	}
	return fs
}

func (a *App) createLocation(w http.ResponseWriter, r *http.Request) {
