		return
	}
	if e := validateLocationReq(&req); e != nil {
		writeErr(w, e)
		return
	}
	var out *Location
	e := a.mutate(func(st *State) *apiError {
		cov := 5.0
		if req.CoverageKm != nil {
			cov = *req.CoverageKm
		}
		hm := 0
		if req.HandlingMinutes != nil {
			hm = *req.HandlingMinutes
		}
		l := &Location{
			LocationID: newUUID(), Name: req.Name, Coordinate: req.Coordinate,
			CoverageKm: cov, HandlingMinutes: hm, Active: req.Active,
			Functions: statesFromFunctions(req.Functions),
			Capacity: Capacity{CapacityUnits: 10, AvailableUnits: 10, CooledCapacityUnits: 5, CooledAvailableUnits: 5},
			AcceptedTypes: map[string]bool{},
		}
		st.Locations[l.LocationID] = l
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		a.auditLocked(getUser(r).UserID, roleOf(r), "location.create", "location", l.LocationID, true, map[string]interface{}{"name": l.Name})
		a.emitLocked("location.created", "location", l.LocationID, locationJSON(l), nil)
		out = l
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 201, locationJSON(out))
