func (a *App) createSampleType(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req sampleTypeReq
	if !decodeBody(w, r, &req) {
		return
	}
	var out *SampleType
	e := a.mutate(func(st *State) *apiError {
		if req.Name == "" || req.ContainerType == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
			return errAPI(400, "invalid_handling_rule", "name, containerType and temperature range required")
		}
		if *req.TemperatureMinC > *req.TemperatureMaxC {
			return errAPI(400, "invalid_handling_rule", "temperatureMinC must be <= temperatureMaxC")
		}
		batching := true
		if req.BatchingAllowed != nil {
			batching = *req.BatchingAllowed
		}
		t := &SampleType{
			SampleTypeID: newUUID(), Name: req.Name, ContainerType: req.ContainerType,
			TemperatureMinC: *req.TemperatureMinC, TemperatureMaxC: *req.TemperatureMaxC,
			IncompatibleSampleTypes: req.IncompatibleSampleTypes,
			RequiredQualification: req.RequiredQualification, BatchingAllowed: batching,
		}
		if req.QualifiedCollectorRequired != nil {
			t.QualifiedCollectorRequired = *req.QualifiedCollectorRequired
		}
		if req.RequiresCooledRoute != nil {
			t.RequiresCooledRoute = *req.RequiresCooledRoute
		}
		st.SampleTypes[t.SampleTypeID] = t
		a.auditLocked(getUser(r).UserID, roleOf(r), "sample_type.create", "sample_type", t.SampleTypeID, true, map[string]interface{}{"name": t.Name})
