	e := a.mutate(func(st *State) *apiError {
		t := st.SampleTypes[req.SampleTypeID]
		if t == nil {
			return errAPI(404, "not_found", "sample type not found")
		}
		if req.TemperatureMinC != nil && req.TemperatureMaxC != nil && *req.TemperatureMinC > *req.TemperatureMaxC {
			return errAPI(400, "invalid_handling_rule", "temperatureMinC must be <= temperatureMaxC")
		}
		if req.QualifiedCollectorRequired != nil {
			t.QualifiedCollectorRequired = *req.QualifiedCollectorRequired
		}
		if req.RequiredQualification != "" {
			t.RequiredQualification = req.RequiredQualification
		}
		if req.ContainerType != "" {
			t.ContainerType = req.ContainerType
		}
		if req.TemperatureMinC != nil {
			t.TemperatureMinC = *req.TemperatureMinC
		}
		if req.TemperatureMaxC != nil {
			t.TemperatureMaxC = *req.TemperatureMaxC
		}
		if req.IncompatibleSampleTypes != nil {
			t.IncompatibleSampleTypes = req.IncompatibleSampleTypes
		}
		if req.RequiresCooledRoute != nil {
			t.RequiresCooledRoute = *req.RequiresCooledRoute
		}
