		if l == nil {
			return errAPI(404, "not_found", "location not found")
		}
		l.Active = req.Active
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		a.auditLocked(getUser(r).UserID, roleOf(r), "location.set_status", "location", l.LocationID, true, map[string]interface{}{"active": req.Active})
		a.emitLocked("location.status", "location", l.LocationID, map[string]interface{}{"active": req.Active}, nil)
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{"locationId": req.LocationID, "active": req.Active})
}

func (a *App) setLocationFunctionStatus(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req struct {
		LocationID string `json:"locationId"`
		Function   string `json:"function"`
		Active     bool   `json:"active"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if !validFunctions[req.Function] {
		writeErr(w, errAPI(400, "invalid_location_function", "unknown function"))
		return
	}
	var fns FunctionStates
	e := a.mutate(func(st *State) *apiError {
		l := st.Locations[req.LocationID]
		if l == nil {
			return errAPI(404, "not_found", "location not found")
		}
		switch req.Function {
		case "collection_point":
			l.Functions.CollectionPoint = req.Active
		case "transfer_point":
			l.Functions.TransferPoint = req.Active
		case "hub":
			l.Functions.Hub = req.Active
		case "laboratory":
			l.Functions.Laboratory = req.Active
		}
		fns = l.Functions
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		a.auditLocked(getUser(r).UserID, roleOf(r), "location.set_function_status", "location", l.LocationID, true, map[string]interface{}{"function": req.Function, "active": req.Active})
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{
		"locationId": req.LocationID, "function": req.Function, "active": req.Active,
		"functions": funcJSON(fns),
	})
}

// ---------- connections ----------

func (a *App) createConnection(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req struct {
		FromLocationID string  `json:"fromLocationId"`
		ToLocationID   string  `json:"toLocationId"`
		TravelMinutes  int     `json:"travelMinutes"`
		CostUnits      float64 `json:"costUnits"`
		Cooled         bool    `json:"cooled"`
		Active         bool    `json:"active"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out *Connection
	e := a.mutate(func(st *State) *apiError {
		if req.TravelMinutes < 1 || req.CostUnits < 0 {
			return errAPI(400, "invalid_connection", "invalid travel time or cost")
		}
		if st.Locations[req.FromLocationID] == nil || st.Locations[req.ToLocationID] == nil {
			return errAPI(400, "invalid_connection", "unknown endpoint location")
		}
		c := &Connection{
			ConnectionID: newUUID(), FromLocationID: req.FromLocationID, ToLocationID: req.ToLocationID,
			TravelMinutes: req.TravelMinutes, CostUnits: req.CostUnits, Cooled: req.Cooled, Active: req.Active,
			Capacity: Capacity{CapacityUnits: 10, AvailableUnits: 10, CooledCapacityUnits: 5, CooledAvailableUnits: 5},
		}
		st.Connections[c.ConnectionID] = c
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		a.auditLocked(getUser(r).UserID, roleOf(r), "connection.create", "connection", c.ConnectionID, true, nil)
		out = c
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 201, map[string]interface{}{
		"connectionId": out.ConnectionID, "fromLocationId": out.FromLocationID,
		"toLocationId": out.ToLocationID, "travelMinutes": out.TravelMinutes,
		"costUnits": out.CostUnits, "cooled": out.Cooled, "active": out.Active,
	})
}

func (a *App) setConnectionStatus(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req struct {
		ConnectionID string `json:"connectionId"`
		Active       bool   `json:"active"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	e := a.mutate(func(st *State) *apiError {
		c := st.Connections[req.ConnectionID]
		if c == nil {
			return errAPI(404, "not_found", "connection not found")
		}
		c.Active = req.Active
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		a.auditLocked(getUser(r).UserID, roleOf(r), "connection.set_status", "connection", c.ConnectionID, true, map[string]interface{}{"active": req.Active})
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{"connectionId": req.ConnectionID, "active": req.Active})
}

// ---------- sample types ----------

type sampleTypeReq struct {
	SampleTypeID               string   `json:"sampleTypeId"`
	Name                       string   `json:"name"`
	QualifiedCollectorRequired *bool    `json:"qualifiedCollectorRequired"`
	RequiredQualification      string   `json:"requiredQualification"`
	ContainerType              string   `json:"containerType"`
	TemperatureMinC            *float64 `json:"temperatureMinC"`
	TemperatureMaxC            *float64 `json:"temperatureMaxC"`
	IncompatibleSampleTypes    []string `json:"incompatibleSampleTypes"`
	RequiresCooledRoute        *bool    `json:"requiresCooledRoute"`
	BatchingAllowed            *bool    `json:"batchingAllowed"`
}

func (a *App) createSampleType(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req sampleTypeReq
	if !decodeBody(w, r, &req) {
		return
	}
	var out *SampleType
	e := a.mutate(func(st *State) *apiError {
		if req.Name == "" || req.ContainerType == "" || req.TemperatureMinC == nil || req.TemperatureMaxC == nil {
			return errAPI(400, "invalid_handling_rule", "name, containerType and temperature range required")
		}
		if *req.TemperatureMinC > *req.TemperatureMaxC {
			return errAPI(400, "invalid_handling_rule", "temperatureMinC must be <= temperatureMaxC")
		}
		batching := true
		if req.BatchingAllowed != nil {
			batching = *req.BatchingAllowed
		}
		t := &SampleType{
			SampleTypeID: newUUID(), Name: req.Name, ContainerType: req.ContainerType,
			TemperatureMinC: *req.TemperatureMinC, TemperatureMaxC: *req.TemperatureMaxC,
			IncompatibleSampleTypes: req.IncompatibleSampleTypes,
			RequiredQualification: req.RequiredQualification, BatchingAllowed: batching,
		}
		if req.QualifiedCollectorRequired != nil {
			t.QualifiedCollectorRequired = *req.QualifiedCollectorRequired
		}
		if req.RequiresCooledRoute != nil {
			t.RequiresCooledRoute = *req.RequiresCooledRoute
		}
		st.SampleTypes[t.SampleTypeID] = t
		a.auditLocked(getUser(r).UserID, roleOf(r), "sample_type.create", "sample_type", t.SampleTypeID, true, map[string]interface{}{"name": t.Name})
		out = t
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 201, sampleTypeJSON(out))
}

func (a *App) updateSampleType(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req sampleTypeReq
	if !decodeBody(w, r, &req) {
		return
	}
	var out *SampleType
	e := a.mutate(func(st *State) *apiError {
		t := st.SampleTypes[req.SampleTypeID]
		if t == nil {
			return errAPI(404, "not_found", "sample type not found")
		}
		if req.TemperatureMinC != nil && req.TemperatureMaxC != nil && *req.TemperatureMinC > *req.TemperatureMaxC {
			return errAPI(400, "invalid_handling_rule", "temperatureMinC must be <= temperatureMaxC")
		}
		if req.QualifiedCollectorRequired != nil {
			t.QualifiedCollectorRequired = *req.QualifiedCollectorRequired
		}
		if req.RequiredQualification != "" {
			t.RequiredQualification = req.RequiredQualification
		}
		if req.ContainerType != "" {
			t.ContainerType = req.ContainerType
		}
		if req.TemperatureMinC != nil {
			t.TemperatureMinC = *req.TemperatureMinC
		}
		if req.TemperatureMaxC != nil {
			t.TemperatureMaxC = *req.TemperatureMaxC
		}
		if req.IncompatibleSampleTypes != nil {
			t.IncompatibleSampleTypes = req.IncompatibleSampleTypes
		}
		if req.RequiresCooledRoute != nil {
			t.RequiresCooledRoute = *req.RequiresCooledRoute
		}
		if req.BatchingAllowed != nil {
			t.BatchingAllowed = *req.BatchingAllowed
		}
		a.auditLocked(getUser(r).UserID, roleOf(r), "sample_type.update", "sample_type", t.SampleTypeID, true, nil)
		out = t
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 201, sampleTypeJSON(out))
}

// ---------- capacity & acceptance ----------

func (a *App) configureCapacity(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator", "dispatcher", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		ResourceID          string `json:"resourceId"`
		CapacityUnits       int    `json:"capacityUnits"`
		CooledCapacityUnits *int   `json:"cooledCapacityUnits"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	cooled := 0
	if req.CooledCapacityUnits != nil {
		cooled = *req.CooledCapacityUnits
	}
	if req.CapacityUnits < 0 || cooled < 0 {
		writeErr(w, errAPI(400, "invalid_capacity", "capacity must be >= 0"))
		return
	}
	e := a.mutate(func(st *State) *apiError {
		var cap *Capacity
		if l := st.Locations[req.ResourceID]; l != nil {
			// node handlers / lab operators may only configure their own location
			role := roleOf(r)
			if role == "node_handler" || role == "laboratory_team" {
				if getUser(r).AssignedLocationID != l.LocationID {
					return errAPI(403, "forbidden", "not assigned to this location")
				}
			}
			cap = &l.Capacity
		} else if c := st.Connections[req.ResourceID]; c != nil {
			if roleOf(r) == "node_handler" || roleOf(r) == "laboratory_team" {
				return errAPI(403, "forbidden", "cannot configure connection capacity")
			}
			cap = &c.Capacity
		} else {
			return errAPI(400, "invalid_capacity", "unknown resource")
		}
		if req.CapacityUnits < cap.ReservedUnits || cooled < cap.CooledReservedUnits {
			return errAPI(409, "capacity_reserved", "capacity below currently reserved units")
		}
		cap.CapacityUnits = req.CapacityUnits
		cap.CooledCapacityUnits = cooled
		cap.AvailableUnits = cap.CapacityUnits - cap.ReservedUnits
		cap.CooledAvailableUnits = cap.CooledCapacityUnits - cap.CooledReservedUnits
		a.auditLocked(getUser(r).UserID, roleOf(r), "capacity.configure", "resource", req.ResourceID, true, map[string]interface{}{"capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled})
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{
		"resourceId": req.ResourceID, "capacityUnits": req.CapacityUnits, "cooledCapacityUnits": cooled,
	})
}

func (a *App) configureLaboratoryAcceptance(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	var req struct {
		LaboratoryID string `json:"laboratoryId"`
		SampleTypeID string `json:"sampleTypeId"`
		Accepts      bool   `json:"accepts"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var accID string
	e := a.mutate(func(st *State) *apiError {
		l := st.Locations[req.LaboratoryID]
		if l == nil || !l.Functions.Laboratory {
			return errAPI(400, "invalid_acceptance", "laboratory not found")
		}
		if st.SampleTypes[req.SampleTypeID] == nil {
			return errAPI(400, "invalid_acceptance", "sample type not found")
		}
		key := req.LaboratoryID + "|" + req.SampleTypeID
		acc := st.Acceptances[key]
		if acc == nil {
			acc = &Acceptance{AcceptanceID: newUUID(), LaboratoryID: req.LaboratoryID, SampleTypeID: req.SampleTypeID}
			st.Acceptances[key] = acc
		}
		acc.Accepts = req.Accepts
		l.AcceptedTypes[req.SampleTypeID] = req.Accepts
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		a.auditLocked(getUser(r).UserID, roleOf(r), "laboratory.configure_acceptance", "laboratory", req.LaboratoryID, true, map[string]interface{}{"sampleTypeId": req.SampleTypeID, "accepts": req.Accepts})
		accID = acc.AcceptanceID
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{"acceptanceId": accID, "accepts": req.Accepts})
}

func (a *App) setWorkerAvailability(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator", "dispatcher", "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		WorkerID      string `json:"workerId"`
		Available     bool   `json:"available"`
		CapacityUnits *int   `json:"capacityUnits"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.CapacityUnits != nil && *req.CapacityUnits < 0 {
		writeErr(w, errAPI(400, "invalid_capacity", "capacityUnits must be >= 0"))
		return
	}
	e := a.mutate(func(st *State) *apiError {
		u := st.Users[req.WorkerID]
		if u == nil {
			return errAPI(404, "not_found", "worker not found")
		}
		role := roleOf(r)
		if role != "administrator" && role != "dispatcher" && getUser(r).UserID != u.UserID {
			return errAPI(403, "forbidden", "cannot change another worker's availability")
		}
		u.Available = req.Available
		if req.CapacityUnits != nil {
			u.CapacityUnits = *req.CapacityUnits
		}
		a.auditLocked(getUser(r).UserID, role, "worker.set_availability", "user", u.UserID, true, map[string]interface{}{"available": req.Available})
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	cu := 0
	if req.CapacityUnits != nil {
		cu = *req.CapacityUnits
	}
	writeData(w, 200, map[string]interface{}{"workerId": req.WorkerID, "available": req.Available, "capacityUnits": cu})
}

