// ---------- auth ----------

func (a *App) authenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var sess *Session
	var user *User
	e := a.mutate(func(st *State) *apiError {
		for _, u := range st.Users {
			if u.Username == req.Username {
				user = u
				break
			}
		}
		if user == nil || user.PasswordHash != hashPassword(req.Password) || !user.Active {
			a.auditLocked("", "", "auth.login", "user", req.Username, false, nil)
			return errAPI(401, "invalid_credentials", "invalid username or password")
		}
		sess = &Session{Token: newUUID() + newUUID(), UserID: user.UserID, CreatedAt: time.Now().UTC()}
		if len(user.Roles) == 1 {
			sess.ActiveRole = user.Roles[0]
		}
		st.Sessions[sess.Token] = sess
		a.auditLocked(user.UserID, sess.ActiveRole, "auth.login", "user", user.UserID, true, nil)
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{
		"sessionToken": sess.Token, "userId": user.UserID, "roles": user.Roles, "activeRole": sess.ActiveRole,
	})
}

func (a *App) selectActiveRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if !validRoles[req.Role] {
		writeErr(w, errAPI(400, "invalid_role", "unknown role"))
		return
	}
	u := getUser(r)
	sess := getSession(r)
	e := a.mutate(func(st *State) *apiError {
		if !containsStr(u.Roles, req.Role) {
			return errAPI(403, "role_not_held", "role not held by user")
		}
		sess.ActiveRole = req.Role
		a.auditLocked(u.UserID, req.Role, "auth.select_role", "user", u.UserID, true, map[string]interface{}{"role": req.Role})
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{"activeRole": req.Role, "roles": u.Roles})
}

// ---------- serviceability ----------

type serviceabilityReq struct {
	Origin               Coordinate `json:"origin"`
	OriginType           string     `json:"originType"`
	OriginNodeID         string     `json:"originNodeId"`
	SampleTypeID         string     `json:"sampleTypeId"`
	RequestedAt          string     `json:"requestedAt"`
	DeliveryDeadline     string     `json:"deliveryDeadline"`
	EarliestCollectionAt string     `json:"earliestCollectionAt"`
	LatestCollectionAt   string     `json:"latestCollectionAt"`
}

func (req *serviceabilityReq) validate() (earliest, latest, deadline time.Time, aerr *apiError) {
	if req.OriginType == "" {
		req.OriginType = "home"
	}
	if req.OriginType != "home" && req.OriginType != "clinic" && req.OriginType != "node" {
		aerr = errAPI(400, "invalid_origin_type", "originType must be home, clinic or node")
		return
	}
	if req.Origin.Latitude < -90 || req.Origin.Latitude > 90 || req.Origin.Longitude < -180 || req.Origin.Longitude > 180 {
		aerr = errAPI(400, "invalid_origin", "origin coordinate out of range")
		return
	}
	var ok bool
	deadline, ok = parseTime(req.DeliveryDeadline)
	if !ok {
		aerr = errAPI(400, "invalid_deadline", "deliveryDeadline must be RFC3339")
		return
	}
	earliest = time.Now().UTC()
	if req.EarliestCollectionAt != "" {
		earliest, ok = parseTime(req.EarliestCollectionAt)
		if !ok {
			aerr = errAPI(400, "invalid_time", "earliestCollectionAt must be RFC3339")
			return
		}
	}
	latest = deadline
	if req.LatestCollectionAt != "" {
