		if svc.Serviceable {
			smp.Serviceability = "serviceable"
		} else {
			smp.Serviceability = "unserviceable"
			smp.ServiceabilityReason = svc.Reason
		}
		if presealed {
			smp.Sealed = true
			smp.SealedAt = &now
			smp.Status = "sealed"
			smp.CurrentHolderID = me.UserID
			loc := me.LatestLocation
			if loc == nil {
				c := req.Origin
				loc = &c
			}
			smp.LatestLocation = loc
			smp.LocationRecordedAt = &now
		}
		st.Requests[rq.RequestID] = rq
		st.Samples[smp.SampleID] = smp
		var j *Journey
		if svc.Serviceable {
			j = a.buildJourneyLocked(st, smp, svc, presealed)
			if !presealed {
				smp.Status = "awaiting_collection"
			}
		}
		a.auditLocked(me.UserID, roleOf(r), "request.create", "request", rq.RequestID, true, map[string]interface{}{"sampleId": smp.SampleID, "serviceable": svc.Serviceable, "reason": svc.Reason})
		a.auditLocked(me.UserID, roleOf(r), "sample.create", "sample", smp.SampleID, true, map[string]interface{}{"requestId": rq.RequestID})
		a.emitLocked("sample.created", "sample", smp.SampleID, map[string]interface{}{"requestId": rq.RequestID, "status": smp.Status}, nil)
		actives := smp.ActiveAssignmentIDs
		if actives == nil {
			actives = []string{}
		}
		out = map[string]interface{}{
			"requestId": rq.RequestID, "sampleId": smp.SampleID,
			"serviceability": smp.Serviceability, "activeAssignmentIds": actives,
			"earliestCollectionAt": timeStr(earliest), "latestCollectionAt": timeStr(latest),
			"alreadySealed": presealed, "originType": smp.OriginType,
		}
		if smp.ServiceabilityReason != "" {
			out["serviceabilityReason"] = smp.ServiceabilityReason
		}
		if j != nil {
			out["journeyId"] = j.JourneyID
			out["targetLaboratoryId"] = j.TargetLaboratoryID
		}
		return nil
	}))
	if e != nil {
		return 0, nil, e
	}
	return 201, out, nil
}

func s(f func(*State) *apiError) func(*State) *apiError { return f }

