func (a *App) splitJourney(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[req.JourneyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
			return e
		}
		if len(req.SampleIDs) == 0 {
			return errAPI(400, "invalid_split", "sampleIds required")
		}
		for _, sid := range req.SampleIDs {
			if !containsStr(j.SampleIDs, sid) {
				return errAPI(400, "invalid_split", "sample "+sid+" is not in this journey")
			}
		}
		nj := &Journey{
			JourneyID: newUUID(), ParentJourneyID: j.JourneyID, PlanVersion: 1,
			RouteMode: j.RouteMode, Status: j.Status, SampleIDs: append([]string{}, req.SampleIDs...),
			Stops: j.Stops, TargetLaboratoryID: j.TargetLaboratoryID,
			EstimatedDeliveryAt: j.EstimatedDeliveryAt, TotalCostUnits: j.TotalCostUnits,
			CreatedAt: time.Now().UTC(),
		}
		st.Journeys[nj.JourneyID] = nj
		remaining := []string{}
		for _, sid := range j.SampleIDs {
			if containsStr(req.SampleIDs, sid) {
				if smp := st.Samples[sid]; smp != nil {
					smp.ActiveJourneyID = nj.JourneyID
				}
			} else {
				remaining = append(remaining, sid)
			}
		}
		j.SampleIDs = remaining
		j.PlanVersion++
		a.auditLocked(getUser(r).UserID, roleOf(r), "journey.split", "journey", j.JourneyID, true, map[string]interface{}{"newJourneyId": nj.JourneyID, "sampleIds": req.SampleIDs})
		a.emitLocked("journey.split", "journey", j.JourneyID, map[string]interface{}{"newJourneyId": nj.JourneyID}, nil)
		out = map[string]interface{}{
			"journeyId": j.JourneyID, "newJourneyId": nj.JourneyID,
			"planVersion": j.PlanVersion, "status": j.Status,
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

func (a *App) mergeJourneys(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[req.JourneyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
			return e
		}
		// validate compatibility of merged samples
		var types []*SampleType
		for _, sid := range append(append([]string{}, j.SampleIDs...), req.SampleIDs...) {
			smp := st.Samples[sid]
			if smp == nil {
				return errAPI(400, "invalid_merge", "unknown sample "+sid)
			}
			if smp.Status == "received" || smp.Status == "cancelled" {
				return errAPI(409, "incompatible_batch", "sample "+sid+" is finished")
			}
			t := st.SampleTypes[smp.SampleTypeID]
			if t != nil {
				if !t.BatchingAllowed {
					return errAPI(409, "incompatible_batch", "sample type "+t.Name+" must not be batched")
				}
				types = append(types, t)
			}
		}
		for _, t := range types {
			for _, other := range types {
				if containsStr(t.IncompatibleSampleTypes, other.Name) {
					return errAPI(409, "incompatible_batch", "samples are not allowed to travel together")
				}
			}
		}
		for _, sid := range req.SampleIDs {
			if containsStr(j.SampleIDs, sid) {
				continue
			}
			smp := st.Samples[sid]
			if old := st.Journeys[smp.ActiveJourneyID]; old != nil && old.JourneyID != j.JourneyID {
				old.SampleIDs = removeStr(old.SampleIDs, sid)
			}
			j.SampleIDs = append(j.SampleIDs, sid)
			smp.ActiveJourneyID = j.JourneyID
		}
		j.RouteMode = "batched"
		j.PlanVersion++
		a.auditLocked(getUser(r).UserID, roleOf(r), "journey.merge", "journey", j.JourneyID, true, map[string]interface{}{"sampleIds": req.SampleIDs})
		a.emitLocked("journey.merged", "journey", j.JourneyID, map[string]interface{}{"sampleIds": j.SampleIDs}, nil)
		out = map[string]interface{}{"journeyId": j.JourneyID, "planVersion": j.PlanVersion, "status": j.Status}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

func (a *App) editActivePlan(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		ChangeType          string `json:"changeType"`
		Details             struct {
			AssignmentID string `json:"assignmentId"`
			WorkerID     string `json:"workerId"`
			Reason       string `json:"reason"`
		} `json:"details"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[req.JourneyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
			return e
		}
		smp := st.Samples[j.SampleIDs[0]]
		switch req.ChangeType {
		case "replace_worker":
			as := st.Assignments[req.Details.AssignmentID]
			if as == nil {
				return errAPI(404, "not_found", "assignment not found")
			}
			if as.Status == "completed" {
				return errAPI(409, "plan_conflict", "cannot rewrite completed work")
			}
			as.WorkerID = ""
			as.Status = "pending"
			as.DeclinedBy = nil
			a.offerAssignmentLocked(st, as, smp)
		case "reroute":
			a.replanJourneyLocked(st, j, true)
		case "cancel_work":
			as := st.Assignments[req.Details.AssignmentID]
			if as == nil {
				return errAPI(404, "not_found", "assignment not found")
			}
			if as.Status == "completed" {
				return errAPI(409, "plan_conflict", "cannot rewrite completed work")
			}
			as.Status = "cancelled"
			as.OfferedTo = ""
		case "replan", "split", "merge", "cancel":
			a.replanJourneyLocked(st, j, true)
		default:
			return errAPI(400, "invalid_change_type", "unknown changeType")
		}
		j.PlanVersion++
		a.auditLocked(getUser(r).UserID, roleOf(r), "journey.edit_plan", "journey", j.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
		a.emitLocked("journey.plan_edited", "journey", j.JourneyID, map[string]interface{}{"changeType": req.ChangeType}, nil)
		out = map[string]interface{}{"journeyId": j.JourneyID, "planVersion": j.PlanVersion, "status": j.Status}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// ---------- disruption ----------

func (a *App) reportDisruption(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		ResourceType string `json:"resourceType"`
		ResourceID   string `json:"resourceId"`
		Reason       string `json:"reason"`
		OccurredAt   string `json:"occurredAt"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	switch req.ResourceType {
	case "worker", "node", "route", "laboratory", "capacity_pool":
	default:
		writeErr(w, errAPI(400, "invalid_disruption", "invalid resourceType"))
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		occ := time.Now().UTC()
		if t, ok := parseTime(req.OccurredAt); ok {
			occ = t
		}
		d := &Disruption{DisruptionID: newUUID(), ResourceType: req.ResourceType, ResourceID: req.ResourceID, Reason: req.Reason, OccurredAt: occ}
		st.Disruptions[d.DisruptionID] = d
		switch req.ResourceType {
		case "worker":
			if u := st.Users[req.ResourceID]; u != nil {
				u.Available = false
			}
		case "node", "laboratory":
			if l := st.Locations[req.ResourceID]; l != nil {
				l.Active = false
			}
		case "route":
			if c := st.Connections[req.ResourceID]; c != nil {
				c.Active = false
			}
		case "capacity_pool":
			if l := st.Locations[req.ResourceID]; l != nil {
				l.Capacity.CapacityUnits = l.Capacity.ReservedUnits
				l.Capacity.CooledCapacityUnits = l.Capacity.CooledReservedUnits
			} else if c := st.Connections[req.ResourceID]; c != nil {
				c.Capacity.CapacityUnits = c.Capacity.ReservedUnits
				c.Capacity.CooledCapacityUnits = c.Capacity.CooledReservedUnits
			}
		}
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		// replan affected unfinished journeys
		affected := 0
		replStatus := "replanned"
		for _, j := range st.Journeys {
			if j.Status != "planned" && j.Status != "in_progress" && j.Status != "exception" {
				continue
			}
			hit := false
			switch req.ResourceType {
			case "worker":
				for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegAssignmentIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
					for _, id := range ids {
						if as := st.Assignments[id]; as != nil && (as.WorkerID == req.ResourceID || as.OfferedTo == req.ResourceID) && as.Status != "completed" && as.Status != "cancelled" {
							hit = true
						}
					}
				}
			case "node", "laboratory", "capacity_pool":
				for _, s := range j.Stops {
					if s.LocationID == req.ResourceID && s.CompletedAt == nil {
						hit = true
					}
				}
				if j.TargetLaboratoryID == req.ResourceID {
					hit = true
				}
			case "route":
				c := st.Connections[req.ResourceID]
				if c != nil {
					for _, aid := range j.LegAssignmentIDs {
						if as := st.Assignments[aid]; as != nil && as.Status != "completed" && as.Status != "cancelled" &&
							as.FromLocationID == c.FromLocationID && as.ToLocationID == c.ToLocationID {
							hit = true
						}
					}
				}
			}
			if !hit {
				continue
			}
			affected++
			if !a.replanJourneyLocked(st, j, true) {
				replStatus = "failed"
			}
		}
		a.auditLocked(getUser(r).UserID, roleOf(r), "disruption.report", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason, "affectedJourneys": affected})
		a.emitLocked("disruption.reported", req.ResourceType, req.ResourceID, map[string]interface{}{"affectedJourneys": affected}, nil)
		out = map[string]interface{}{
			"disruptionId": d.DisruptionID, "replanStatus": replStatus, "affectedJourneys": affected,
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// ---------- audit search ----------

func (a *App) searchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	q := r.URL.Query()
	limit := 50
	if v := q.Get("limit"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n >= 1 && n <= 200 {
			limit = n
		}
	}
	offset := 0
	if v := q.Get("offset"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n >= 0 {
			offset = n
		}
	}
	var items []interface{}
	var total int
	a.read(func(st *State) {
		var matched []AuditEntry
		for _, e := range st.Audit {
			if v := q.Get("actorId"); v != "" && e.ActorID != v {
				continue
			}
			if v := q.Get("role"); v != "" && e.Role != v {
				continue
			}
			if v := q.Get("action"); v != "" && e.Action != v {
				continue
			}
			if v := q.Get("entityType"); v != "" && e.EntityType != v {
				continue
			}
			if v := q.Get("entityId"); v != "" && e.EntityID != v {
				continue
			}
			if v := q.Get("success"); v != "" {
				if (v == "true") != e.Success {
					continue
				}
			}
			if v := q.Get("from"); v != "" {
				if t, ok := parseTime(v); ok && e.OccurredAt.Before(t) {
					continue
				}
			}
			if v := q.Get("to"); v != "" {
				if t, ok := parseTime(v); ok && e.OccurredAt.After(t) {
					continue
				}
			}
			matched = append(matched, e)
		}
		total = len(matched)
		sort.Slice(matched, func(i, j int) bool { return matched[i].OccurredAt.After(matched[j].OccurredAt) })
		items = []interface{}{}
		for i := offset; i < len(matched) && len(items) < limit; i++ {
			items = append(items, auditJSON(matched[i]))
		}
	})
	writeData(w, 200, map[string]interface{}{"items": items, "total": total, "limit": limit, "offset": offset})
}

// ---------- serviceability snapshot ----------

func (a *App) readServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	var out map[string]interface{}
	a.read(func(st *State) {
		regions := []interface{}{}
		for _, rg := range st.Serviceability.Regions {
			regions = append(regions, map[string]interface{}{
				"locationId": rg.LocationID, "name": rg.Name,
				"latitude": rg.Latitude, "longitude": rg.Longitude, "coverageKm": rg.CoverageKm,
			})
		}
		out = map[string]interface{}{
			"version": st.Serviceability.Version, "status": st.Serviceability.Status,
			"computedAt": timeStr(st.Serviceability.ComputedAt),
			"networkRevision": st.Serviceability.NetworkRevision,
			"regions": regions, "activeCollectionPointCount": st.Serviceability.ActiveCollectionPointCount,
		}
	})
	writeData(w, 200, out)
}

