func (a *App) readJourneyPlan(w http.ResponseWriter, r *http.Request) {
	journeyID := r.PathValue("journeyId")
	u := getUser(r)
	role := roleOf(r)
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[journeyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		switch role {
		case "dispatcher", "administrator":
			out = journeyPlanJSON(st, j)
		case "requester":
			owns := false
			for _, sid := range j.SampleIDs {
				if smp := st.Samples[sid]; smp != nil && smp.RequesterID == u.UserID {
					owns = true
				}
			}
			if !owns {
				return errAPI(403, "forbidden", "journey not visible to you")
			}
			out = requesterJourneyPlanJSON(st, j)
		default:
			involved := false
			for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegAssignmentIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
				for _, id := range ids {
					if as := st.Assignments[id]; as != nil && (as.WorkerID == u.UserID || as.OfferedTo == u.UserID) {
						involved = true
					}
				}
			}
			if !involved {
				return errAPI(403, "forbidden", "journey not visible to you")
			}
			out = workerJourneyPlanJSON(st, j, u.UserID)
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// ---------- plan version guard ----------

func checkPlanVersion(j *Journey, expected int) *apiError {
	if expected < 1 {
		return errAPI(400, "invalid_plan_version", "expectedPlanVersion must be >= 1")
	}
	if expected != j.PlanVersion {
		return errAPI(409, "stale_plan", "plan version does not match the current journey plan")
	}
	return nil
}

// cancelUnfinishedLocked cancels unfinished assignments of a journey and releases capacity.
func (a *App) cancelUnfinishedLocked(st *State, j *Journey) {
	for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegAssignmentIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
		for _, id := range ids {
			as := st.Assignments[id]
			if as == nil {
				continue
			}
			if as.Status == "pending" || as.Status == "accepted" || as.Status == "in_progress" {
				as.Status = "cancelled"
				as.OfferedTo = ""
				for _, sid := range j.SampleIDs {
					if smp := st.Samples[sid]; smp != nil {
						smp.ActiveAssignmentIDs = removeStr(smp.ActiveAssignmentIDs, id)
					}
				}
			}
		}
	}
}

func (a *App) cancelJourney(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[req.JourneyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
			return e
		}
		a.cancelUnfinishedLocked(st, j)
		j.Status = "cancelled"
		j.PlanVersion++
		for _, sid := range j.SampleIDs {
			if smp := st.Samples[sid]; smp != nil && smp.Status != "received" {
				smp.Status = "cancelled"
				smp.ActiveJourneyID = ""
				releaseCapacityLocked(st, journeyRoute(st, j), st.SampleTypes[smp.SampleTypeID] != nil && st.SampleTypes[smp.SampleTypeID].RequiresCooledRoute, 1)
			}
		}
		a.auditLocked(getUser(r).UserID, roleOf(r), "journey.cancel", "journey", j.JourneyID, true, map[string]interface{}{"reason": req.Reason})
		a.emitLocked("journey.cancelled", "journey", j.JourneyID, map[string]interface{}{}, nil)
		out = map[string]interface{}{"journeyId": j.JourneyID, "status": "cancelled", "planVersion": j.PlanVersion}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// replanJourneyLocked rebuilds unfinished legs of a journey from its entry node.
// Completed work is preserved. Returns true if a valid replacement plan was made.
func (a *App) replanJourneyLocked(st *State, j *Journey, excludeUnavailable bool) bool {
	if len(j.SampleIDs) == 0 {
		return false
	}
	smp := st.Samples[j.SampleIDs[0]]
	if smp == nil || smp.Status == "received" {
		return false
	}
	stype := st.SampleTypes[smp.SampleTypeID]
	cooled := stype != nil && stype.RequiresCooledRoute
	// release old reservations, cancel unfinished legs
	oldRoute := journeyRoute(st, j)
	releaseCapacityLocked(st, oldRoute, cooled, 1)
	a.cancelUnfinishedLocked(st, j)
	// determine where the sample currently is: last completed leg destination or entry
	entry := ""
	for _, aid := range j.LegAssignmentIDs {
		as := st.Assignments[aid]
		if as != nil && as.Status == "completed" {
			entry = as.ToLocationID
		}
	}
	if entry == "" {
		entry = nearestCollectionPoint(st, smp.Origin).LocationIDOrEmpty()
	}
	if entry == "" {
		j.Status = "exception"
		j.ReplanStatus = "failed"
		return false
	}
	accept := func(lid string) bool { return labAccepts(st, st.Locations[lid], smp.SampleTypeID) }
	var r *routeResult
	if accept(entry) {
		r = &routeResult{Found: true, LocationIDs: []string{entry}}
	} else {
		r = findRoute(st, entry, cooled, accept)
	}
	if r == nil || !routeHasCapacity(st, r, cooled) {
		j.Status = "exception"
		j.ReplanStatus = "failed"
		reserveCapacityLocked(st, oldRoute, cooled, 1)
		return false
	}
	est := time.Now().UTC().Add(time.Duration(r.TravelMinutes) * time.Minute)
	if est.After(smp.DeliveryDeadline) {
		j.Status = "expired"
		j.ReplanStatus = "failed"
		smp.Status = "expired"
		smp.ExceptionReason = "delivery_deadline_exceeded"
		reserveCapacityLocked(st, oldRoute, cooled, 1)
		return false
	}
	j.PlanVersion++
	j.ReplacementPlanID = newUUID()
	j.ReplanStatus = "replanned"
	j.TargetLaboratoryID = r.LocationIDs[len(r.LocationIDs)-1]
	smp.TargetLaboratoryID = j.TargetLaboratoryID
	reserveCapacityLocked(st, r, cooled, 1)
	// build new legs from entry
	j.LegAssignmentIDs = nil
	j.NodeAssignmentIDs = nil
	j.LaboratoryAssignmentIDs = nil
	seq := 0
	for _, aid := range st.assignmentOrder(j) {
		_ = aid
	}
	locs := r.LocationIDs
	if len(locs) == 1 {
		la := &Assignment{
			AssignmentID: newUUID(), Kind: "laboratory", JourneyID: j.JourneyID,
			SampleID: smp.SampleID, SampleIDs: []string{smp.SampleID},
			Sequence: 100, Status: "pending", LaboratoryID: locs[0], CreatedAt: time.Now().UTC(),
		}
		st.Assignments[la.AssignmentID] = la
		j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, la.AssignmentID)
		smp.ActiveAssignmentIDs = append(smp.ActiveAssignmentIDs, la.AssignmentID)
	} else {
		for i := 0; i < len(locs)-1; i++ {
			seq++
			ta := &Assignment{
				AssignmentID: newUUID(), Kind: "transport", JourneyID: j.JourneyID,
				SampleID: smp.SampleID, SampleIDs: []string{smp.SampleID},
				Sequence: 100 + seq, Status: "pending",
				FromLocationID: locs[i], ToLocationID: locs[i+1], CreatedAt: time.Now().UTC(),
			}
			st.Assignments[ta.AssignmentID] = ta
			j.LegAssignmentIDs = append(j.LegAssignmentIDs, ta.AssignmentID)
			smp.ActiveAssignmentIDs = append(smp.ActiveAssignmentIDs, ta.AssignmentID)
			if i < len(locs)-2 {
				na := &Assignment{
					AssignmentID: newUUID(), Kind: "node", JourneyID: j.JourneyID,
					SampleID: smp.SampleID, SampleIDs: []string{smp.SampleID},
					Sequence: 100 + seq, Status: "pending", NodeID: locs[i+1], CreatedAt: time.Now().UTC(),
				}
				st.Assignments[na.AssignmentID] = na
				j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, na.AssignmentID)
				smp.ActiveAssignmentIDs = append(smp.ActiveAssignmentIDs, na.AssignmentID)
			}
		}
		la := &Assignment{
			AssignmentID: newUUID(), Kind: "laboratory", JourneyID: j.JourneyID,
			SampleID: smp.SampleID, SampleIDs: []string{smp.SampleID},
			Sequence: 200, Status: "pending", LaboratoryID: locs[len(locs)-1], CreatedAt: time.Now().UTC(),
		}
		st.Assignments[la.AssignmentID] = la
		j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, la.AssignmentID)
		smp.ActiveAssignmentIDs = append(smp.ActiveAssignmentIDs, la.AssignmentID)
	}
	// completed legs remain in CompletedLegIDs; offer next
	if smp.Status == "exception" || smp.Status == "expired" {
		smp.Status = "in_transit"
		smp.ExceptionReason = ""
	}
	a.offerNextAfterLocked(st, j, smp)
	return true
}

