package main

import (
	"net/http"
	"sort"
	"strconv"
	"time"
)

// ---------- operations state ----------

func (a *App) readOperationsState(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		a.expireOffersLocked(st)
		samples := []interface{}{}
		for _, smp := range st.Samples {
			m := sampleWorkItemJSON(st, smp)
			m["origin"] = smp.Origin
			m["originType"] = smp.OriginType
			m["deliveryDeadline"] = timeStr(smp.DeliveryDeadline)
			m["earliestCollectionAt"] = timeStr(smp.EarliestCollectionAt)
			m["latestCollectionAt"] = timeStr(smp.LatestCollectionAt)
			m["requestedAt"] = timeStr(smp.RequestedAt)
			m["containerType"] = smp.ContainerType
			m["temperatureMinC"] = smp.TemperatureMinC
			m["temperatureMaxC"] = smp.TemperatureMaxC
			m["requesterId"] = smp.RequesterID
			if smp.ExceptionReason != "" {
				m["exceptionReason"] = smp.ExceptionReason
			}
			if smp.TargetLaboratoryID != "" {
				m["targetLaboratoryId"] = smp.TargetLaboratoryID
			}
			samples = append(samples, m)
		}
		workers := []interface{}{}
		for _, u := range st.Users {
			isWorker := false
			for _, ro := range u.Roles {
				if ro == "collection_professional" || ro == "delivery_partner" || ro == "node_handler" || ro == "laboratory_team" {
					isWorker = true
				}
			}
			if !isWorker {
				continue
			}
			m := map[string]interface{}{
				"userId": u.UserID, "username": u.Username, "roles": u.Roles,
				"active": u.Active, "available": u.Available,
				"capacityUnits": u.CapacityUnits,
				"activeAssignments": workerActiveAssignmentCount(st, u.UserID),
				"locationStale": isStale(u.LocationRecordedAt),
			}
			if u.LatestLocation != nil {
				m["latestLocation"] = u.LatestLocation
			}
			if u.LocationRecordedAt != nil {
				m["locationRecordedAt"] = timeStr(*u.LocationRecordedAt)
			}
			if u.AssignedLocationID != "" {
				m["assignedLocationId"] = u.AssignedLocationID
			}
			workers = append(workers, m)
		}
		locations := []interface{}{}
		for _, l := range st.Locations {
			m := locationJSON(l)
			m["capacity"] = capJSON(l.Capacity)
			accepted := []string{}
			for tid, ok := range l.AcceptedTypes {
				if ok {
					accepted = append(accepted, tid)
				}
			}
			m["acceptedSampleTypeIds"] = accepted
			locations = append(locations, m)
		}
		connections := []interface{}{}
		for _, c := range st.Connections {
			connections = append(connections, map[string]interface{}{
				"connectionId": c.ConnectionID, "fromLocationId": c.FromLocationID,
				"toLocationId": c.ToLocationID, "travelMinutes": c.TravelMinutes,
				"costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active,
				"capacity": capJSON(c.Capacity),
			})
		}
		journeys := []interface{}{}
		for _, j := range st.Journeys {
			journeys = append(journeys, journeyPlanJSON(st, j))
		}
		sampleTypes := []interface{}{}
		for _, t := range st.SampleTypes {
			sampleTypes = append(sampleTypes, sampleTypeJSON(t))
		}
		exceptions := []interface{}{}
		for _, smp := range st.Samples {
			if smp.Status == "exception" || smp.Status == "expired" {
				exceptions = append(exceptions, map[string]interface{}{
					"sampleId": smp.SampleID, "status": smp.Status, "reason": smp.ExceptionReason,
				})
			}
		}
		out = map[string]interface{}{
			"samples": samples, "workers": workers, "locations": locations,
			"connections": connections, "journeys": journeys, "sampleTypes": sampleTypes,
			"exceptions": exceptions, "stateVersion": st.StateVersion,
			"networkRevision": st.NetworkRevision,
			"serviceabilityVersion": st.Serviceability.Version,
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// ---------- sample state & lifecycle ----------

func sampleVisibleTo(st *State, smp *Sample, u *User, role string) bool {
	switch role {
	case "dispatcher", "administrator":
		return true
	case "requester":
		return smp.RequesterID == u.UserID
	default:
		if smp.CurrentHolderID == u.UserID {
			return true
		}
		for _, id := range smp.ActiveAssignmentIDs {
			if as := st.Assignments[id]; as != nil && (as.WorkerID == u.UserID || as.OfferedTo == u.UserID) {
				return true
			}
		}
		for _, id := range smp.CompletedLegIDs {
			if as := st.Assignments[id]; as != nil && as.WorkerID == u.UserID {
				return true
			}
		}
		return false
	}
}

func sampleTimeline(st *State, smp *Sample) []interface{} {
	ids := map[string]bool{smp.SampleID: true, smp.RequestID: true}
	if smp.ActiveJourneyID != "" {
		ids[smp.ActiveJourneyID] = true
	}
	for _, as := range st.Assignments {
		if as.SampleID == smp.SampleID {
			ids[as.AssignmentID] = true
		}
	}
	for _, h := range st.Handoffs {
		if h.SampleID == smp.SampleID {
			ids[h.HandoffID] = true
		}
	}
	var entries []AuditEntry
	for _, e := range st.Audit {
		if ids[e.EntityID] {
			entries = append(entries, e)
		}
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].OccurredAt.Before(entries[j].OccurredAt) })
	out := []interface{}{}
	for i, e := range entries {
		m := timeline(e.ActorID, e.Role, e.Action, e.EntityType, e.EntityID, e.OccurredAt, e.Details)
		m["eventId"] = i + 1
		m["success"] = e.Success
		out = append(out, m)
	}
	return out
}

