package main

import (
	"net/http"
	"sort"
	"strconv"
	"time"
)

// ---------- operations state ----------

func (a *App) readOperationsState(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		a.expireOffersLocked(st)
		samples := []interface{}{}
		for _, smp := range st.Samples {
			m := sampleWorkItemJSON(st, smp)
			m["origin"] = smp.Origin
			m["originType"] = smp.OriginType
			m["deliveryDeadline"] = timeStr(smp.DeliveryDeadline)
			m["earliestCollectionAt"] = timeStr(smp.EarliestCollectionAt)
			m["latestCollectionAt"] = timeStr(smp.LatestCollectionAt)
			m["requestedAt"] = timeStr(smp.RequestedAt)
			m["containerType"] = smp.ContainerType
			m["temperatureMinC"] = smp.TemperatureMinC
			m["temperatureMaxC"] = smp.TemperatureMaxC
			m["requesterId"] = smp.RequesterID
			if smp.ExceptionReason != "" {
				m["exceptionReason"] = smp.ExceptionReason
			}
			if smp.TargetLaboratoryID != "" {
				m["targetLaboratoryId"] = smp.TargetLaboratoryID
			}
			samples = append(samples, m)
		}
		workers := []interface{}{}
		for _, u := range st.Users {
			isWorker := false
			for _, ro := range u.Roles {
				if ro == "collection_professional" || ro == "delivery_partner" || ro == "node_handler" || ro == "laboratory_team" {
					isWorker = true
				}
			}
			if !isWorker {
				continue
			}
			m := map[string]interface{}{
				"userId": u.UserID, "username": u.Username, "roles": u.Roles,
				"active": u.Active, "available": u.Available,
				"capacityUnits": u.CapacityUnits,
				"activeAssignments": workerActiveAssignmentCount(st, u.UserID),
				"locationStale": isStale(u.LocationRecordedAt),
			}
			if u.LatestLocation != nil {
				m["latestLocation"] = u.LatestLocation
			}
			if u.LocationRecordedAt != nil {
				m["locationRecordedAt"] = timeStr(*u.LocationRecordedAt)
			}
			if u.AssignedLocationID != "" {
				m["assignedLocationId"] = u.AssignedLocationID
			}
			workers = append(workers, m)
		}
		locations := []interface{}{}
		for _, l := range st.Locations {
			m := locationJSON(l)
			m["capacity"] = capJSON(l.Capacity)
			accepted := []string{}
			for tid, ok := range l.AcceptedTypes {
				if ok {
					accepted = append(accepted, tid)
				}
			}
			m["acceptedSampleTypeIds"] = accepted
			locations = append(locations, m)
		}
		connections := []interface{}{}
		for _, c := range st.Connections {
			connections = append(connections, map[string]interface{}{
				"connectionId": c.ConnectionID, "fromLocationId": c.FromLocationID,
				"toLocationId": c.ToLocationID, "travelMinutes": c.TravelMinutes,
				"costUnits": c.CostUnits, "cooled": c.Cooled, "active": c.Active,
				"capacity": capJSON(c.Capacity),
			})
		}
		journeys := []interface{}{}
		for _, j := range st.Journeys {
			journeys = append(journeys, journeyPlanJSON(st, j))
		}
		sampleTypes := []interface{}{}
		for _, t := range st.SampleTypes {
			sampleTypes = append(sampleTypes, sampleTypeJSON(t))
		}
		exceptions := []interface{}{}
		for _, smp := range st.Samples {
			if smp.Status == "exception" || smp.Status == "expired" {
				exceptions = append(exceptions, map[string]interface{}{
					"sampleId": smp.SampleID, "status": smp.Status, "reason": smp.ExceptionReason,
				})
			}
		}
		out = map[string]interface{}{
			"samples": samples, "workers": workers, "locations": locations,
			"connections": connections, "journeys": journeys, "sampleTypes": sampleTypes,
			"exceptions": exceptions, "stateVersion": st.StateVersion,
			"networkRevision": st.NetworkRevision,
			"serviceabilityVersion": st.Serviceability.Version,
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// ---------- sample state & lifecycle ----------

func sampleVisibleTo(st *State, smp *Sample, u *User, role string) bool {
	switch role {
	case "dispatcher", "administrator":
		return true
	case "requester":
		return smp.RequesterID == u.UserID
	default:
		if smp.CurrentHolderID == u.UserID {
			return true
		}
		for _, id := range smp.ActiveAssignmentIDs {
			if as := st.Assignments[id]; as != nil && (as.WorkerID == u.UserID || as.OfferedTo == u.UserID) {
				return true
			}
		}
		for _, id := range smp.CompletedLegIDs {
			if as := st.Assignments[id]; as != nil && as.WorkerID == u.UserID {
				return true
			}
		}
		return false
	}
}

func sampleTimeline(st *State, smp *Sample) []interface{} {
	ids := map[string]bool{smp.SampleID: true, smp.RequestID: true}
	if smp.ActiveJourneyID != "" {
		ids[smp.ActiveJourneyID] = true
	}
	for _, as := range st.Assignments {
		if as.SampleID == smp.SampleID {
			ids[as.AssignmentID] = true
		}
	}
	for _, h := range st.Handoffs {
		if h.SampleID == smp.SampleID {
			ids[h.HandoffID] = true
		}
	}
	var entries []AuditEntry
	for _, e := range st.Audit {
		if ids[e.EntityID] {
			entries = append(entries, e)
		}
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].OccurredAt.Before(entries[j].OccurredAt) })
	out := []interface{}{}
	for i, e := range entries {
		m := timeline(e.ActorID, e.Role, e.Action, e.EntityType, e.EntityID, e.OccurredAt, e.Details)
		m["eventId"] = i + 1
		m["success"] = e.Success
		out = append(out, m)
	}
	return out
}

func (a *App) readSampleState(w http.ResponseWriter, r *http.Request) {
	sampleID := r.PathValue("sampleId")
	u := getUser(r)
	var out map[string]interface{}
	found := false
	e := a.mutate(func(st *State) *apiError {
		a.expireOffersLocked(st)
		smp := st.Samples[sampleID]
		if smp == nil {
			return errAPI(404, "not_found", "sample not found")
		}
		if !sampleVisibleTo(st, smp, u, roleOf(r)) {
			return errAPI(403, "forbidden", "sample not visible to you")
		}
		found = true
		m := sampleWorkItemJSON(st, smp)
		m["origin"] = smp.Origin
		m["originType"] = smp.OriginType
		m["deliveryDeadline"] = timeStr(smp.DeliveryDeadline)
		m["earliestCollectionAt"] = timeStr(smp.EarliestCollectionAt)
		m["latestCollectionAt"] = timeStr(smp.LatestCollectionAt)
		m["requestedAt"] = timeStr(smp.RequestedAt)
		m["containerType"] = smp.ContainerType
		m["temperatureMinC"] = smp.TemperatureMinC
		m["temperatureMaxC"] = smp.TemperatureMaxC
		m["timeline"] = sampleTimeline(st, smp)
		if smp.ExceptionReason != "" {
			m["exceptionReason"] = smp.ExceptionReason
		}
		if smp.TargetLaboratoryID != "" {
			m["targetLaboratoryId"] = smp.TargetLaboratoryID
		}
		if smp.ReceivedLaboratoryID != "" {
			m["receivedLaboratoryId"] = smp.ReceivedLaboratoryID
		}
		if smp.ReceivedAt != nil {
			m["receivedAt"] = timeStr(*smp.ReceivedAt)
		}
		out = m
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	_ = found
	writeData(w, 200, out)
}

func (a *App) readSampleLifecycle(w http.ResponseWriter, r *http.Request) {
	sampleID := r.PathValue("sampleId")
	u := getUser(r)
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		smp := st.Samples[sampleID]
		if smp == nil {
			return errAPI(404, "not_found", "sample not found")
		}
		if !sampleVisibleTo(st, smp, u, roleOf(r)) {
			return errAPI(403, "forbidden", "sample not visible to you")
		}
		tl := sampleTimeline(st, smp)
		var current map[string]interface{}
		if len(tl) > 0 {
			current = tl[len(tl)-1].(map[string]interface{})
		} else {
			current = timeline("", "", "sample.create", "sample", smp.SampleID, smp.CreatedAt, nil)
			current["eventId"] = 1
		}
		out = map[string]interface{}{
			"sampleId": smp.SampleID, "current": current, "timeline": tl,
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// ---------- journey plan read ----------

func (a *App) readJourneyPlan(w http.ResponseWriter, r *http.Request) {
	journeyID := r.PathValue("journeyId")
	u := getUser(r)
	role := roleOf(r)
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[journeyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		switch role {
		case "dispatcher", "administrator":
			out = journeyPlanJSON(st, j)
		case "requester":
			owns := false
			for _, sid := range j.SampleIDs {
				if smp := st.Samples[sid]; smp != nil && smp.RequesterID == u.UserID {
					owns = true
				}
			}
			if !owns {
				return errAPI(403, "forbidden", "journey not visible to you")
			}
			out = requesterJourneyPlanJSON(st, j)
		default:
			involved := false
			for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegAssignmentIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
				for _, id := range ids {
					if as := st.Assignments[id]; as != nil && (as.WorkerID == u.UserID || as.OfferedTo == u.UserID) {
						involved = true
					}
				}
			}
			if !involved {
				return errAPI(403, "forbidden", "journey not visible to you")
			}
			out = workerJourneyPlanJSON(st, j, u.UserID)
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// ---------- plan version guard ----------

func checkPlanVersion(j *Journey, expected int) *apiError {
	if expected < 1 {
		return errAPI(400, "invalid_plan_version", "expectedPlanVersion must be >= 1")
	}
	if expected != j.PlanVersion {
		return errAPI(409, "stale_plan", "plan version does not match the current journey plan")
	}
	return nil
}

// cancelUnfinishedLocked cancels unfinished assignments of a journey and releases capacity.
func (a *App) cancelUnfinishedLocked(st *State, j *Journey) {
	for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegAssignmentIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
		for _, id := range ids {
			as := st.Assignments[id]
			if as == nil {
				continue
			}
			if as.Status == "pending" || as.Status == "accepted" || as.Status == "in_progress" {
				as.Status = "cancelled"
				as.OfferedTo = ""
				for _, sid := range j.SampleIDs {
					if smp := st.Samples[sid]; smp != nil {
						smp.ActiveAssignmentIDs = removeStr(smp.ActiveAssignmentIDs, id)
					}
				}
			}
		}
	}
}

func (a *App) cancelJourney(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[req.JourneyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
			return e
		}
		a.cancelUnfinishedLocked(st, j)
		j.Status = "cancelled"
		j.PlanVersion++
		for _, sid := range j.SampleIDs {
			if smp := st.Samples[sid]; smp != nil && smp.Status != "received" {
				smp.Status = "cancelled"
				smp.ActiveJourneyID = ""
				releaseCapacityLocked(st, journeyRoute(st, j), st.SampleTypes[smp.SampleTypeID] != nil && st.SampleTypes[smp.SampleTypeID].RequiresCooledRoute, 1)
			}
		}
		a.auditLocked(getUser(r).UserID, roleOf(r), "journey.cancel", "journey", j.JourneyID, true, map[string]interface{}{"reason": req.Reason})
		a.emitLocked("journey.cancelled", "journey", j.JourneyID, map[string]interface{}{}, nil)
		out = map[string]interface{}{"journeyId": j.JourneyID, "status": "cancelled", "planVersion": j.PlanVersion}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// replanJourneyLocked rebuilds unfinished legs of a journey from its entry node.
// Completed work is preserved. Returns true if a valid replacement plan was made.
func (a *App) replanJourneyLocked(st *State, j *Journey, excludeUnavailable bool) bool {
	if len(j.SampleIDs) == 0 {
		return false
	}
	smp := st.Samples[j.SampleIDs[0]]
	if smp == nil || smp.Status == "received" {
		return false
	}
	stype := st.SampleTypes[smp.SampleTypeID]
	cooled := stype != nil && stype.RequiresCooledRoute
	// release old reservations, cancel unfinished legs
	oldRoute := journeyRoute(st, j)
	releaseCapacityLocked(st, oldRoute, cooled, 1)
	a.cancelUnfinishedLocked(st, j)
	// determine where the sample currently is: last completed leg destination or entry
	entry := ""
	for _, aid := range j.LegAssignmentIDs {
		as := st.Assignments[aid]
		if as != nil && as.Status == "completed" {
			entry = as.ToLocationID
		}
	}
	if entry == "" {
		entry = nearestCollectionPoint(st, smp.Origin).LocationIDOrEmpty()
	}
	if entry == "" {
		j.Status = "exception"
		j.ReplanStatus = "failed"
		return false
	}
	accept := func(lid string) bool { return labAccepts(st, st.Locations[lid], smp.SampleTypeID) }
	var r *routeResult
	if accept(entry) {
		r = &routeResult{Found: true, LocationIDs: []string{entry}}
	} else {
		r = findRoute(st, entry, cooled, accept)
	}
	if r == nil || !routeHasCapacity(st, r, cooled) {
		j.Status = "exception"
		j.ReplanStatus = "failed"
		reserveCapacityLocked(st, oldRoute, cooled, 1)
		return false
	}
	est := time.Now().UTC().Add(time.Duration(r.TravelMinutes) * time.Minute)
	if est.After(smp.DeliveryDeadline) {
		j.Status = "expired"
		j.ReplanStatus = "failed"
		smp.Status = "expired"
		smp.ExceptionReason = "delivery_deadline_exceeded"
		reserveCapacityLocked(st, oldRoute, cooled, 1)
		return false
	}
	j.PlanVersion++
	j.ReplacementPlanID = newUUID()
	j.ReplanStatus = "replanned"
	j.TargetLaboratoryID = r.LocationIDs[len(r.LocationIDs)-1]
	smp.TargetLaboratoryID = j.TargetLaboratoryID
	reserveCapacityLocked(st, r, cooled, 1)
	// build new legs from entry
	j.LegAssignmentIDs = nil
	j.NodeAssignmentIDs = nil
	j.LaboratoryAssignmentIDs = nil
	seq := 0
	locs := r.LocationIDs
	if len(locs) == 1 {
		la := &Assignment{
			AssignmentID: newUUID(), Kind: "laboratory", JourneyID: j.JourneyID,
			SampleID: smp.SampleID, SampleIDs: []string{smp.SampleID},
			Sequence: 100, Status: "pending", LaboratoryID: locs[0], CreatedAt: time.Now().UTC(),
		}
		st.Assignments[la.AssignmentID] = la
		j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, la.AssignmentID)
		smp.ActiveAssignmentIDs = append(smp.ActiveAssignmentIDs, la.AssignmentID)
	} else {
		for i := 0; i < len(locs)-1; i++ {
			seq++
			ta := &Assignment{
				AssignmentID: newUUID(), Kind: "transport", JourneyID: j.JourneyID,
				SampleID: smp.SampleID, SampleIDs: []string{smp.SampleID},
				Sequence: 100 + seq, Status: "pending",
				FromLocationID: locs[i], ToLocationID: locs[i+1], CreatedAt: time.Now().UTC(),
			}
			st.Assignments[ta.AssignmentID] = ta
			j.LegAssignmentIDs = append(j.LegAssignmentIDs, ta.AssignmentID)
			smp.ActiveAssignmentIDs = append(smp.ActiveAssignmentIDs, ta.AssignmentID)
			if i < len(locs)-2 {
				na := &Assignment{
					AssignmentID: newUUID(), Kind: "node", JourneyID: j.JourneyID,
					SampleID: smp.SampleID, SampleIDs: []string{smp.SampleID},
					Sequence: 100 + seq, Status: "pending", NodeID: locs[i+1], CreatedAt: time.Now().UTC(),
				}
				st.Assignments[na.AssignmentID] = na
				j.NodeAssignmentIDs = append(j.NodeAssignmentIDs, na.AssignmentID)
				smp.ActiveAssignmentIDs = append(smp.ActiveAssignmentIDs, na.AssignmentID)
			}
		}
		la := &Assignment{
			AssignmentID: newUUID(), Kind: "laboratory", JourneyID: j.JourneyID,
			SampleID: smp.SampleID, SampleIDs: []string{smp.SampleID},
			Sequence: 200, Status: "pending", LaboratoryID: locs[len(locs)-1], CreatedAt: time.Now().UTC(),
		}
		st.Assignments[la.AssignmentID] = la
		j.LaboratoryAssignmentIDs = append(j.LaboratoryAssignmentIDs, la.AssignmentID)
		smp.ActiveAssignmentIDs = append(smp.ActiveAssignmentIDs, la.AssignmentID)
	}
	// completed legs remain in CompletedLegIDs; offer next
	if smp.Status == "exception" || smp.Status == "expired" {
		smp.Status = "in_transit"
		smp.ExceptionReason = ""
	}
	a.offerNextAfterLocked(st, j, smp)
	return true
}

func (l *Location) LocationIDOrEmpty() string {
	if l == nil {
		return ""
	}
	return l.LocationID
}

func (a *App) rerouteJourney(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[req.JourneyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
			return e
		}
		ok := a.replanJourneyLocked(st, j, true)
		a.auditLocked(getUser(r).UserID, roleOf(r), "journey.reroute", "journey", j.JourneyID, ok, map[string]interface{}{"reason": req.Reason})
		a.emitLocked("journey.rerouted", "journey", j.JourneyID, map[string]interface{}{"status": j.Status}, nil)
		out = map[string]interface{}{
			"journeyId": j.JourneyID, "planVersion": j.PlanVersion,
			"status": j.Status, "replanStatus": j.ReplanStatus,
		}
		if j.ReplacementPlanID != "" {
			out["replacementPlanId"] = j.ReplacementPlanID
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

func (a *App) splitJourney(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[req.JourneyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
			return e
		}
		if len(req.SampleIDs) == 0 {
			return errAPI(400, "invalid_split", "sampleIds required")
		}
		for _, sid := range req.SampleIDs {
			if !containsStr(j.SampleIDs, sid) {
				return errAPI(400, "invalid_split", "sample "+sid+" is not in this journey")
			}
		}
		nj := &Journey{
			JourneyID: newUUID(), ParentJourneyID: j.JourneyID, PlanVersion: 1,
			RouteMode: j.RouteMode, Status: j.Status, SampleIDs: append([]string{}, req.SampleIDs...),
			Stops: j.Stops, TargetLaboratoryID: j.TargetLaboratoryID,
			EstimatedDeliveryAt: j.EstimatedDeliveryAt, TotalCostUnits: j.TotalCostUnits,
			CreatedAt: time.Now().UTC(),
		}
		st.Journeys[nj.JourneyID] = nj
		remaining := []string{}
		for _, sid := range j.SampleIDs {
			if containsStr(req.SampleIDs, sid) {
				if smp := st.Samples[sid]; smp != nil {
					smp.ActiveJourneyID = nj.JourneyID
				}
			} else {
				remaining = append(remaining, sid)
			}
		}
		j.SampleIDs = remaining
		j.PlanVersion++
		a.auditLocked(getUser(r).UserID, roleOf(r), "journey.split", "journey", j.JourneyID, true, map[string]interface{}{"newJourneyId": nj.JourneyID, "sampleIds": req.SampleIDs})
		a.emitLocked("journey.split", "journey", j.JourneyID, map[string]interface{}{"newJourneyId": nj.JourneyID}, nil)
		out = map[string]interface{}{
			"journeyId": j.JourneyID, "newJourneyId": nj.JourneyID,
			"planVersion": j.PlanVersion, "status": j.Status,
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

func (a *App) mergeJourneys(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[req.JourneyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
			return e
		}
		// validate compatibility of merged samples
		var types []*SampleType
		for _, sid := range append(append([]string{}, j.SampleIDs...), req.SampleIDs...) {
			smp := st.Samples[sid]
			if smp == nil {
				return errAPI(400, "invalid_merge", "unknown sample "+sid)
			}
			if smp.Status == "received" || smp.Status == "cancelled" {
				return errAPI(409, "incompatible_batch", "sample "+sid+" is finished")
			}
			t := st.SampleTypes[smp.SampleTypeID]
			if t != nil {
				if !t.BatchingAllowed {
					return errAPI(409, "incompatible_batch", "sample type "+t.Name+" must not be batched")
				}
				types = append(types, t)
			}
		}
		for _, t := range types {
			for _, other := range types {
				if containsStr(t.IncompatibleSampleTypes, other.Name) {
					return errAPI(409, "incompatible_batch", "samples are not allowed to travel together")
				}
			}
		}
		for _, sid := range req.SampleIDs {
			if containsStr(j.SampleIDs, sid) {
				continue
			}
			smp := st.Samples[sid]
			if old := st.Journeys[smp.ActiveJourneyID]; old != nil && old.JourneyID != j.JourneyID {
				old.SampleIDs = removeStr(old.SampleIDs, sid)
			}
			j.SampleIDs = append(j.SampleIDs, sid)
			smp.ActiveJourneyID = j.JourneyID
		}
		j.RouteMode = "batched"
		j.PlanVersion++
		a.auditLocked(getUser(r).UserID, roleOf(r), "journey.merge", "journey", j.JourneyID, true, map[string]interface{}{"sampleIds": req.SampleIDs})
		a.emitLocked("journey.merged", "journey", j.JourneyID, map[string]interface{}{"sampleIds": j.SampleIDs}, nil)
		out = map[string]interface{}{"journeyId": j.JourneyID, "planVersion": j.PlanVersion, "status": j.Status}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

func (a *App) editActivePlan(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		ChangeType          string `json:"changeType"`
		Details             struct {
			AssignmentID string `json:"assignmentId"`
			WorkerID     string `json:"workerId"`
			Reason       string `json:"reason"`
		} `json:"details"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		j := st.Journeys[req.JourneyID]
		if j == nil {
			return errAPI(404, "not_found", "journey not found")
		}
		if e := checkPlanVersion(j, req.ExpectedPlanVersion); e != nil {
			return e
		}
		smp := st.Samples[j.SampleIDs[0]]
		switch req.ChangeType {
		case "replace_worker":
			as := st.Assignments[req.Details.AssignmentID]
			if as == nil {
				return errAPI(404, "not_found", "assignment not found")
			}
			if as.Status == "completed" {
				return errAPI(409, "plan_conflict", "cannot rewrite completed work")
			}
			as.WorkerID = ""
			as.Status = "pending"
			as.DeclinedBy = nil
			a.offerAssignmentLocked(st, as, smp)
		case "reroute":
			a.replanJourneyLocked(st, j, true)
		case "cancel_work":
			as := st.Assignments[req.Details.AssignmentID]
			if as == nil {
				return errAPI(404, "not_found", "assignment not found")
			}
			if as.Status == "completed" {
				return errAPI(409, "plan_conflict", "cannot rewrite completed work")
			}
			as.Status = "cancelled"
			as.OfferedTo = ""
		case "replan", "split", "merge", "cancel":
			a.replanJourneyLocked(st, j, true)
		default:
			return errAPI(400, "invalid_change_type", "unknown changeType")
		}
		j.PlanVersion++
		a.auditLocked(getUser(r).UserID, roleOf(r), "journey.edit_plan", "journey", j.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
		a.emitLocked("journey.plan_edited", "journey", j.JourneyID, map[string]interface{}{"changeType": req.ChangeType}, nil)
		out = map[string]interface{}{"journeyId": j.JourneyID, "planVersion": j.PlanVersion, "status": j.Status}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// ---------- disruption ----------

func (a *App) reportDisruption(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		ResourceType string `json:"resourceType"`
		ResourceID   string `json:"resourceId"`
		Reason       string `json:"reason"`
		OccurredAt   string `json:"occurredAt"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	switch req.ResourceType {
	case "worker", "node", "route", "laboratory", "capacity_pool":
	default:
		writeErr(w, errAPI(400, "invalid_disruption", "invalid resourceType"))
		return
	}
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		occ := time.Now().UTC()
		if t, ok := parseTime(req.OccurredAt); ok {
			occ = t
		}
		d := &Disruption{DisruptionID: newUUID(), ResourceType: req.ResourceType, ResourceID: req.ResourceID, Reason: req.Reason, OccurredAt: occ}
		st.Disruptions[d.DisruptionID] = d
		switch req.ResourceType {
		case "worker":
			if u := st.Users[req.ResourceID]; u != nil {
				u.Available = false
			}
		case "node", "laboratory":
			if l := st.Locations[req.ResourceID]; l != nil {
				l.Active = false
			}
		case "route":
			if c := st.Connections[req.ResourceID]; c != nil {
				c.Active = false
			}
		case "capacity_pool":
			if l := st.Locations[req.ResourceID]; l != nil {
				l.Capacity.CapacityUnits = l.Capacity.ReservedUnits
				l.Capacity.CooledCapacityUnits = l.Capacity.CooledReservedUnits
			} else if c := st.Connections[req.ResourceID]; c != nil {
				c.Capacity.CapacityUnits = c.Capacity.ReservedUnits
				c.Capacity.CooledCapacityUnits = c.Capacity.CooledReservedUnits
			}
		}
		st.NetworkRevision++
		recomputeServiceabilitySnapshot(st)
		// replan affected unfinished journeys
		affected := 0
		replStatus := "replanned"
		for _, j := range st.Journeys {
			if j.Status != "planned" && j.Status != "in_progress" && j.Status != "exception" {
				continue
			}
			hit := false
			switch req.ResourceType {
			case "worker":
				for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegAssignmentIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
					for _, id := range ids {
						if as := st.Assignments[id]; as != nil && (as.WorkerID == req.ResourceID || as.OfferedTo == req.ResourceID) && as.Status != "completed" && as.Status != "cancelled" {
							hit = true
						}
					}
				}
			case "node", "laboratory", "capacity_pool":
				for _, s := range j.Stops {
					if s.LocationID == req.ResourceID && s.CompletedAt == nil {
						hit = true
					}
				}
				if j.TargetLaboratoryID == req.ResourceID {
					hit = true
				}
			case "route":
				c := st.Connections[req.ResourceID]
				if c != nil {
					for _, aid := range j.LegAssignmentIDs {
						if as := st.Assignments[aid]; as != nil && as.Status != "completed" && as.Status != "cancelled" &&
							as.FromLocationID == c.FromLocationID && as.ToLocationID == c.ToLocationID {
							hit = true
						}
					}
				}
			}
			if !hit {
				continue
			}
			affected++
			if !a.replanJourneyLocked(st, j, true) {
				replStatus = "failed"
			}
		}
		a.auditLocked(getUser(r).UserID, roleOf(r), "disruption.report", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason, "affectedJourneys": affected})
		a.emitLocked("disruption.reported", req.ResourceType, req.ResourceID, map[string]interface{}{"affectedJourneys": affected}, nil)
		out = map[string]interface{}{
			"disruptionId": d.DisruptionID, "replanStatus": replStatus, "affectedJourneys": affected,
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, out)
}

// ---------- audit search ----------

func (a *App) searchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	q := r.URL.Query()
	limit := 50
	if v := q.Get("limit"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n >= 1 && n <= 200 {
			limit = n
		}
	}
	offset := 0
	if v := q.Get("offset"); v != "" {
		if n, err := strconv.Atoi(v); err == nil && n >= 0 {
			offset = n
		}
	}
	var items []interface{}
	var total int
	a.read(func(st *State) {
		var matched []AuditEntry
		for _, e := range st.Audit {
			if v := q.Get("actorId"); v != "" && e.ActorID != v {
				continue
			}
			if v := q.Get("role"); v != "" && e.Role != v {
				continue
			}
			if v := q.Get("action"); v != "" && e.Action != v {
				continue
			}
			if v := q.Get("entityType"); v != "" && e.EntityType != v {
				continue
			}
			if v := q.Get("entityId"); v != "" && e.EntityID != v {
				continue
			}
			if v := q.Get("success"); v != "" {
				if (v == "true") != e.Success {
					continue
				}
			}
			if v := q.Get("from"); v != "" {
				if t, ok := parseTime(v); ok && e.OccurredAt.Before(t) {
					continue
				}
			}
			if v := q.Get("to"); v != "" {
				if t, ok := parseTime(v); ok && e.OccurredAt.After(t) {
					continue
				}
			}
			matched = append(matched, e)
		}
		total = len(matched)
		sort.Slice(matched, func(i, j int) bool { return matched[i].OccurredAt.After(matched[j].OccurredAt) })
		items = []interface{}{}
		for i := offset; i < len(matched) && len(items) < limit; i++ {
			items = append(items, auditJSON(matched[i]))
		}
	})
	writeData(w, 200, map[string]interface{}{"items": items, "total": total, "limit": limit, "offset": offset})
}

// ---------- serviceability snapshot ----------

func (a *App) readServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	var out map[string]interface{}
	a.read(func(st *State) {
		regions := []interface{}{}
		for _, rg := range st.Serviceability.Regions {
			regions = append(regions, map[string]interface{}{
				"locationId": rg.LocationID, "name": rg.Name,
				"latitude": rg.Latitude, "longitude": rg.Longitude, "coverageKm": rg.CoverageKm,
			})
		}
		out = map[string]interface{}{
			"version": st.Serviceability.Version, "status": st.Serviceability.Status,
			"computedAt": timeStr(st.Serviceability.ComputedAt),
			"networkRevision": st.Serviceability.NetworkRevision,
			"regions": regions, "activeCollectionPointCount": st.Serviceability.ActiveCollectionPointCount,
		}
	})
	writeData(w, 200, out)
}

