	deadline := time.Now().Add(time.Duration(waitMs) * time.Millisecond)
	for {
		var evs []interface{}
		var cursor int64
		a.read(func(st *State) {
			evs = []interface{}{}
			cursor = since
			for _, e := range st.Events {
				if e.ID > since {
					evs = append(evs, eventJSON(e))
					cursor = e.ID
				}
			}
		})
		if len(evs) > 0 || waitMs == 0 || time.Now().After(deadline) {
			writeData(w, 200, map[string]interface{}{"events": evs, "cursor": cursor})
			return
		}
		select {
		case <-ch:
		case <-time.After(time.Until(deadline)):
		}
	}
}

