package main

import (
	"net/http"
	"time"
)

// ---------- auth ----------

func (a *App) authenticateUser(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Username string `json:"username"`
		Password string `json:"password"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	var sess *Session
	var user *User
	e := a.mutate(func(st *State) *apiError {
		for _, u := range st.Users {
			if u.Username == req.Username {
				user = u
				break
			}
		}
		if user == nil || user.PasswordHash != hashPassword(req.Password) || !user.Active {
			a.auditLocked("", "", "auth.login", "user", req.Username, false, nil)
			return errAPI(401, "invalid_credentials", "invalid username or password")
		}
		sess = &Session{Token: newUUID() + newUUID(), UserID: user.UserID, CreatedAt: time.Now().UTC()}
		if len(user.Roles) == 1 {
			sess.ActiveRole = user.Roles[0]
		}
		st.Sessions[sess.Token] = sess
		a.auditLocked(user.UserID, sess.ActiveRole, "auth.login", "user", user.UserID, true, nil)
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{
		"sessionToken": sess.Token, "userId": user.UserID, "roles": user.Roles, "activeRole": sess.ActiveRole,
	})
}

func (a *App) selectActiveRole(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role string `json:"role"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if !validRoles[req.Role] {
		writeErr(w, errAPI(400, "invalid_role", "unknown role"))
		return
	}
	u := getUser(r)
	sess := getSession(r)
	e := a.mutate(func(st *State) *apiError {
		if !containsStr(u.Roles, req.Role) {
			return errAPI(403, "role_not_held", "role not held by user")
		}
		sess.ActiveRole = req.Role
		a.auditLocked(u.UserID, req.Role, "auth.select_role", "user", u.UserID, true, map[string]interface{}{"role": req.Role})
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 200, map[string]interface{}{"activeRole": req.Role, "roles": u.Roles})
}

// ---------- serviceability ----------

type serviceabilityReq struct {
	Origin               Coordinate `json:"origin"`
	OriginType           string     `json:"originType"`
	OriginNodeID         string     `json:"originNodeId"`
	SampleTypeID         string     `json:"sampleTypeId"`
	RequestedAt          string     `json:"requestedAt"`
	DeliveryDeadline     string     `json:"deliveryDeadline"`
	EarliestCollectionAt string     `json:"earliestCollectionAt"`
	LatestCollectionAt   string     `json:"latestCollectionAt"`
}

func (req *serviceabilityReq) validate() (earliest, latest, deadline time.Time, aerr *apiError) {
	if req.OriginType == "" {
		req.OriginType = "home"
	}
	if req.OriginType != "home" && req.OriginType != "clinic" && req.OriginType != "node" {
		aerr = errAPI(400, "invalid_origin_type", "originType must be home, clinic or node")
		return
	}
	if req.Origin.Latitude < -90 || req.Origin.Latitude > 90 || req.Origin.Longitude < -180 || req.Origin.Longitude > 180 {
		aerr = errAPI(400, "invalid_origin", "origin coordinate out of range")
		return
	}
	var ok bool
	deadline, ok = parseTime(req.DeliveryDeadline)
	if !ok {
		aerr = errAPI(400, "invalid_deadline", "deliveryDeadline must be RFC3339")
		return
	}
	earliest = time.Now().UTC()
	if req.EarliestCollectionAt != "" {
		earliest, ok = parseTime(req.EarliestCollectionAt)
		if !ok {
			aerr = errAPI(400, "invalid_time", "earliestCollectionAt must be RFC3339")
			return
		}
	}
	latest = deadline
	if req.LatestCollectionAt != "" {
		latest, ok = parseTime(req.LatestCollectionAt)
		if !ok {
			aerr = errAPI(400, "invalid_time", "latestCollectionAt must be RFC3339")
			return
		}
	}
	if latest.Before(earliest) {
		aerr = errAPI(400, "invalid_collection_window", "collection window is inverted")
		return
	}
	if !deadline.After(earliest) {
		aerr = errAPI(400, "invalid_deadline", "delivery deadline must be after collection window start")
		return
	}
	return
}

func (a *App) checkServiceability(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "requester", "dispatcher", "administrator") {
		return
	}
	var req serviceabilityReq
	if !decodeBody(w, r, &req) {
		return
	}
	earliest, _, deadline, aerr := req.validate()
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	var res *serviceabilityResult
	var version int
	var found bool
	e := a.mutate(func(st *State) *apiError {
		if st.SampleTypes[req.SampleTypeID] == nil {
			return errAPI(404, "not_found", "sample type not found")
		}
		res = computeServiceability(st, req.Origin, req.OriginType, req.OriginNodeID, req.SampleTypeID, earliest, deadline)
		version = st.Serviceability.Version
		found = res.Serviceable
		a.auditLocked(getUser(r).UserID, roleOf(r), "serviceability.check", "sample_type", req.SampleTypeID, true, map[string]interface{}{"serviceable": res.Serviceable, "reason": res.Reason})
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	out := map[string]interface{}{
		"serviceable": found, "reason": res.Reason, "serviceabilityVersion": version,
	}
	if res.LaboratoryID != "" {
		out["targetLaboratoryId"] = res.LaboratoryID
	}
	if !res.EstimatedArrival.IsZero() {
		out["estimatedArrivalAt"] = timeStr(res.EstimatedArrival)
	}
	writeData(w, 200, out)
}

// ---------- collection request ----------

type createRequestReq struct {
	RequesterID             string     `json:"requesterId"`
	Origin                  Coordinate `json:"origin"`
	OriginType              string     `json:"originType"`
	OriginNodeID            string     `json:"originNodeId"`
	RequestedAt             string     `json:"requestedAt"`
	DeliveryDeadline        string     `json:"deliveryDeadline"`
	EarliestCollectionAt    string     `json:"earliestCollectionAt"`
	LatestCollectionAt      string     `json:"latestCollectionAt"`
	SampleTypeID            string     `json:"sampleTypeId"`
	ContainerType           string     `json:"containerType"`
	TemperatureMinC         *float64   `json:"temperatureMinC"`
	TemperatureMaxC         *float64   `json:"temperatureMaxC"`
	IncompatibleSampleTypes []string   `json:"incompatibleSampleTypes"`
	IdempotencyKey          string     `json:"idempotencyKey"`
}

func (a *App) createCollectionRequest(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "requester", "dispatcher", "administrator") {
		return
	}
	var req createRequestReq
	if !decodeBody(w, r, &req) {
		return
	}
	body := r.Context().Value(ctxBody).([]byte)
	a.idempotent(w, r, "create_collection_request", body, req.IdempotencyKey, func() (int, interface{}, *apiError) {
		return a.createRequestInner(r, &req, false)
	})
}

func (a *App) ingestPresealedSample(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team", "dispatcher", "administrator") {
		return
	}
	var req createRequestReq
	if !decodeBody(w, r, &req) {
		return
	}
	if req.OriginType == "" {
		req.OriginType = "node"
	}
	if req.OriginType == "home" {
		writeErr(w, errAPI(400, "invalid_origin_type", "pre-sealed samples must originate at a clinic or node"))
		return
	}
	body := r.Context().Value(ctxBody).([]byte)
	a.idempotent(w, r, "ingest_presealed_sample", body, req.IdempotencyKey, func() (int, interface{}, *apiError) {
		return a.createRequestInner(r, &req, true)
	})
}

func (a *App) createRequestInner(r *http.Request, req *createRequestReq, presealed bool) (int, interface{}, *apiError) {
	sreq := serviceabilityReq{
		Origin: req.Origin, OriginType: req.OriginType, OriginNodeID: req.OriginNodeID,
		SampleTypeID: req.SampleTypeID, RequestedAt: req.RequestedAt, DeliveryDeadline: req.DeliveryDeadline,
		EarliestCollectionAt: req.EarliestCollectionAt, LatestCollectionAt: req.LatestCollectionAt,
	}
	earliest, latest, deadline, aerr := sreq.validate()
	if aerr != nil {
		return 0, nil, aerr
	}
	if req.TemperatureMinC == nil || req.TemperatureMaxC == nil || req.ContainerType == "" {
		return 0, nil, errAPI(400, "handling_mismatch", "containerType and temperature range are required")
	}
	me := getUser(r)
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		stype := st.SampleTypes[req.SampleTypeID]
		if stype == nil {
			return errAPI(404, "not_found", "sample type not found")
		}
		// handling attributes must satisfy the sample type rules
		if req.ContainerType != stype.ContainerType ||
			*req.TemperatureMinC < stype.TemperatureMinC || *req.TemperatureMaxC > stype.TemperatureMaxC {
			return errAPI(400, "handling_mismatch", "handling attributes do not satisfy the sample type rules")
		}
		requesterID := me.UserID
		if req.RequesterID != "" && (roleOf(r) == "dispatcher" || roleOf(r) == "administrator") {
			requesterID = req.RequesterID
		}
		svc := computeServiceability(st, req.Origin, sreq.OriginType, req.OriginNodeID, req.SampleTypeID, earliest, deadline)
		now := time.Now().UTC()
		requestedAt := now
		if t, ok := parseTime(req.RequestedAt); ok {
			requestedAt = t
		}
		rq := &Request{
			RequestID: newUUID(), RequesterID: requesterID, Origin: req.Origin,
			OriginType: sreq.OriginType, OriginNodeID: req.OriginNodeID,
			RequestedAt: requestedAt, DeliveryDeadline: deadline,
			EarliestCollectionAt: earliest, LatestCollectionAt: latest,
			SampleTypeID: req.SampleTypeID, CreatedAt: now,
		}
		incomp := req.IncompatibleSampleTypes
		if incomp == nil {
			incomp = stype.IncompatibleSampleTypes
		}
		smp := &Sample{
			SampleID: newUUID(), RequestID: rq.RequestID, RequesterID: requesterID,
			Origin: req.Origin, OriginType: sreq.OriginType, OriginNodeID: req.OriginNodeID,
			RequestedAt: requestedAt, DeliveryDeadline: deadline,
			EarliestCollectionAt: earliest, LatestCollectionAt: latest,
			SampleTypeID: req.SampleTypeID, ContainerType: req.ContainerType,
			TemperatureMinC: *req.TemperatureMinC, TemperatureMaxC: *req.TemperatureMaxC,
			IncompatibleSampleTypes: incomp,
			Status: "requested", CreatedAt: now,
			ActiveAssignmentIDs: []string{}, CompletedLegIDs: []string{}, ActiveReplacementPlanIDs: []string{},
		}
		rq.SampleID = smp.SampleID
		if svc.Serviceable {
			smp.Serviceability = "serviceable"
		} else {
			smp.Serviceability = "unserviceable"
			smp.ServiceabilityReason = svc.Reason
		}
		if presealed {
			smp.Sealed = true
			smp.SealedAt = &now
			smp.Status = "sealed"
			smp.CurrentHolderID = me.UserID
			loc := me.LatestLocation
			if loc == nil {
				c := req.Origin
				loc = &c
			}
			smp.LatestLocation = loc
			smp.LocationRecordedAt = &now
		}
		st.Requests[rq.RequestID] = rq
		st.Samples[smp.SampleID] = smp
		var j *Journey
		if svc.Serviceable {
			j = a.buildJourneyLocked(st, smp, svc, presealed)
			if !presealed {
				smp.Status = "awaiting_collection"
			}
		}
		a.auditLocked(me.UserID, roleOf(r), "request.create", "request", rq.RequestID, true, map[string]interface{}{"sampleId": smp.SampleID, "serviceable": svc.Serviceable, "reason": svc.Reason})
