		writeErr(w, errAPI(400, "invalid_json", "malformed JSON body"))
		return false
	}
	r = r.WithContext(contextWith(r, ctxBody, b))
	return true
}

func bodyHash(b []byte) string {
	h := sha256.Sum256(b)
	return hex.EncodeToString(h[:])
}

func getUser(r *http.Request) *User       { return r.Context().Value(ctxUser).(*User) }
func getSession(r *http.Request) *Session { return r.Context().Value(ctxSession).(*Session) }

func roleOf(r *http.Request) string { return getSession(r).ActiveRole }

// requireRole checks the session's selected role is among allowed.
// administrator inherits dispatcher permissions.
func (a *App) requireRole(w http.ResponseWriter, r *http.Request, allowed ...string) bool {
	sess := getSession(r)
	role := sess.ActiveRole
	if role == "" {
		writeErr(w, errAPI(409, "role_not_selected", "select an active role first"))
		return false
	}
	eff := role
	if role == "administrator" {
		// administrator can do everything dispatcher can
		for _, al := range allowed {
			if al == "dispatcher" {
				eff = "dispatcher"
			}
		}
	}
	for _, al := range allowed {
		if role == al || eff == al {
			return true
		}
	}
	a.mutate(func(st *State) *apiError {
		a.auditLocked(getUser(r).UserID, role, "permission.denied", "http", r.URL.Path, false, map[string]interface{}{"required": allowed})
		return nil
	})
	writeErr(w, errAPI(403, "forbidden", "role "+role+" may not perform this action"))
	return false
}

// idempotent wraps a mutating handler with idempotency-key semantics.
// The inner handler returns (status, data, err).
func (a *App) idempotent(w http.ResponseWriter, r *http.Request, op string, body []byte, key string, fn func() (int, interface{}, *apiError)) {
	if key == "" {
		writeErr(w, errAPI(400, "idempotency_required", "idempotencyKey is required"))
		return
	}
	u := getUser(r)
	recKey := u.UserID + "|" + op + "|" + key
	bh := bodyHash(body)
	var rec *IdemRecord
	a.read(func(st *State) { rec = st.Idempotency[recKey] })
	if rec != nil {
		if rec.RequestHash != bh {
			writeErr(w, errAPI(409, "idempotency_conflict", "idempotency key reused with different payload"))
			return
		}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(rec.Status)
		io.WriteString(w, rec.Body)
		return
	}
	status, data, aerr := fn()
	if aerr != nil {
		writeErr(w, aerr)
		return
	}
	resp := map[string]interface{}{"data": data}
	raw, _ := json.Marshal(resp)
	a.mutate(func(st *State) *apiError {
		st.Idempotency[recKey] = &IdemRecord{Key: key, UserID: u.UserID, Op: op, RequestHash: bh, Status: status, Body: string(raw)}
		return nil
	})
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(status)
	w.Write(raw)
}

