    61	func haversineKm(a, b Coordinate) float64 {
    62		const R = 6371.0
    63		dLat := (b.Latitude - a.Latitude) * math.Pi / 180
    64		dLon := (b.Longitude - a.Longitude) * math.Pi / 180
    65		la := a.Latitude * math.Pi / 180
    66		lb := b.Latitude * math.Pi / 180
    67		h := math.Sin(dLat/2)*math.Sin(dLat/2) + math.Cos(la)*math.Cos(lb)*math.Sin(dLon/2)*math.Sin(dLon/2)
    68		return 2 * R * math.Asin(math.Sqrt(h))
