     7	)
     8	
     9	// ---------- routing ----------
    10	
    11	type routeResult struct {
    12		Found        bool
    13		LocationIDs  []string // includes start and end
    14		ConnectionIDs []string
    15		TravelMinutes int
    16		CostUnits    float64
    17	}
    18	
    19	// dijkstra over active connections; cooledRequired restricts to cooled connections.
    20	func findRoute(st *State, fromLocationID string, cooledRequired bool, acceptLab func(locID string) bool) *routeResult {
    21		dist := map[string]int{fromLocationID: 0}
    22		prevLoc := map[string]string{}
    23		prevConn := map[string]string{}
    24		visited := map[string]bool{}
    25		best := ""
    26		for {
    27			// pick unvisited min
    28			cur := ""
    29			curD := math.MaxInt32
    30			for id, d := range dist {
    31				if !visited[id] && d < curD {
    32					cur, curD = id, d
    33				}
    34			}
    35			if cur == "" {
    36				break
    37			}
    38			visited[cur] = true
    39			loc := st.Locations[cur]
    40			if loc == nil || !loc.Active {
    41				continue
    42			}
    43			if cur != fromLocationID && acceptLab(cur) {
    44				best = cur
    45				break
    46			}
    47			for _, c := range st.Connections {
    48				if !c.Active || c.FromLocationID != cur {
    49					continue
    50				}
    51				if cooledRequired && !c.Cooled {
    52					continue
    53				}
    54				to := st.Locations[c.ToLocationID]
    55				if to == nil || !to.Active {
    56					continue
    57				}
    58				// intermediate nodes must provide transfer/hub function
    59				if !acceptLab(c.ToLocationID) && !(to.Functions.TransferPoint || to.Functions.Hub || to.Functions.CollectionPoint) {
    60					continue
    61				}
    62				nd := curD + c.TravelMinutes + to.HandlingMinutes
    63				if ex, ok := dist[c.ToLocationID]; !ok || nd < ex {
    64					dist[c.ToLocationID] = nd
    65					prevLoc[c.ToLocationID] = cur
    66					prevConn[c.ToLocationID] = c.ConnectionID
    67				}
    68			}
    69		}
    70		if best == "" {
    71			return nil
    72		}
    73		res := &routeResult{Found: true, TravelMinutes: dist[best]}
    74		cur := best
    75		for cur != fromLocationID {
    76			res.LocationIDs = append([]string{cur}, res.LocationIDs...)
    77			res.ConnectionIDs = append([]string{prevConn[cur]}, res.ConnectionIDs...)
    78			res.CostUnits += st.Connections[prevConn[cur]].CostUnits
    79			cur = prevLoc[cur]
    80		}
    81		res.LocationIDs = append([]string{fromLocationID}, res.LocationIDs...)
    82		return res
    83	}
