    92	// nearest active collection point within coverage
    93	func nearestCollectionPoint(st *State, origin Coordinate) *Location {
    94		var best *Location
    95		bestD := math.MaxFloat64
    96		for _, l := range st.Locations {
    97			if !l.Active || !l.Functions.CollectionPoint {
    98				continue
    99			}
   100			d := haversineKm(origin, l.Coordinate)
   101			if d <= l.CoverageKm && d < bestD {
   102				best, bestD = l, d
   103			}
