   137	
   138	func computeServiceability(st *State, origin Coordinate, originType, originNodeID, sampleTypeID string, earliest, deadline time.Time) *serviceabilityResult {
   139		res := &serviceabilityResult{Reason: "serviceable"}
   140		st2 := st.SampleTypes[sampleTypeID]
   141		if st2 == nil {
   142			res.Reason = "handling_rules_unsatisfiable"
   143			return res
   144		}
   145		cooled := st2.RequiresCooledRoute
   146		var entry *Location
   147		if originType == "node" && originNodeID != "" {
   148			entry = st.Locations[originNodeID]
   149			if entry == nil || !entry.Active || !entry.Functions.CollectionPoint {
   150				res.Reason = "outside_service_coverage"
   151				return res
   152			}
   153		} else {
   154			entry = nearestCollectionPoint(st, origin)
   155			if entry == nil {
   156				res.Reason = "outside_service_coverage"
   157				return res
   158			}
   159		}
   160		res.EntryNodeID = entry.LocationID
   161		accept := func(lid string) bool { return labAccepts(st, st.Locations[lid], sampleTypeID) }
   162		// any accepting lab at all?
   163		anyLab := false
   164		for _, l := range st.Locations {
   165			if labAccepts(st, l, sampleTypeID) {
   166				anyLab = true
   167				break
   168			}
   169		}
   170		if !anyLab {
   171			res.Reason = "no_accepting_laboratory"
   172			return res
   173		}
   174		if accept(entry.LocationID) {
   175			res.LaboratoryID = entry.LocationID
   176			res.Route = &routeResult{Found: true, LocationIDs: []string{entry.LocationID}}
   177		} else {
   178			r := findRoute(st, entry.LocationID, cooled, accept)
   179			if r == nil {
   180				res.Reason = "no_route"
   181				return res
   182			}
   183			res.Route = r
   184			res.LaboratoryID = r.LocationIDs[len(r.LocationIDs)-1]
   185		}
   186		if !routeHasCapacity(st, res.Route, cooled) {
   187			res.Reason = "insufficient_capacity"
   188			return res
   189		}
   190		arr := earliest.Add(time.Duration(res.Route.TravelMinutes) * time.Minute)
   191		res.EstimatedArrival = arr
   192		if arr.After(deadline) {
   193			res.Reason = "deadline_unreachable"
   194			return res
   195		}
   196		res.Serviceable = true
   197		return res
   198	}
