   211		sort.Slice(regions, func(i, j int) bool { return regions[i].Name < regions[j].Name })
   212		st.Serviceability = ServiceabilitySnapshot{
   213			Version: st.Serviceability.Version + 1, Status: "complete",
   214			ComputedAt: time.Now().UTC(), NetworkRevision: st.NetworkRevision,
   215			Regions: regions, ActiveCollectionPointCount: len(regions),
   216		}
