   221	func reserveCapacityLocked(st *State, r *routeResult, cooled bool, n int) {
   222		for _, cid := range r.ConnectionIDs {
   223			c := st.Connections[cid]
   224			if cooled {
   225				c.Capacity.CooledReservedUnits += n
   226			} else {
   227				c.Capacity.ReservedUnits += n
   228			}
   229			c.Capacity.AvailableUnits = c.Capacity.CapacityUnits - c.Capacity.ReservedUnits
   230			c.Capacity.CooledAvailableUnits = c.Capacity.CooledCapacityUnits - c.Capacity.CooledReservedUnits
   231		}
   232		for _, lid := range r.LocationIDs {
   233			l := st.Locations[lid]
   234			if cooled {
   235				l.Capacity.CooledReservedUnits += n
   236			} else {
   237				l.Capacity.ReservedUnits += n
   238			}
   239			l.Capacity.AvailableUnits = l.Capacity.CapacityUnits - l.Capacity.ReservedUnits
   240			l.Capacity.CooledAvailableUnits = l.Capacity.CooledCapacityUnits - l.Capacity.CooledReservedUnits
   241		}
   242	}
