   452	// offerNextAfterLocked offers the next pending assignment in journey order after one completes.
   453	func (a *App) offerNextAfterLocked(st *State, j *Journey, sample *Sample) {
   454		order := append([]string{}, j.CollectionAssignmentIDs...)
   455		order = append(order, j.LegAssignmentIDs...)
   456		// interleave: simpler global order by sequence then kind priority
   457		var pend []*Assignment
   458		for _, id := range append(append(append([]string{}, j.CollectionAssignmentIDs...), j.LegAssignmentIDs...), append(append([]string{}, j.NodeAssignmentIDs...), j.LaboratoryAssignmentIDs...)...) {
   459			as := st.Assignments[id]
   460			if as != nil && as.Status == "pending" && as.OfferedTo == "" {
   461				pend = append(pend, as)
   462			}
   463		}
   464		_ = order
   465		if len(pend) == 0 {
   466			return
   467		}
   468		sort.Slice(pend, func(i, j int) bool { return pend[i].Sequence < pend[j].Sequence })
   469		a.offerAssignmentLocked(st, pend[0], sample)
   470	}
