   472	// journeyRoute reconstructs the routeResult for capacity release from journey legs.
   473	func journeyRoute(st *State, j *Journey) *routeResult {
   474		r := &routeResult{Found: true}
   475		prev := ""
   476		for _, aid := range j.LegAssignmentIDs {
   477			as := st.Assignments[aid]
   478			if as == nil {
   479				continue
   480			}
   481			if prev == "" {
   482				r.LocationIDs = append(r.LocationIDs, as.FromLocationID)
   483			}
   484			r.LocationIDs = append(r.LocationIDs, as.ToLocationID)
   485			for _, c := range st.Connections {
   486				if c.FromLocationID == as.FromLocationID && c.ToLocationID == as.ToLocationID {
   487					r.ConnectionIDs = append(r.ConnectionIDs, c.ConnectionID)
   488					break
   489				}
   490			}
   491			prev = as.ToLocationID
   492		}
   493		if len(r.LocationIDs) == 0 && len(j.LaboratoryAssignmentIDs) > 0 {
   494			r.LocationIDs = append(r.LocationIDs, st.Assignments[j.LaboratoryAssignmentIDs[0]].LaboratoryID)
   495		}
   496		return r
   497	}
