// ---------- journey dispatch operations ----------

func planVersionCheck(j *Journey, expected int) *apiError {
	if expected < 1 {
		return errAPI(400, "invalid_plan_version", "expectedPlanVersion must be >= 1")
	}
	if j.PlanVersion != expected {
		return errAPI(409, "stale_plan", "plan version mismatch")
	}
	return nil
}

func (a *App) cancelUnfinishedLocked(st *State, j *Journey) {
	for _, ids := range [][]string{j.CollectionAssignmentIDs, j.LegAssignmentIDs, j.NodeAssignmentIDs, j.LaboratoryAssignmentIDs} {
		for _, id := range ids {
			as := st.Assignments[id]
			if as != nil && as.Status != "completed" && as.Status != "cancelled" {
				as.Status = "cancelled"
				for _, sid := range as.SampleIDs {
					if s := st.Samples[sid]; s != nil {
						s.ActiveAssignmentIDs = removeStr(s.ActiveAssignmentIDs, id)
					}
				}
			}
		}
	}
	for _, h := range st.Handoffs {
		if h.Status == "pending" {
			if s := st.Samples[h.SampleID]; s != nil && containsStr(j.SampleIDs, s.SampleID) {
				h.Status = "cancelled"
				s.PendingHandoffID = ""
			}
		}
	}
}

func (a *App) cancelJourney(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	a.idempotent(w, r, "cancel_journey", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		var resp map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			j := st.Journeys[req.JourneyID]
			if j == nil {
				return errAPI(404, "not_found", "journey not found")
			}
			if e := planVersionCheck(j, req.ExpectedPlanVersion); e != nil {
				return e
			}
			if j.Status == "cancelled" {
				return errAPI(409, "inactive_plan", "journey already cancelled")
			}
			stypeCooled := map[string]bool{}
			for _, sid := range j.SampleIDs {
				if s := st.Samples[sid]; s != nil {
					if t := st.SampleTypes[s.SampleTypeID]; t != nil {
						stypeCooled[sid] = t.RequiresCooledRoute
					}
				}
			}
			route := journeyRoute(st, j)
			for _, sid := range j.SampleIDs {
				releaseCapacityLocked(st, route, stypeCooled[sid], 1)
				if s := st.Samples[sid]; s != nil {
					s.Status = "cancelled"
					s.ActiveJourneyID = ""
					a.auditLocked(getUser(r).UserID, roleOf(r), "sample.cancelled", "sample", sid, true, map[string]interface{}{"reason": req.Reason})
				}
			}
			a.cancelUnfinishedLocked(st, j)
			j.Status = "cancelled"
			j.PlanVersion++
			a.auditLocked(getUser(r).UserID, roleOf(r), "journey.cancel", "journey", j.JourneyID, true, map[string]interface{}{"reason": req.Reason})
			a.emitLocked("journey.cancelled", "journey", j.JourneyID, map[string]interface{}{"reason": req.Reason}, nil)
			resp = map[string]interface{}{"journeyId": j.JourneyID, "status": "cancelled", "sampleIds": j.SampleIDs}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, resp, nil
	})
}

// replanJourneyLocked replans unfinished legs of journey j from each sample's
// current position. Returns true if a valid replacement was built.
func (a *App) replanJourneyLocked(st *State, j *Journey) bool {
	u := st.Samples[j.SampleIDs[0]]
	if u == nil {
		return false
	}
	// determine current position of the sample
	fromLoc := ""
	if len(j.LegAssignmentIDs) > 0 {
		// find furthest completed leg
		lastDone := -1
		for i, aid := range j.LegAssignmentIDs {
			if as := st.Assignments[aid]; as != nil && as.Status == "completed" {
				lastDone = i
			}
		}
		if lastDone >= 0 {
			fromLoc = st.Assignments[j.LegAssignmentIDs[lastDone]].ToLocationID
		} else {
			fromLoc = st.Assignments[j.LegAssignmentIDs[0]].FromLocationID
		}
	}
	if fromLoc == "" && len(j.LaboratoryAssignmentIDs) > 0 {
		return true // already at lab, nothing to replan
	}
	if fromLoc == "" {
		return false
	}
	stype := st.SampleTypes[u.SampleTypeID]
	cooled := stype != nil && stype.RequiresCooledRoute
	accept := func(lid string) bool { return labAccepts(st, st.Locations[lid], u.SampleTypeID) }
	if accept(fromLoc) {
		return true
	}
	route := findRoute(st, fromLoc, cooled, accept)
	if route == nil || !routeHasCapacity(st, route, cooled) {
		return false
	}
	earliest := time.Now().UTC()
	if u.SealedAt != nil && u.SealedAt.After(earliest) {
		earliest = *u.SealedAt
	}
	if earliest.Add(time.Duration(route.TravelMinutes) * time.Minute).After(u.DeliveryDeadline) {
		return false
	}
	// cancel unfinished legs, build replacement legs
	oldRoute := journeyRoute(st, j)
	releaseCapacityLocked(st, oldRoute, cooled, 1)
	for _, aid := range j.LegAssignmentIDs {
		as := st.Assignments[aid]
		if as != nil && as.Status != "completed" && as.Status != "cancelled" {
			as.Status = "cancelled"
			u.ActiveAssignmentIDs = removeStr(u.ActiveAssignmentIDs, aid)
		}
	}
	for _, aid := range j.NodeAssignmentIDs {
		as := st.Assignments[aid]
		if as != nil && as.Status != "completed" && as.Status != "cancelled" {
			as.Status = "cancelled"
			u.ActiveAssignmentIDs = removeStr(u.ActiveAssignmentIDs, aid)
		}
	}
	for _, aid := range j.LaboratoryAssignmentIDs {
		as := st.Assignments[aid]
		if as != nil && as.Status != "completed" && as.Status != "cancelled" {
			as.Status = "cancelled"
			u.ActiveAssignmentIDs = removeStr(u.ActiveAssignmentIDs, aid)
		}
	}
	keptLegs := []string{}
	for _, aid := range j.LegAssignmentIDs {
		if as := st.Assignments[aid]; as != nil && as.Status == "completed" {
			keptLegs = append(keptLegs, aid)
		}
	}
	seq := len(keptLegs)
	newLegs := append([]string{}, keptLegs...)
	for i := 0; i < len(route.LocationIDs)-1; i++ {
		seq++
		ta := &Assignment{
			AssignmentID: newUUID(), Kind: "transport", JourneyID: j.JourneyID,
			SampleID: u.SampleID, SampleIDs: []string{u.SampleID}, Sequence: seq,
			Status: "pending", FromLocationID: route.LocationIDs[i], ToLocationID: route.LocationIDs[i+1],
			CreatedAt: time.Now().UTC(),
		}
		st.Assignments[ta.AssignmentID] = ta
		newLegs = append(newLegs, ta.AssignmentID)
		u.ActiveAssignmentIDs = append(u.ActiveAssignmentIDs, ta.AssignmentID)
	}
	j.LegAssignmentIDs = newLegs
	labID := route.LocationIDs[len(route.LocationIDs)-1]
	la := &Assignment{
		AssignmentID: newUUID(), Kind: "laboratory", JourneyID: j.JourneyID,
		SampleID: u.SampleID, SampleIDs: []string{u.SampleID}, Sequence: seq + 1,
		Status: "pending", LaboratoryID: labID, CreatedAt: time.Now().UTC(),
	}
	st.Assignments[la.AssignmentID] = la
	j.LaboratoryAssignmentIDs = []string{la.AssignmentID}
	u.ActiveAssignmentIDs = append(u.ActiveAssignmentIDs, la.AssignmentID)
	j.TargetLaboratoryID = labID
	u.TargetLaboratoryID = labID
	est := earliest.Add(time.Duration(route.TravelMinutes) * time.Minute)
	j.EstimatedDeliveryAt = &est
	j.TotalCostUnits += route.CostUnits
	j.PlanVersion++
	j.ReplanStatus = "replaced"
	j.ReplacementPlanID = newUUID()
	u.ActiveReplacementPlanIDs = []string{j.ReplacementPlanID}
	reserveCapacityLocked(st, route, cooled, 1)
	// offer first pending replacement leg
	for _, aid := range newLegs {
		as := st.Assignments[aid]
		if as.Status == "pending" {
			a.offerAssignmentLocked(st, as, u)
			break
		}
	}
	return true
}

func (a *App) rerouteJourney(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string `json:"journeyId"`
		ExpectedPlanVersion int    `json:"expectedPlanVersion"`
		Reason              string `json:"reason"`
		IdempotencyKey      string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	a.idempotent(w, r, "reroute_journey", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		var resp map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			j := st.Journeys[req.JourneyID]
			if j == nil {
				return errAPI(404, "not_found", "journey not found")
			}
			if e := planVersionCheck(j, req.ExpectedPlanVersion); e != nil {
				return e
			}
			if j.Status == "cancelled" || j.Status == "completed" {
				return errAPI(409, "inactive_plan", "journey is not active")
			}
			sample := st.Samples[j.SampleIDs[0]]
			ok := a.replanJourneyLocked(st, j)
			status := "replaced"
			if !ok {
				if sample != nil && time.Now().After(sample.DeliveryDeadline) {
					status = "expired"
					sample.Status = "expired"
					j.Status = "expired"
				} else {
					status = "exception"
					if sample != nil {
						sample.Status = "exception"
						sample.ExceptionReason = "no_valid_route"
					}
					j.Status = "exception"
				}
				j.ReplanStatus = status
			}
			a.auditLocked(getUser(r).UserID, roleOf(r), "journey.reroute", "journey", j.JourneyID, true, map[string]interface{}{"reason": req.Reason, "replanStatus": status})
			a.emitLocked("journey.replanned", "journey", j.JourneyID, map[string]interface{}{"replanStatus": status}, nil)
			resp = map[string]interface{}{
				"journeyId": j.JourneyID, "replanStatus": status,
				"replacementJourney": journeyPlanJSON(st, j),
			}
			if j.ReplacementPlanID != "" {
				resp["replacementPlanId"] = j.ReplacementPlanID
			}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, resp, nil
	})
}

func (a *App) splitJourney(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string   `json:"journeyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SampleIDs           []string `json:"sampleIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	a.idempotent(w, r, "split_journey", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		var resp map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			j := st.Journeys[req.JourneyID]
			if j == nil {
				return errAPI(404, "not_found", "journey not found")
			}
			if e := planVersionCheck(j, req.ExpectedPlanVersion); e != nil {
				return e
			}
			if len(req.SampleIDs) == 0 || len(req.SampleIDs) >= len(j.SampleIDs) {
				return errAPI(409, "invalid_split", "sampleIds must be a proper subset of the journey samples")
			}
			for _, sid := range req.SampleIDs {
				if !containsStr(j.SampleIDs, sid) {
					return errAPI(409, "invalid_split", "sample not in journey")
				}
			}
			nj := &Journey{
				JourneyID: newUUID(), ParentJourneyID: j.JourneyID, PlanVersion: 1,
				RouteMode: j.RouteMode, Status: j.Status, SampleIDs: append([]string{}, req.SampleIDs...),
				Stops: j.Stops, EstimatedDeliveryAt: j.EstimatedDeliveryAt,
				TargetLaboratoryID: j.TargetLaboratoryID, CreatedAt: time.Now().UTC(),
			}
			st.Journeys[nj.JourneyID] = nj
			remaining := []string{}
			for _, sid := range j.SampleIDs {
				if !containsStr(req.SampleIDs, sid) {
					remaining = append(remaining, sid)
				}
			}
			j.SampleIDs = remaining
			j.PlanVersion++
			for _, sid := range req.SampleIDs {
				if s := st.Samples[sid]; s != nil {
					s.ActiveJourneyID = nj.JourneyID
				}
			}
			a.auditLocked(getUser(r).UserID, roleOf(r), "journey.split", "journey", j.JourneyID, true, map[string]interface{}{"splitJourneyId": nj.JourneyID, "sampleIds": req.SampleIDs})
			a.emitLocked("journey.split", "journey", j.JourneyID, map[string]interface{}{"splitJourneyId": nj.JourneyID}, nil)
			resp = map[string]interface{}{"journey": journeyPlanJSON(st, j), "splitJourney": journeyPlanJSON(st, nj)}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, resp, nil
	})
}

func (a *App) mergeJourneys(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		TargetJourneyID     string   `json:"targetJourneyId"`
		ExpectedPlanVersion int      `json:"expectedPlanVersion"`
		SourceJourneyIDs    []string `json:"sourceJourneyIds"`
		IdempotencyKey      string   `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	a.idempotent(w, r, "merge_journeys", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		var resp map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			t := st.Journeys[req.TargetJourneyID]
			if t == nil {
				return errAPI(404, "not_found", "target journey not found")
			}
			if e := planVersionCheck(t, req.ExpectedPlanVersion); e != nil {
				return e
			}
			if len(req.SourceJourneyIDs) == 0 {
				return errAPI(409, "invalid_merge", "no source journeys given")
			}
			types := map[string]string{}
			for _, sid := range t.SampleIDs {
				if s := st.Samples[sid]; s != nil {
					types[s.SampleTypeID] = true0(s)
				}
			}
			_ = types
			for _, srcID := range req.SourceJourneyIDs {
				s := st.Journeys[srcID]
				if s == nil {
					return errAPI(404, "not_found", "source journey not found")
				}
				if s.JourneyID == t.JourneyID {
					return errAPI(409, "invalid_merge", "cannot merge journey into itself")
				}
				if s.Status == "completed" || s.Status == "cancelled" {
					return errAPI(409, "invalid_merge", "source journey not active")
				}
				// compatibility check
				for _, sid := range append(append([]string{}, t.SampleIDs...), s.SampleIDs...) {
					smp := st.Samples[sid]
					if smp == nil {
						continue
					}
					stype := st.SampleTypes[smp.SampleTypeID]
					if stype != nil && !stype.BatchingAllowed {
						return errAPI(409, "pulse_no_batch", "sample type does not allow batching")
					}
					for _, otherID := range append(append([]string{}, t.SampleIDs...), s.SampleIDs...) {
						if otherID == sid {
							continue
						}
						other := st.Samples[otherID]
						if other == nil {
							continue
						}
						if containsStr(smp.IncompatibleSampleTypes, other.SampleTypeID) {
							return errAPI(409, "incompatible_batch", "samples are incompatible")
						}
					}
				}
			}
			for _, srcID := range req.SourceJourneyIDs {
				s := st.Journeys[srcID]
				for _, sid := range s.SampleIDs {
					t.SampleIDs = append(t.SampleIDs, sid)
					if smp := st.Samples[sid]; smp != nil {
						smp.ActiveJourneyID = t.JourneyID
					}
				}
				s.Status = "cancelled"
				s.PlanVersion++
				a.auditLocked(getUser(r).UserID, roleOf(r), "journey.merged_away", "journey", s.JourneyID, true, map[string]interface{}{"targetJourneyId": t.JourneyID})
			}
			t.RouteMode = "batched"
			t.PlanVersion++
			a.auditLocked(getUser(r).UserID, roleOf(r), "journey.merge", "journey", t.JourneyID, true, map[string]interface{}{"sourceJourneyIds": req.SourceJourneyIDs})
			a.emitLocked("journey.merged", "journey", t.JourneyID, map[string]interface{}{"sourceJourneyIds": req.SourceJourneyIDs}, nil)
			resp = journeyPlanJSON(st, t)
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, resp, nil
	})
}

func true0(s *Sample) string { return s.SampleTypeID }

func (a *App) editActivePlan(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		JourneyID           string                 `json:"journeyId"`
		ExpectedPlanVersion int                    `json:"expectedPlanVersion"`
		ChangeType          string                 `json:"changeType"`
		Changes             map[string]interface{} `json:"changes"`
		IdempotencyKey      string                 `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	validChange := map[string]bool{
		"add_stop": true, "remove_stop": true, "reorder_stops": true,
		"replace_worker": true, "reassign_worker": true, "merge_samples": true,
		"split_samples": true, "split_batch": true, "cancel_work": true,
		"reroute": true, "replace_route": true,
	}
	if !validChange[req.ChangeType] {
		writeErr(w, errAPI(400, "invalid_change_type", "unknown changeType"))
		return
	}
	a.idempotent(w, r, "edit_active_plan", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		var resp map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			j := st.Journeys[req.JourneyID]
			if j == nil {
				return errAPI(404, "not_found", "journey not found")
			}
			if e := planVersionCheck(j, req.ExpectedPlanVersion); e != nil {
				return e
			}
			if j.Status == "cancelled" || j.Status == "completed" {
				return errAPI(409, "inactive_plan", "journey is not active")
			}
			switch req.ChangeType {
			case "cancel_work":
				a.cancelUnfinishedLocked(st, j)
				j.Status = "cancelled"
			case "replace_worker", "reassign_worker":
				aid, _ := req.Changes["assignmentId"].(string)
				wid, _ := req.Changes["workerId"].(string)
				as := st.Assignments[aid]
				if as == nil || as.JourneyID != j.JourneyID {
					return errAPI(409, "invalid_assignment", "assignment not in journey")
				}
				if as.Status == "completed" {
					return errAPI(409, "completed_work_immutable", "completed assignment cannot be changed")
				}
				wk := st.Users[wid]
				if wk == nil || !wk.Active {
					return errAPI(400, "invalid_worker", "worker not found")
				}
				as.WorkerID = wid
				as.OfferedTo = wid
				as.Status = "pending"
			case "reroute", "replace_route":
				if !a.replanJourneyLocked(st, j) {
					return errAPI(409, "no_valid_route", "no valid replacement route")
				}
				j.PlanVersion-- // replan already bumped
			case "add_stop", "remove_stop", "reorder_stops":
				return errAPI(409, "invalid_stop_order", "stop changes are not permitted on in-flight journeys")
			default:
				return errAPI(409, "invalid_plan", "change not applicable")
			}
			j.PlanVersion++
			a.auditLocked(getUser(r).UserID, roleOf(r), "journey.edit_plan", "journey", j.JourneyID, true, map[string]interface{}{"changeType": req.ChangeType})
			a.emitLocked("journey.plan_changed", "journey", j.JourneyID, map[string]interface{}{"changeType": req.ChangeType}, nil)
			resp = journeyPlanJSON(st, j)
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, resp, nil
	})
}

// ---------- disruptions ----------

func (a *App) reportDisruption(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		ResourceType   string `json:"resourceType"`
		ResourceID     string `json:"resourceId"`
		Reason         string `json:"reason"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	validRT := map[string]bool{"location": true, "node": true, "laboratory": true, "connection": true, "route": true, "worker": true, "capacity": true}
	if !validRT[req.ResourceType] {
		writeErr(w, errAPI(400, "invalid_resource_type", "unknown resourceType"))
		return
	}
	occ, ok := parseTime(req.OccurredAt)
	if !ok {
		writeErr(w, errAPI(400, "invalid_time", "occurredAt must be RFC3339"))
		return
	}
	a.idempotent(w, r, "report_disruption", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		var resp map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			d := &Disruption{DisruptionID: newUUID(), ResourceType: req.ResourceType, ResourceID: req.ResourceID, Reason: req.Reason, OccurredAt: occ}
			st.Disruptions[d.DisruptionID] = d
			affected := []string{}
			replacements := []string{}
			replanStatus := "not_required"
			// find affected journeys
			affectedJourneys := map[string]*Journey{}
			switch req.ResourceType {
			case "location", "node", "laboratory":
				if st.Locations[req.ResourceID] == nil {
					return errAPI(404, "not_found", "location not found")
				}
				for _, j := range st.Journeys {
					if j.Status != "planned" && j.Status != "in_progress" {
						continue
					}
					for _, s := range j.Stops {
						if s.LocationID == req.ResourceID && s.CompletedAt == nil {
							affectedJourneys[j.JourneyID] = j
						}
					}
				}
			case "connection", "route":
				if st.Connections[req.ResourceID] == nil {
					return errAPI(404, "not_found", "connection not found")
				}
				for _, j := range st.Journeys {
					if j.Status != "planned" && j.Status != "in_progress" {
						continue
					}
					for _, aid := range j.LegAssignmentIDs {
						as := st.Assignments[aid]
						if as == nil || as.Status == "completed" {
							continue
						}
						c := st.Connections[req.ResourceID]
						if c.FromLocationID == as.FromLocationID && c.ToLocationID == as.ToLocationID {
							affectedJourneys[j.JourneyID] = j
						}
					}
				}
			case "worker":
				if st.Users[req.ResourceID] == nil {
					return errAPI(404, "not_found", "worker not found")
				}
				for _, as := range st.Assignments {
					if (as.WorkerID == req.ResourceID || as.OfferedTo == req.ResourceID) && (as.Status == "pending" || as.Status == "accepted" || as.Status == "in_progress") {
						if j := st.Journeys[as.JourneyID]; j != nil {
							affectedJourneys[j.JourneyID] = j
						}
					}
				}
			case "capacity":
				for _, j := range st.Journeys {
					if j.Status == "planned" || j.Status == "in_progress" {
						affectedJourneys[j.JourneyID] = j
					}
				}
			}
			for _, j := range affectedJourneys {
				for _, sid := range j.SampleIDs {
					if !containsStr(affected, sid) {
						affected = append(affected, sid)
					}
				}
				if a.replanJourneyLocked(st, j) {
					replanStatus = "replaced"
					if j.ReplacementPlanID != "" {
						replacements = append(replacements, j.ReplacementPlanID)
					}
				} else {
					sample := st.Samples[j.SampleIDs[0]]
					if sample != nil && time.Now().After(sample.DeliveryDeadline) {
						replanStatus = "expired"
						sample.Status = "expired"
						j.Status = "expired"
					} else if replanStatus != "replaced" {
						replanStatus = "exception"
						if sample != nil {
							sample.Status = "exception"
							sample.ExceptionReason = "no_valid_route"
						}
						j.Status = "exception"
					}
				}
			}
			a.auditLocked(getUser(r).UserID, roleOf(r), "disruption.report", req.ResourceType, req.ResourceID, true, map[string]interface{}{"reason": req.Reason, "affectedSamples": affected})
			a.emitLocked("disruption.reported", req.ResourceType, req.ResourceID, map[string]interface{}{"affectedSampleIds": affected}, nil)
			resp = map[string]interface{}{
				"disruptionId": d.DisruptionID, "affectedSampleIds": affected,
				"replacementPlanIds": replacements, "replanStatus": replanStatus,
			}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, resp, nil
	})
}

// ---------- audit search ----------

func (a *App) searchAuditTrail(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator") {
		return
	}
	var req struct {
		Query      string `json:"query"`
		ActorID    string `json:"actorId"`
		EntityType string `json:"entityType"`
		EntityID   string `json:"entityId"`
		Action     string `json:"action"`
		Role       string `json:"role"`
		Success    *bool  `json:"success"`
		FromTime   string `json:"fromTime"`
		ToTime     string `json:"toTime"`
		Limit      int    `json:"limit"`
		Offset     int    `json:"offset"`
		Order      string `json:"order"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.Limit == 0 {
		req.Limit = 500
	}
	if req.Limit < 1 || req.Limit > 5000 {
		writeErr(w, errAPI(400, "invalid_limit", "limit must be 1..5000"))
		return
	}
	if req.Offset < 0 {
		writeErr(w, errAPI(400, "invalid_offset", "offset must be >= 0"))
		return
	}
	if req.Order == "" {
		req.Order = "newest_first"
	}
	if req.Order != "newest_first" && req.Order != "oldest_first" {
		writeErr(w, errAPI(400, "invalid_order", "order must be newest_first or oldest_first"))
		return
	}
	var from, to time.Time
	if req.FromTime != "" {
		t, ok := parseTime(req.FromTime)
		if !ok {
			writeErr(w, errAPI(400, "invalid_time", "fromTime must be RFC3339"))
			return
		}
		from = t
	}
	if req.ToTime != "" {
		t, ok := parseTime(req.ToTime)
		if !ok {
			writeErr(w, errAPI(400, "invalid_time", "toTime must be RFC3339"))
			return
		}
		to = t
	}
	var resp map[string]interface{}
	a.read(func(st *State) {
		matched := []AuditEntry{}
		for _, e := range st.Audit {
			if req.ActorID != "" && e.ActorID != req.ActorID {
				continue
			}
			if req.EntityType != "" && e.EntityType != req.EntityType {
				continue
			}
			if req.EntityID != "" && e.EntityID != req.EntityID {
				continue
			}
			if req.Action != "" && e.Action != req.Action {
				continue
			}
			if req.Role != "" && e.Role != req.Role {
				continue
			}
			if req.Success != nil && e.Success != *req.Success {
				continue
			}
			if !from.IsZero() && e.OccurredAt.Before(from) {
				continue
			}
			if !to.IsZero() && e.OccurredAt.After(to) {
				continue
			}
			if req.Query != "" {
				hay := strings.ToLower(e.Action + " " + e.EntityType + " " + e.EntityID + " " + e.ActorID)
				if !strings.Contains(hay, strings.ToLower(req.Query)) {
					continue
				}
			}
			matched = append(matched, e)
		}
		sort.Slice(matched, func(i, j int) bool {
			if req.Order == "oldest_first" {
				return matched[i].OccurredAt.Before(matched[j].OccurredAt)
			}
			return matched[i].OccurredAt.After(matched[j].OccurredAt)
		})
		total := len(matched)
		start := req.Offset
		if start > total {
			start = total
		}
		end := start + req.Limit
		if end > total {
			end = total
		}
		entries := []interface{}{}
		for _, e := range matched[start:end] {
			entries = append(entries, auditJSON(e))
		}
		hasMore := end < total
		resp = map[string]interface{}{
			"entries": entries, "total": total, "returned": end - start,
			"offset": req.Offset, "limit": req.Limit, "order": req.Order, "hasMore": hasMore,
		}
		if hasMore {
			resp["nextOffset"] = end
		}
	})
	writeData(w, 200, resp)
}

// ---------- serviceability snapshot ----------

func (a *App) readServiceabilitySnapshot(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "dispatcher", "administrator", "requester") {
		return
	}
	var resp map[string]interface{}
	a.read(func(st *State) {
		snap := st.Serviceability
		regions := []interface{}{}
		for _, rg := range snap.Regions {
			regions = append(regions, map[string]interface{}{
				"locationId": rg.LocationID, "name": rg.Name,
				"latitude": rg.Latitude, "longitude": rg.Longitude, "coverageKm": rg.CoverageKm,
			})
		}
		resp = map[string]interface{}{
			"version": snap.Version, "status": "complete", "computedAt": timeStr(snap.ComputedAt),
			"networkRevision": snap.NetworkRevision, "regions": regions,
			"activeCollectionPointCount": snap.ActiveCollectionPointCount,
		}
	})
	writeData(w, 200, resp)
}
