// bodyCacheMiddleware reads the request body once, stores it in the request
// context, and restores r.Body so decodeBody and rawBody can both access it.
func bodyCacheMiddleware(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		if r.Body != nil && (r.Method == http.MethodPost || r.Method == http.MethodPut || r.Method == http.MethodPatch) {
			b, err := io.ReadAll(io.LimitReader(r.Body, 4<<20))
			if err == nil {
				r.Body = io.NopCloser(strings.NewReader(string(b)))
				r = r.WithContext(contextWith(r, ctxBody, b))
			}
		}
		next.ServeHTTP(w, r)
	})
}

func rawBody(r *http.Request) []byte {
	b, _ := r.Context().Value(ctxBody).([]byte)
	return b
}

func decodeBody(w http.ResponseWriter, r *http.Request, dst interface{}) bool {
	b := rawBody(r)
	if b == nil {
		var err error
		b, err = io.ReadAll(io.LimitReader(r.Body, 4<<20))
		if err != nil {
			writeErr(w, errAPI(400, "invalid_json", "cannot read body"))
			return false
		}
	}
	if len(b) == 0 {
		b = []byte("{}")
	}
	dec := json.NewDecoder(strings.NewReader(string(b)))
	if err := dec.Decode(dst); err != nil {
		writeErr(w, errAPI(400, "invalid_json", "malformed JSON body"))
		return false
	}
	return true
}

