package main

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"net/http"
	"sort"
	"strconv"
	"time"
)

//go:embed openapi.json
var openapiSpec []byte

// ---------- openapi document ----------

func (a *App) serveOpenAPI(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(200)
	w.Write(openapiSpec)
}

// ---------- ui bootstrap ----------

func (a *App) readUiBootstrap(w http.ResponseWriter, r *http.Request) {
	u := getUser(r)
	sess := getSession(r)
	var resp map[string]interface{}
	a.read(func(st *State) {
		types := []interface{}{}
		for _, t := range st.SampleTypes {
			types = append(types, sampleTypeJSON(t))
		}
		sort.Slice(types, func(i, j int) bool {
			return types[i].(map[string]interface{})["name"].(string) < types[j].(map[string]interface{})["name"].(string)
		})
		locs := []interface{}{}
		for _, l := range st.Locations {
			accepted := []string{}
			for tid, ok := range l.AcceptedTypes {
				if ok {
					accepted = append(accepted, tid)
				}
			}
			sort.Strings(accepted)
			locs = append(locs, map[string]interface{}{
				"id": l.LocationID, "locationId": l.LocationID, "name": l.Name,
				"coordinate": l.Coordinate, "active": l.Active, "coverageKm": l.CoverageKm,
				"handlingMinutes": l.HandlingMinutes, "functions": funcJSON(l.Functions),
				"capacity": capJSON(l.Capacity), "acceptedSampleTypeIds": accepted,
			})
		}
		resp = map[string]interface{}{
			"user": map[string]interface{}{
				"userId": u.UserID, "username": u.Username, "fullName": u.FullName,
				"roles": u.Roles, "activeRole": sess.ActiveRole,
			},
			"sampleTypes": types, "locations": locs,
			"mapConfig": map[string]interface{}{
				"center": []float64{77.5946, 12.9716}, "zoom": 11,
				"style":  "/map-assets/style.json",
			},
		}
	})
	writeData(w, 200, resp)
}

// ---------- events stream ----------

// streamEvents serves GET /api/events. With ?stream=true it keeps the
// connection open as server-sent events; otherwise it returns a JSON
// snapshot of events after ?after=<eventId>.
func (a *App) streamEvents(w http.ResponseWriter, r *http.Request) {
	after, _ := strconv.Atoi(r.URL.Query().Get("after"))
	if r.URL.Query().Get("stream") != "true" {
		var events []Event
		a.read(func(st *State) {
			for _, e := range st.Events {
				if e.ID > after {
					events = append(events, e)
				}
			}
		})
		out := []interface{}{}
		for _, e := range events {
			out = append(out, eventJSON(e))
		}
		writeData(w, 200, map[string]interface{}{"events": out})
		return
	}
	fl, ok := w.(http.Flusher)
	if !ok {
		writeErr(w, errAPI(500, "internal_error", "streaming unsupported"))
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.WriteHeader(200)
	ch := a.subscribe()
	defer a.unsubscribe(ch)
	last := after
	send := func(e Event) {
		b, _ := json.Marshal(eventJSON(e))
		fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", e.ID, e.Type, b)
	}
	// replay backlog
	a.read(func(st *State) {
		for _, e := range st.Events {
			if e.ID > last {
				send(e)
				last = e.ID
			}
		}
	})
	fl.Flush()
	keepalive := time.NewTicker(25 * time.Second)
	defer keepalive.Stop()
	for {
		select {
		case <-r.Context().Done():
			return
		case <-keepalive.C:
			fmt.Fprint(w, ": keepalive\n\n")
			fl.Flush()
		case <-ch:
			a.read(func(st *State) {
				for _, e := range st.Events {
					if e.ID > last {
						send(e)
						last = e.ID
					}
				}
			})
			fl.Flush()
		}
	}
}

// ---------- admin reset ----------

func (a *App) adminReset(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	a.idempotent(w, r, "admin_reset", rawBody(r), "reset", func() (int, interface{}, *apiError) {
		e := a.mutate(func(st *State) *apiError {
			keep := map[string]*User{}
			for id, usr := range st.Users {
				if containsStr(usr.Roles, "administrator") {
					keep[id] = usr
				}
			}
			*st = *NewState()
			st.Users = keep
			seedSampleTypes(st)
			a.auditLocked(getUser(r).UserID, roleOf(r), "admin.reset", "system", "reset", true, nil)
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, map[string]interface{}{"reset": true}, nil
	})
}

