package main

import (
	_ "embed"
	"encoding/json"
	"fmt"
	"net/http"
	"sort"
	"strconv"
	"time"
)

//go:embed openapi.json
var openapiSpec []byte

// ---------- openapi document ----------

func (a *App) serveOpenAPI(w http.ResponseWriter, r *http.Request) {
	w.Header().Set("Content-Type", "application/json")
	w.WriteHeader(200)
	w.Write(openapiSpec)
}

// ---------- ui bootstrap ----------

func (a *App) readUiBootstrap(w http.ResponseWriter, r *http.Request) {
	u := getUser(r)
	sess := getSession(r)
	var resp map[string]interface{}
	a.read(func(st *State) {
		resp = map[string]interface{}{
			"user": map[string]interface{}{
				"userId": u.UserID, "username": u.Username, "fullName": u.FullName,
				"roles": u.Roles, "activeRole": sess.ActiveRole,
				"roleSelectionRequired": sess.ActiveRole == "",
			},
			"serverTime":       timeStr(time.Now().UTC()),
			"requesterSamples": requesterSamplesLocked(st, u),
			"operations":       operationsStateLocked(st, ""),
		}
	})
	writeData(w, 200, resp)
}

// requesterSamplesLocked lists the caller's own samples for bootstrap.
func requesterSamplesLocked(st *State, u *User) []interface{} {
	out := []interface{}{}
	for _, s := range st.Samples {
		if s.RequesterID != u.UserID {
			continue
		}
		out = append(out, map[string]interface{}{
			"sampleId": s.SampleID, "requestId": s.RequestID, "status": s.Status,
			"serviceability": s.Serviceability, "locationStale": isStale(s.LocationRecordedAt),
		})
	}
	return out
}

// ---------- events stream ----------

// streamEvents serves GET /api/events?since=<cursor>. It returns the events
// after the cursor plus the new cursor. With ?stream=true it instead keeps
// the connection open as server-sent events.
func (a *App) streamEvents(w http.ResponseWriter, r *http.Request) {
	since, _ := strconv.ParseInt(r.URL.Query().Get("since"), 10, 64)
	if r.URL.Query().Get("stream") != "true" {
		out := []interface{}{}
		cursor := since
		a.read(func(st *State) {
			for _, e := range st.Events {
				if e.ID > since {
					out = append(out, eventJSON(e))
					if e.ID > cursor {
						cursor = e.ID
					}
				}
			}
			if cursor == 0 {
				cursor = st.EventSeq
			}
		})
		writeData(w, 200, map[string]interface{}{"events": out, "cursor": cursor})
		return
	}
	after := since
	fl, ok := w.(http.Flusher)
	if !ok {
		writeErr(w, errAPI(500, "internal_error", "streaming unsupported"))
		return
	}
	w.Header().Set("Content-Type", "text/event-stream")
	w.Header().Set("Cache-Control", "no-cache")
	w.Header().Set("Connection", "keep-alive")
	w.WriteHeader(200)
	ch := a.subscribe()
	defer a.unsubscribe(ch)
	last := after
	send := func(e Event) {
		b, _ := json.Marshal(eventJSON(e))
		fmt.Fprintf(w, "id: %d\nevent: %s\ndata: %s\n\n", e.ID, e.Type, b)
	}
	// replay backlog
	a.read(func(st *State) {
		for _, e := range st.Events {
			if e.ID > last {
				send(e)
				last = e.ID
			}
		}
	})
	fl.Flush()
	keepalive := time.NewTicker(25 * time.Second)
	defer keepalive.Stop()
	for {
		select {
		case <-r.Context().Done():
			return
		case <-keepalive.C:
			fmt.Fprint(w, ": keepalive\n\n")
			fl.Flush()
		case <-ch:
			a.read(func(st *State) {
				for _, e := range st.Events {
					if e.ID > last {
						send(e)
						last = e.ID
					}
				}
			})
			fl.Flush()
		}
	}
}

// ---------- admin reset ----------

func (a *App) adminReset(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "administrator") {
		return
	}
	a.idempotent(w, r, "admin_reset", rawBody(r), "reset", func() (int, interface{}, *apiError) {
		e := a.mutate(func(st *State) *apiError {
			keep := map[string]*User{}
			for id, usr := range st.Users {
				if containsStr(usr.Roles, "administrator") {
					keep[id] = usr
				}
			}
			*st = *NewState()
			st.Users = keep
			seedSampleTypes(st)
			a.auditLocked(getUser(r).UserID, roleOf(r), "admin.reset", "system", "reset", true, nil)
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, map[string]interface{}{"reset": true}, nil
	})
}

