	}
	if j.EstimatedDeliveryAt != nil {
		m["estimatedDeliveryAt"] = timeStr(*j.EstimatedDeliveryAt)
	}
	if len(j.CollectionAssignmentIDs) > 0 {
		m["collectionAssignmentId"] = j.CollectionAssignmentIDs[0]
	}
	if len(j.LegAssignmentIDs) > 0 {
		m["firstTransportAssignmentId"] = j.LegAssignmentIDs[0]
		m["finalTransportAssignmentId"] = j.LegAssignmentIDs[len(j.LegAssignmentIDs)-1]
	}
	if len(j.LegAssignmentIDs) > 2 {
		m["middleTransportAssignmentId"] = j.LegAssignmentIDs[1]
	}
	if j.ReplanStatus != "" {
		m["replanStatus"] = j.ReplanStatus
	}
	return m
}

