   470	func (a *App) initiateHandoff(w http.ResponseWriter, r *http.Request) {
   471		if !a.requireRole(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
   472			return
   473		}
   474		var req struct {
   475			SampleID         string `json:"sampleId"`
   476			FromAssignmentID string `json:"fromAssignmentId"`
   477			ToAssignmentID   string `json:"toAssignmentId"`
   478			ReceiverID       string `json:"receiverId"`
   479		}
   480		if !decodeBody(w, r, &req) {
   481			return
   482		}
   483		u := getUser(r)
   484		var out map[string]interface{}
   485		e := a.mutate(func(st *State) *apiError {
   486			smp := st.Samples[req.SampleID]
   487			if smp == nil {
   488				return errAPI(404, "not_found", "sample not found")
   489			}
   490			if smp.CurrentHolderID != u.UserID {
   491				return errAPI(409, "custody_required", "you are not the current holder")
   492			}
   493			if smp.PendingHandoffID != "" {
   494				if h := st.Handoffs[smp.PendingHandoffID]; h != nil && h.Status == "pending" {
   495					return errAPI(409, "handoff_state_invalid", "a handoff is already pending for this sample")
   496				}
   497			}
   498			recv := st.Users[req.ReceiverID]
   499			if recv == nil {
   500				return errAPI(404, "not_found", "receiver not found")
   501			}
   502			h := &Handoff{
   503				HandoffID: newUUID(), SampleID: smp.SampleID, FromAssignmentID: req.FromAssignmentID,
   504				ToAssignmentID: req.ToAssignmentID, SenderID: u.UserID, ReceiverID: req.ReceiverID,
   505				Status: "pending", InitiatedAt: time.Now().UTC(),
   506			}
   507			st.Handoffs[h.HandoffID] = h
   508			smp.PendingHandoffID = h.HandoffID
   509			a.auditLocked(u.UserID, roleOf(r), "handoff.initiate", "handoff", h.HandoffID, true, map[string]interface{}{"sampleId": smp.SampleID, "receiverId": req.ReceiverID})
   510			a.emitLocked("handoff.initiated", "handoff", h.HandoffID, map[string]interface{}{"sampleId": smp.SampleID}, nil)
   511			out = map[string]interface{}{"handoffId": h.HandoffID, "status": "pending", "currentHolderId": u.UserID}
   512			return nil
   513		})
   514		if e != nil {
   515			writeErr(w, e)
   516			return
   517		}
   518		writeData(w, 200, out)
   519	}
