   521	func (a *App) confirmHandoff(w http.ResponseWriter, r *http.Request) {
   522		if !a.requireRole(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
   523			return
   524		}
   525		var req struct {
   526			HandoffID string `json:"handoffId"`
   527			Side      string `json:"side"`
   528		}
   529		if !decodeBody(w, r, &req) {
   530			return
   531		}
   532		if req.Side != "sender" && req.Side != "receiver" {
   533			writeErr(w, errAPI(400, "invalid_handoff_side", "side must be sender or receiver"))
   534			return
   535		}
   536		u := getUser(r)
   537		var out map[string]interface{}
   538		e := a.mutate(func(st *State) *apiError {
   539			h := st.Handoffs[req.HandoffID]
   540			if h == nil {
   541				return errAPI(404, "not_found", "handoff not found")
   542			}
   543			if h.Status == "confirmed" {
   544				// idempotent re-confirmation
   545				out = map[string]interface{}{"handoffId": h.HandoffID, "status": "confirmed", "currentHolderId": h.ReceiverID}
   546				return nil
   547			}
   548			if h.Status != "pending" {
   549				return errAPI(409, "handoff_state_invalid", "handoff is not pending")
   550			}
   551			if req.Side == "sender" {
   552				if h.SenderID != u.UserID {
   553					return errAPI(403, "forbidden", "only the sender can confirm the sender side")
   554				}
   555				h.SenderConfirmed = true
   556			} else {
   557				if h.ReceiverID != u.UserID {
   558					return errAPI(403, "forbidden", "only the receiver can confirm the receiver side")
   559				}
   560				h.ReceiverConfirmed = true
   561			}
   562			smp := st.Samples[h.SampleID]
   563			if h.SenderConfirmed && h.ReceiverConfirmed {
   564				now := time.Now().UTC()
   565				h.Status = "confirmed"
   566				h.ConfirmedAt = &now
   567				if smp != nil {
   568					smp.CurrentHolderID = h.ReceiverID
   569					smp.PendingHandoffID = ""
   570					smp.LocationRecordedAt = &now
   571					if recv := st.Users[h.ReceiverID]; recv != nil && recv.LatestLocation != nil {
   572						smp.LatestLocation = recv.LatestLocation
   573					}
   574					// mark destination stop / node assignment progression
   575					if to := st.Assignments[h.ToAssignmentID]; to != nil && to.WorkerID == h.ReceiverID {
   576						if to.Kind == "node" && smp.Status == "in_transit" {
   577							smp.Status = "at_node"
   578						}
   579					}
   580				}
   581				a.auditLocked(u.UserID, roleOf(r), "handoff.confirm", "handoff", h.HandoffID, true, map[string]interface{}{"sampleId": h.SampleID, "completed": true})
   582				a.emitLocked("handoff.confirmed", "handoff", h.HandoffID, map[string]interface{}{"sampleId": h.SampleID, "holderId": h.ReceiverID}, nil)
   583				out = map[string]interface{}{"handoffId": h.HandoffID, "status": "confirmed", "currentHolderId": h.ReceiverID}
   584			} else {
   585				a.auditLocked(u.UserID, roleOf(r), "handoff.confirm", "handoff", h.HandoffID, true, map[string]interface{}{"sampleId": h.SampleID, "side": req.Side, "completed": false})
   586				out = map[string]interface{}{"handoffId": h.HandoffID, "status": "pending", "currentHolderId": h.SenderID}
   587			}
   588			return nil
   589		})
   590		if e != nil {
   591			writeErr(w, e)
   592			return
   593		}
   594		writeData(w, 200, out)
   595	}
