   648	// ---------- laboratory receipt ----------
   649	
   650	func (a *App) confirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
   651		if !a.requireRole(w, r, "laboratory_team") {
   652			return
   653		}
   654		var req struct {
   655			SampleID      string `json:"sampleId"`
   656			LaboratoryID  string `json:"laboratoryId"`
   657			ReceivedAt    string `json:"receivedAt"`
   658			ConditionNote string `json:"conditionNote"`
   659		}
   660		if !decodeBody(w, r, &req) {
   661			return
   662		}
   663		receivedAt, ok := parseTime(req.ReceivedAt)
   664		if !ok {
   665			writeErr(w, errAPI(400, "invalid_time", "receivedAt must be RFC3339"))
   666			return
   667		}
   668		u := getUser(r)
   669		var out map[string]interface{}
   670		e := a.mutate(func(st *State) *apiError {
   671			smp := st.Samples[req.SampleID]
   672			if smp == nil {
   673				return errAPI(404, "not_found", "sample not found")
   674			}
   675			lab := st.Locations[req.LaboratoryID]
   676			if lab == nil || !lab.Functions.Laboratory {
   677				return errAPI(404, "not_found", "laboratory not found")
   678			}
   679			if u.AssignedLocationID != lab.LocationID {
   680				return errAPI(403, "forbidden", "not assigned to this laboratory")
   681			}
   682			if !lab.Active {
   683				return errAPI(409, "laboratory_inactive", "laboratory is inactive")
   684			}
   685			if !labAccepts(st, lab, smp.SampleTypeID) {
   686				return errAPI(409, "laboratory_not_accepting", "laboratory does not accept this sample type")
   687			}
   688			if smp.Status == "received" {
   689				out = map[string]interface{}{"sampleId": smp.SampleID, "status": "received", "receivedAt": tptr(smp.ReceivedAt)}
   690				return nil
   691			}
   692			if smp.CurrentHolderID != u.UserID {
   693				return errAPI(409, "custody_required", "you must hold custody of the sample before confirming receipt")
   694			}
   695			if receivedAt.After(smp.DeliveryDeadline) {
   696				smp.Status = "expired"
   697				smp.ExceptionReason = "delivery_deadline_exceeded"
   698				return errAPI(409, "delivery_deadline_exceeded", "sample arrived after its delivery deadline")
   699			}
   700			now := time.Now().UTC()
   701			smp.Status = "received"
   702			smp.ReceivedAt = &receivedAt
   703			smp.ReceivedLaboratoryID = lab.LocationID
   704			c := lab.Coordinate
   705			smp.LatestLocation = &c
   706			smp.LocationRecordedAt = &now
   707			if j := st.Journeys[smp.ActiveJourneyID]; j != nil {
   708				j.Status = "completed"
   709				for _, id := range smp.ActiveAssignmentIDs {
   710					if as := st.Assignments[id]; as != nil && (as.Status == "pending" || as.Status == "accepted" || as.Status == "in_progress") {
   711						as.Status = "completed"
   712						as.CompletedAt = &now
   713					}
   714				}
   715				smp.ActiveAssignmentIDs = []string{}
   716				releaseCapacityLocked(st, journeyRoute(st, j), st.SampleTypes[smp.SampleTypeID] != nil && st.SampleTypes[smp.SampleTypeID].RequiresCooledRoute, 1)
   717			}
   718			a.auditLocked(u.UserID, roleOf(r), "laboratory.receipt", "sample", smp.SampleID, true, map[string]interface{}{"laboratoryId": lab.LocationID, "receivedAt": timeStr(receivedAt)})
   719			a.emitLocked("sample.received", "sample", smp.SampleID, map[string]interface{}{"laboratoryId": lab.LocationID}, nil)
   720			out = map[string]interface{}{"sampleId": smp.SampleID, "status": "received", "receivedAt": timeStr(receivedAt)}
   721			return nil
   722		})
   723		if e != nil {
   724			writeErr(w, e)
   725			return
   726		}
   727		writeData(w, 200, out)
   728	}
