package main

import (
	"net/http"
	"time"
)

// ---------- role work listing ----------

func assignmentWorkItemJSON(st *State, as *Assignment) map[string]interface{} {
	m := map[string]interface{}{
		"kind": as.Kind, "assignmentId": as.AssignmentID, "assignment_id": as.AssignmentID,
		"journeyId": as.JourneyID, "sampleId": as.SampleID, "sample_id": as.SampleID,
		"sequence": as.Sequence, "status": as.Status,
		"history": assignmentTimeline(st, as.AssignmentID),
	}
	if as.FromLocationID != "" {
		m["fromLocationId"] = as.FromLocationID
	}
	if as.ToLocationID != "" {
		m["toLocationId"] = as.ToLocationID
	}
	if as.NodeID != "" {
		m["nodeId"] = as.NodeID
		m["incomingFromLocationId"] = as.FromLocationID
		m["outgoingToLocationId"] = as.ToLocationID
	}
	if as.LaboratoryID != "" {
		m["laboratoryId"] = as.LaboratoryID
		if smp := st.Samples[as.SampleID]; smp != nil {
			m["expectedSampleTypeId"] = smp.SampleTypeID
		}
	}
	if as.WorkerID != "" {
		m["workerId"] = as.WorkerID
	}
	if as.OfferExpiresAt != nil {
		m["offerExpiresAt"] = timeStr(*as.OfferExpiresAt)
	}
	if as.ToLocationID != "" {
		if l := st.Locations[as.ToLocationID]; l != nil {
			m["destinationCapacity"] = capJSON(l.Capacity)
		}
	}
	return m
}

func assignmentTimeline(st *State, assignmentID string) []interface{} {
	out := []interface{}{}
	for _, e := range st.Audit {
		if e.EntityID == assignmentID || e.Details["assignmentId"] == assignmentID {
			out = append(out, map[string]interface{}{
				"eventId": len(out) + 1, "action": e.Action, "actorId": e.ActorID,
				"role": e.Role, "entityType": e.EntityType, "entityId": e.EntityID,
				"success": e.Success, "occurredAt": timeStr(e.OccurredAt), "details": e.Details,
			})
		}
	}
	return out
}

func sampleWorkItemJSON(st *State, smp *Sample) map[string]interface{} {
	m := map[string]interface{}{
		"kind": "sample", "sampleId": smp.SampleID, "sample_id": smp.SampleID,
		"requestId": smp.RequestID, "status": smp.Status,
		"serviceability": smp.Serviceability,
		"requestedAt": timeStr(smp.RequestedAt), "deliveryDeadline": timeStr(smp.DeliveryDeadline),
		"earliestCollectionAt": timeStr(smp.EarliestCollectionAt),
		"latestCollectionAt":   timeStr(smp.LatestCollectionAt),
		"history":              sampleTimeline(st, smp.SampleID),
		"locationStale":        isStale(smp.LocationRecordedAt),
	}
	if smp.CurrentHolderID != "" {
		m["currentHolderId"] = smp.CurrentHolderID
	}
	if smp.RequesterID != "" {
		m["requesterId"] = smp.RequesterID
	}
	if smp.ActiveJourneyID != "" {
		m["activeJourneyId"] = smp.ActiveJourneyID
		m["journeyId"] = smp.ActiveJourneyID
	}
	if smp.TargetLaboratoryID != "" {
		m["laboratoryId"] = smp.TargetLaboratoryID
	}
	if smp.LocationRecordedAt != nil {
		m["locationRecordedAt"] = timeStr(*smp.LocationRecordedAt)
	}
	return m
}

func journeyWorkItemJSON(st *State, j *Journey) map[string]interface{} {
	n := len(j.CollectionAssignmentIDs) + len(j.LegAssignmentIDs) + len(j.NodeAssignmentIDs) + len(j.LaboratoryAssignmentIDs)
	est := ""
	if j.EstimatedDeliveryAt != nil {
		est = timeStr(*j.EstimatedDeliveryAt)
	}
	hist := []interface{}{}
	for _, e := range st.Audit {
		if e.EntityID == j.JourneyID || e.Details["journeyId"] == j.JourneyID {
			hist = append(hist, map[string]interface{}{
				"eventId": len(hist) + 1, "action": e.Action, "actorId": e.ActorID,
				"role": e.Role, "entityType": e.EntityType, "entityId": e.EntityID,
				"success": e.Success, "occurredAt": timeStr(e.OccurredAt), "details": e.Details,
			})
		}
	}
	return map[string]interface{}{
		"kind": "journey", "journeyId": j.JourneyID, "journey_id": j.JourneyID,
		"status": j.Status, "routeMode": j.RouteMode, "planVersion": j.PlanVersion,
		"sampleIds": j.SampleIDs, "estimatedDeliveryAt": est,
		"assignmentCount": n, "history": hist,
	}
}

func (a *App) listRoleWork(w http.ResponseWriter, r *http.Request) {
	var req struct {
		Role   string `json:"role"`
		Status string `json:"status"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	role := req.Role
	validRoles := map[string]bool{"requester": true, "collection_professional": true, "delivery_partner": true, "node_handler": true, "laboratory_team": true, "dispatcher": true, "administrator": true}
	if !validRoles[role] {
		writeErr(w, errAPI(400, "invalid_role", "unknown role"))
		return
	}
	sess := getSession(r)
	if sess.ActiveRole == "" {
		writeErr(w, errAPI(409, "role_not_selected", "select an active role first"))
		return
	}
	if sess.ActiveRole != role {
		writeErr(w, errAPI(403, "forbidden", "requested role does not match selected role"))
		return
	}
	u := getUser(r)
	pending := []interface{}{}
	inProgress := []interface{}{}
	completed := []interface{}{}
	e := a.mutate(func(st *State) *apiError {
		a.expireOffersLocked(st)
		push := func(as *Assignment) {
			item := assignmentWorkItemJSON(st, as)
			switch {
			case as.Status == "pending":
				pending = append(pending, item)
			case as.Status == "accepted" || as.Status == "in_progress":
				inProgress = append(inProgress, item)
			case as.Status == "completed":
				completed = append(completed, item)
			}
		}
		switch role {
		case "requester":
			for _, smp := range st.Samples {
				if smp.RequesterID != u.UserID {
					continue
				}
				item := sampleWorkItemJSON(st, smp)
				switch smp.Status {
				case "received", "expired", "cancelled":
					completed = append(completed, item)
				case "exception":
					inProgress = append(inProgress, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		case "collection_professional", "delivery_partner", "node_handler", "laboratory_team":
			kind := map[string]string{
				"collection_professional": "collection", "delivery_partner": "transport",
				"node_handler": "node", "laboratory_team": "laboratory",
			}[role]
			for _, as := range st.Assignments {
				if as.Kind != kind {
					continue
				}
				if as.Status == "pending" && as.OfferedTo == u.UserID {
					push(as)
				} else if as.WorkerID == u.UserID {
					push(as)
				}
			}
		case "dispatcher", "administrator":
			for _, j := range st.Journeys {
				item := journeyWorkItemJSON(st, j)
				switch j.Status {
				case "completed", "cancelled", "expired":
					completed = append(completed, item)
				case "planned":
					pending = append(pending, item)
				default:
					inProgress = append(inProgress, item)
				}
			}
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	if req.Status != "" {
		switch req.Status {
		case "pending":
			inProgress, completed = []interface{}{}, []interface{}{}
		case "in_progress":
			pending, completed = []interface{}{}, []interface{}{}
		case "completed":
			pending, inProgress = []interface{}{}, []interface{}{}
		}
	}
	writeData(w, 200, map[string]interface{}{
		"pending": pending, "inProgress": inProgress, "completed": completed,
	})
}

// ---------- accept / decline ----------

func (a *App) acceptAssignment(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	a.idempotent(w, r, "accept_assignment", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		u := getUser(r)
		var out map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			a.expireOffersLocked(st)
			as := st.Assignments[req.AssignmentID]
			if as == nil {
				return errAPI(404, "not_found", "assignment not found")
			}
			if as.Status != "pending" {
				return errAPI(409, "assignment_not_pending", "assignment is not awaiting acceptance")
			}
			if as.OfferedTo != u.UserID {
				return errAPI(403, "ineligible_worker", "assignment was not offered to you")
			}
			now := time.Now().UTC()
			as.Status = "accepted"
			as.WorkerID = u.UserID
			as.AcceptedAt = &now
			as.OfferedTo = ""
			as.OfferExpiresAt = nil
			a.auditLocked(u.UserID, roleOf(r), "assignment.accept", "assignment", as.AssignmentID, true, map[string]interface{}{"journeyId": as.JourneyID, "sampleId": as.SampleID})
			a.emitLocked("assignment.accepted", "assignment", as.AssignmentID, map[string]interface{}{"workerId": u.UserID}, nil)
			out = map[string]interface{}{"assignmentId": as.AssignmentID, "status": "accepted", "workerId": u.UserID}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, out, nil
	})
}

func (a *App) declineAssignment(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Reason         string `json:"reason"`
		DeclinedAt     string `json:"declinedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	a.idempotent(w, r, "decline_assignment", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		u := getUser(r)
		var out map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			a.expireOffersLocked(st)
			as := st.Assignments[req.AssignmentID]
			if as == nil {
				return errAPI(404, "not_found", "assignment not found")
			}
			if as.Status != "pending" {
				return errAPI(409, "assignment_not_pending", "assignment is not awaiting acceptance")
			}
			if as.OfferedTo != u.UserID {
				return errAPI(403, "ineligible_worker", "assignment was not offered to you")
			}
			as.DeclinedBy = append(as.DeclinedBy, u.UserID)
			u.RecentDeclines++
			if u.RecentDeclines >= 3 {
				t := time.Now().Add(10 * time.Minute)
				u.DeclinePenaltyTill = &t
				u.RecentDeclines = 0
			}
			declinedAt := time.Now().UTC()
			if t, ok := parseTime(req.DeclinedAt); ok {
				declinedAt = t
			}
			a.auditLocked(u.UserID, roleOf(r), "assignment.decline", "assignment", as.AssignmentID, true, map[string]interface{}{"reason": req.Reason})
			sample := st.Samples[as.SampleID]
			nw := a.offerAssignmentLocked(st, as, sample)
			out = map[string]interface{}{
				"assignmentId": as.AssignmentID, "status": "pending",
				"declinedBy": u.UserID, "declinedAt": timeStr(declinedAt),
			}
			if nw != nil {
				out["reofferedTo"] = nw.UserID
			}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, out, nil
	})
}

// ---------- collect & seal ----------

func (a *App) collectAndSealSample(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "collection_professional") {
		return
	}
	var req struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		CollectedAt          string  `json:"collectedAt"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	collectedAt, ok := parseTime(req.CollectedAt)
	if !ok {
		writeErr(w, errAPI(400, "invalid_time", "collectedAt must be RFC3339"))
		return
	}
	a.idempotent(w, r, "collect_and_seal_sample", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		u := getUser(r)
		var out map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			as := st.Assignments[req.AssignmentID]
			if as == nil || as.Kind != "collection" {
				return errAPI(404, "not_found", "collection assignment not found")
			}
			if as.WorkerID != u.UserID || (as.Status != "accepted" && as.Status != "in_progress") {
				return errAPI(403, "forbidden", "not your accepted collection assignment")
			}
			smp := st.Samples[as.SampleID]
			if smp == nil || smp.SampleID != req.SampleID {
				return errAPI(404, "not_found", "sample not found")
			}
			if collectedAt.Before(smp.EarliestCollectionAt) || collectedAt.After(smp.LatestCollectionAt) {
				return errAPI(409, "collection_window_violation", "collection time outside the collection window")
			}
			stype := st.SampleTypes[smp.SampleTypeID]
			if stype != nil && stype.QualifiedCollectorRequired {
				okq := containsStr(u.Qualifications, stype.RequiredQualification)
				for _, c := range u.Certifications {
					if c.Code == stype.RequiredQualification && c.Active && (c.ExpiresAt == nil || c.ExpiresAt.After(time.Now())) {
						okq = true
					}
				}
				if !okq {
					return errAPI(403, "forbidden", "collector lacks required qualification")
				}
			}
			compliant := req.ContainerType == smp.ContainerType &&
				req.ObservedTemperatureC >= smp.TemperatureMinC && req.ObservedTemperatureC <= smp.TemperatureMaxC
			if !compliant {
				return errAPI(400, "handling_noncompliant", "container or temperature does not satisfy sample requirements")
			}
			now := time.Now().UTC()
			smp.Sealed = true
			smp.SealedAt = &collectedAt
			smp.Status = "sealed"
			smp.CurrentHolderID = u.UserID
			loc := u.LatestLocation
			if loc == nil {
				c := smp.Origin
				loc = &c
			}
			smp.LatestLocation = loc
			smp.LocationRecordedAt = &now
			as.Status = "completed"
			as.CompletedAt = &now
			smp.ActiveAssignmentIDs = removeStr(smp.ActiveAssignmentIDs, as.AssignmentID)
			a.auditLocked(u.UserID, roleOf(r), "sample.collect_seal", "sample", smp.SampleID, true, map[string]interface{}{"assignmentId": as.AssignmentID, "collectedAt": timeStr(collectedAt)})
			a.emitLocked("sample.sealed", "sample", smp.SampleID, map[string]interface{}{"holderId": u.UserID}, nil)
			j := st.Journeys[as.JourneyID]
			if j != nil {
				j.Status = "in_progress"
				a.offerNextAfterLocked(st, j, smp)
			}
			out = map[string]interface{}{
				"sampleId": smp.SampleID, "status": "sealed", "sealedAt": timeStr(collectedAt),
				"currentHolderId": u.UserID, "handlingCompliant": true,
			}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, out, nil
	})
}

// ---------- progress & location ----------

var validProgress = map[string]bool{
	"at_pickup": true, "picked_up": true, "in_transit": true,
	"arrived": true, "delivered": true, "in_progress": true, "completed": true,
}

func (a *App) updateAssignmentProgress(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		AssignmentID   string `json:"assignmentId"`
		Status         string `json:"status"`
		OccurredAt     string `json:"occurredAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if !validProgress[req.Status] {
		writeErr(w, errAPI(400, "invalid_assignment_status", "unknown progress status"))
		return
	}
	a.idempotent(w, r, "update_assignment_progress", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		u := getUser(r)
		var out map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			as := st.Assignments[req.AssignmentID]
			if as == nil {
				return errAPI(404, "not_found", "assignment not found")
			}
			if as.WorkerID != u.UserID {
				return errAPI(403, "forbidden", "not your assignment")
			}
			if as.Status != "accepted" && as.Status != "in_progress" {
				return errAPI(409, "invalid_assignment_status", "assignment not active")
			}
			smp := st.Samples[as.SampleID]
			if req.Status == "picked_up" {
				if smp != nil && smp.CurrentHolderID != u.UserID {
					return errAPI(409, "custody_required", "you must hold custody before pickup")
				}
			}
			now := time.Now().UTC()
			as.ProgressStatus = req.Status
			if req.Status != "delivered" && req.Status != "completed" {
				as.Status = "in_progress"
			}
			if smp != nil {
				switch req.Status {
				case "picked_up", "in_transit":
					smp.Status = "in_transit"
				case "delivered", "completed":
					as.Status = "completed"
					as.CompletedAt = &now
					smp.ActiveAssignmentIDs = removeStr(smp.ActiveAssignmentIDs, as.AssignmentID)
					smp.CompletedLegIDs = append(smp.CompletedLegIDs, as.AssignmentID)
					// current holder stays until handoff confirmed
					j := st.Journeys[as.JourneyID]
					if j != nil {
						a.offerNextAfterLocked(st, j, smp)
					}
				}
			}
			a.auditLocked(u.UserID, roleOf(r), "assignment.progress", "assignment", as.AssignmentID, true, map[string]interface{}{"status": req.Status})
			a.emitLocked("assignment.progress", "assignment", as.AssignmentID, map[string]interface{}{"status": req.Status, "sampleId": as.SampleID}, nil)
			out = map[string]interface{}{"assignmentId": as.AssignmentID, "sampleId": as.SampleID, "status": req.Status}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, out, nil
	})
}

func (a *App) recordWorkerLocation(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "collection_professional", "delivery_partner") {
		return
	}
	var req struct {
		AssignmentID string     `json:"assignmentId"`
		Coordinate   Coordinate `json:"coordinate"`
		Sequence     int        `json:"sequence"`
		RecordedAt   string     `json:"recordedAt"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.Coordinate.Latitude < -90 || req.Coordinate.Latitude > 90 || req.Coordinate.Longitude < -180 || req.Coordinate.Longitude > 180 {
		writeErr(w, errAPI(400, "invalid_coordinate", "coordinate out of range"))
		return
	}
	if req.Sequence < 1 {
		writeErr(w, errAPI(400, "invalid_sequence", "sequence must be at least 1"))
		return
	}
	recordedAt := time.Now().UTC()
	if t, ok := parseTime(req.RecordedAt); ok {
		recordedAt = t
	}
	u := getUser(r)
	var out map[string]interface{}
	e := a.mutate(func(st *State) *apiError {
		as := st.Assignments[req.AssignmentID]
		if as == nil {
			return errAPI(404, "not_found", "assignment not found")
		}
		if as.WorkerID != u.UserID {
			return errAPI(403, "forbidden", "not your assignment")
		}
		if req.Sequence <= u.LastLocationSeq {
			return errAPI(409, "stale_location", "location sequence is not newer than the last recorded update")
		}
		u.LastLocationSeq = req.Sequence
		c := req.Coordinate
		u.LatestLocation = &c
		u.LocationRecordedAt = &recordedAt
		// propagate to samples currently held by this worker
		for _, smp := range st.Samples {
			if smp.CurrentHolderID == u.UserID {
				smp.LatestLocation = &c
				smp.LocationRecordedAt = &recordedAt
			}
		}
		a.auditLocked(u.UserID, roleOf(r), "worker.record_location", "assignment", as.AssignmentID, true, map[string]interface{}{"sequence": req.Sequence})
		a.emitLocked("worker.location", "user", u.UserID, map[string]interface{}{"coordinate": c, "recordedAt": timeStr(recordedAt)}, nil)
		out = map[string]interface{}{
			"assignmentId": as.AssignmentID, "coordinate": c,
			"sequence": req.Sequence, "recordedAt": timeStr(recordedAt),
		}
		return nil
	})
	if e != nil {
		writeErr(w, e)
		return
	}
	writeData(w, 201, out)
}

// ---------- handoffs ----------

func (a *App) initiateHandoff(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		SampleID         string `json:"sampleId"`
		FromAssignmentID string `json:"fromAssignmentId"`
		ToAssignmentID   string `json:"toAssignmentId"`
		ReceiverID       string `json:"receiverId"`
		InitiatedAt      string `json:"initiatedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	a.idempotent(w, r, "initiate_handoff", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		u := getUser(r)
		var out map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			smp := st.Samples[req.SampleID]
			if smp == nil {
				return errAPI(404, "not_found", "sample not found")
			}
			if smp.CurrentHolderID != u.UserID {
				return errAPI(409, "custody_required", "you are not the current holder")
			}
			if smp.PendingHandoffID != "" {
				if h := st.Handoffs[smp.PendingHandoffID]; h != nil && h.Status == "pending" {
					return errAPI(409, "handoff_state_invalid", "a handoff is already pending for this sample")
				}
			}
			recv := st.Users[req.ReceiverID]
			if recv == nil {
				return errAPI(404, "not_found", "receiver not found")
			}
			initiatedAt := time.Now().UTC()
			if t, ok := parseTime(req.InitiatedAt); ok {
				initiatedAt = t
			}
			h := &Handoff{
				HandoffID: newUUID(), SampleID: smp.SampleID, FromAssignmentID: req.FromAssignmentID,
				ToAssignmentID: req.ToAssignmentID, SenderID: u.UserID, ReceiverID: req.ReceiverID,
				Status: "pending", InitiatedAt: initiatedAt,
			}
			st.Handoffs[h.HandoffID] = h
			smp.PendingHandoffID = h.HandoffID
			a.auditLocked(u.UserID, roleOf(r), "handoff.initiate", "handoff", h.HandoffID, true, map[string]interface{}{"sampleId": smp.SampleID, "receiverId": req.ReceiverID})
			a.emitLocked("handoff.initiated", "handoff", h.HandoffID, map[string]interface{}{"sampleId": smp.SampleID}, nil)
			out = map[string]interface{}{
				"handoffId": h.HandoffID, "senderId": u.UserID, "receiverId": req.ReceiverID,
				"status": "pending", "currentHolderId": u.UserID,
			}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, out, nil
	})
}

func (a *App) confirmHandoff(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		HandoffID        string `json:"handoffId"`
		ConfirmationSide string `json:"confirmationSide"`
		ConfirmedAt      string `json:"confirmedAt"`
		IdempotencyKey   string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	if req.ConfirmationSide != "sender" && req.ConfirmationSide != "receiver" {
		writeErr(w, errAPI(400, "invalid_handoff_side", "confirmationSide must be sender or receiver"))
		return
	}
	a.idempotent(w, r, "confirm_handoff", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		u := getUser(r)
		var out map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			h := st.Handoffs[req.HandoffID]
			if h == nil {
				return errAPI(404, "not_found", "handoff not found")
			}
			if h.Status == "confirmed" {
				// idempotent re-confirmation; never duplicate custody transfer
				out = map[string]interface{}{
					"handoffId": h.HandoffID, "status": "confirmed",
					"senderConfirmed": true, "receiverConfirmed": true,
					"currentHolderId": h.ReceiverID,
				}
				return nil
			}
			if h.Status != "pending" {
				return errAPI(409, "handoff_state_invalid", "handoff is not pending")
			}
			if req.ConfirmationSide == "sender" {
				if h.SenderID != u.UserID {
					return errAPI(403, "forbidden", "only the sender can confirm the sender side")
				}
				h.SenderConfirmed = true
			} else {
				if h.ReceiverID != u.UserID {
					return errAPI(403, "forbidden", "only the receiver can confirm the receiver side")
				}
				h.ReceiverConfirmed = true
			}
			smp := st.Samples[h.SampleID]
			if h.SenderConfirmed && h.ReceiverConfirmed {
				now := time.Now().UTC()
				h.Status = "confirmed"
				h.ConfirmedAt = &now
				if smp != nil {
					smp.CurrentHolderID = h.ReceiverID
					smp.PendingHandoffID = ""
					smp.LocationRecordedAt = &now
					if recv := st.Users[h.ReceiverID]; recv != nil && recv.LatestLocation != nil {
						smp.LatestLocation = recv.LatestLocation
					}
					if to := st.Assignments[h.ToAssignmentID]; to != nil && to.WorkerID == h.ReceiverID {
						if to.Kind == "node" && smp.Status == "in_transit" {
							smp.Status = "at_node"
						}
					}
				}
				a.auditLocked(u.UserID, roleOf(r), "handoff.confirm", "handoff", h.HandoffID, true, map[string]interface{}{"sampleId": h.SampleID, "completed": true})
				a.emitLocked("handoff.confirmed", "handoff", h.HandoffID, map[string]interface{}{"sampleId": h.SampleID, "holderId": h.ReceiverID}, nil)
			} else {
				a.auditLocked(u.UserID, roleOf(r), "handoff.confirm", "handoff", h.HandoffID, true, map[string]interface{}{"sampleId": h.SampleID, "side": req.ConfirmationSide, "completed": false})
			}
			holder := h.SenderID
			if h.Status == "confirmed" {
				holder = h.ReceiverID
			}
			out = map[string]interface{}{
				"handoffId": h.HandoffID, "status": h.Status,
				"senderConfirmed": h.SenderConfirmed, "receiverConfirmed": h.ReceiverConfirmed,
				"currentHolderId": holder,
			}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, out, nil
	})
}

// ---------- handling checkpoint ----------

func (a *App) recordHandlingCheckpoint(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "collection_professional", "delivery_partner", "node_handler", "laboratory_team") {
		return
	}
	var req struct {
		SampleID             string  `json:"sampleId"`
		AssignmentID         string  `json:"assignmentId"`
		LocationID           string  `json:"locationId"`
		ContainerType        string  `json:"containerType"`
		ObservedTemperatureC float64 `json:"observedTemperatureC"`
		RecordedAt           string  `json:"recordedAt"`
		IdempotencyKey       string  `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	a.idempotent(w, r, "record_handling_checkpoint", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		u := getUser(r)
		var out map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			smp := st.Samples[req.SampleID]
			if smp == nil {
				return errAPI(404, "not_found", "sample not found")
			}
			if smp.CurrentHolderID != u.UserID {
				return errAPI(409, "custody_required", "you are not the current holder")
			}
			compliant := req.ContainerType == smp.ContainerType &&
				req.ObservedTemperatureC >= smp.TemperatureMinC && req.ObservedTemperatureC <= smp.TemperatureMaxC
			recordedAt := time.Now().UTC()
			if t, ok := parseTime(req.RecordedAt); ok {
				recordedAt = t
			}
			cp := &Checkpoint{
				CheckpointID: newUUID(), SampleID: smp.SampleID, AssignmentID: req.AssignmentID,
				LocationID: req.LocationID, ContainerType: req.ContainerType,
				ObservedTemperatureC: req.ObservedTemperatureC, Compliant: compliant,
				RecordedBy: u.UserID, RecordedAt: recordedAt,
			}
			st.Checkpoints[cp.CheckpointID] = cp
			if !compliant && smp.Status != "received" {
				smp.Status = "exception"
				smp.ExceptionReason = "handling_noncompliant"
				a.emitLocked("sample.exception", "sample", smp.SampleID, map[string]interface{}{"reason": "handling_noncompliant"}, nil)
			}
			a.auditLocked(u.UserID, roleOf(r), "handling.checkpoint", "sample", smp.SampleID, true, map[string]interface{}{"compliant": compliant, "observedTemperatureC": req.ObservedTemperatureC})
			out = map[string]interface{}{
				"checkpointId": cp.CheckpointID, "sampleId": smp.SampleID,
				"compliant": compliant, "sampleStatus": smp.Status,
			}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, out, nil
	})
}

// ---------- laboratory receipt ----------

func (a *App) confirmLaboratoryReceipt(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "laboratory_team") {
		return
	}
	var req struct {
		SampleID       string `json:"sampleId"`
		LaboratoryID   string `json:"laboratoryId"`
		ReceivedAt     string `json:"receivedAt"`
		IdempotencyKey string `json:"idempotencyKey"`
	}
	if !decodeBody(w, r, &req) {
		return
	}
	receivedAt, ok := parseTime(req.ReceivedAt)
	if !ok {
		writeErr(w, errAPI(400, "invalid_time", "receivedAt must be RFC3339"))
		return
	}
	a.idempotent(w, r, "confirm_laboratory_receipt", rawBody(r), req.IdempotencyKey, func() (int, interface{}, *apiError) {
		u := getUser(r)
		var out map[string]interface{}
		e := a.mutate(func(st *State) *apiError {
			smp := st.Samples[req.SampleID]
			if smp == nil {
				return errAPI(404, "not_found", "sample not found")
			}
			lab := st.Locations[req.LaboratoryID]
			if lab == nil || !lab.Functions.Laboratory {
				return errAPI(404, "not_found", "laboratory not found")
			}
			if u.AssignedLocationID != lab.LocationID {
				return errAPI(403, "forbidden", "not assigned to this laboratory")
			}
			if !lab.Active {
				return errAPI(409, "laboratory_inactive", "laboratory is inactive")
			}
			if !labAccepts(st, lab, smp.SampleTypeID) {
				return errAPI(409, "laboratory_not_accepting", "laboratory does not accept this sample type")
			}
			if smp.Status == "received" {
				out = map[string]interface{}{"sampleId": smp.SampleID, "laboratoryId": lab.LocationID, "status": "received", "receivedAt": tptr(smp.ReceivedAt)}
				return nil
			}
			if smp.CurrentHolderID != u.UserID {
				return errAPI(409, "custody_required", "you must hold custody of the sample before confirming receipt")
			}
			if receivedAt.After(smp.DeliveryDeadline) {
				smp.Status = "expired"
				smp.ExceptionReason = "delivery_deadline_exceeded"
				return errAPI(409, "delivery_deadline_exceeded", "sample arrived after its delivery deadline")
			}
			now := time.Now().UTC()
			smp.Status = "received"
			smp.ReceivedAt = &receivedAt
			smp.ReceivedLaboratoryID = lab.LocationID
			c := lab.Coordinate
			smp.LatestLocation = &c
			smp.LocationRecordedAt = &now
			if j := st.Journeys[smp.ActiveJourneyID]; j != nil {
				j.Status = "completed"
				for _, id := range smp.ActiveAssignmentIDs {
					if as := st.Assignments[id]; as != nil && (as.Status == "pending" || as.Status == "accepted" || as.Status == "in_progress") {
						as.Status = "completed"
						as.CompletedAt = &now
					}
				}
				smp.ActiveAssignmentIDs = []string{}
				releaseCapacityLocked(st, journeyRoute(st, j), st.SampleTypes[smp.SampleTypeID] != nil && st.SampleTypes[smp.SampleTypeID].RequiresCooledRoute, 1)
			}
			a.auditLocked(u.UserID, roleOf(r), "laboratory.receipt", "sample", smp.SampleID, true, map[string]interface{}{"laboratoryId": lab.LocationID, "receivedAt": timeStr(receivedAt)})
			a.emitLocked("sample.received", "sample", smp.SampleID, map[string]interface{}{"laboratoryId": lab.LocationID}, nil)
			out = map[string]interface{}{"sampleId": smp.SampleID, "laboratoryId": lab.LocationID, "status": "received", "receivedAt": timeStr(receivedAt)}
			return nil
		})
		if e != nil {
			return 0, nil, e
		}
		return 201, out, nil
	})
}

func (a *App) recordLaboratoryException(w http.ResponseWriter, r *http.Request) {
	if !a.requireRole(w, r, "laboratory_team") {
		return
	}
	var req struct {
