package main

import (
	"context"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"time"

	"github.com/jackc/pgx/v5/pgxpool"
)

func seedSampleTypes(st *State) {
	if st.Seeded {
		return
	}
	mk := func(name, container string, tmin, tmax float64, cooled, batching bool, incomp []string) {
		t := &SampleType{
			SampleTypeID: newUUID(), Name: name, QualifiedCollectorRequired: true,
			RequiredQualification: name, ContainerType: container,
			TemperatureMinC: tmin, TemperatureMaxC: tmax,
			IncompatibleSampleTypes: incomp, RequiresCooledRoute: cooled, BatchingAllowed: batching,
		}
		st.SampleTypes[t.SampleTypeID] = t
	}
	mk("Amber", "standard", 2, 25, false, true, nil)
	mk("Indigo", "standard", 2, 25, false, true, []string{"Amber"})
	mk("Frost", "cooler", -20, 4, true, true, nil)
	mk("Pulse", "standard", 2, 25, false, false, nil)
	st.Seeded = true
}

func (a *App) ensureAdmin() {
	username := os.Getenv("ADMIN_USERNAME")
	password := os.Getenv("ADMIN_PASSWORD")
	if username == "" {
		username = "admin"
	}
	if password == "" {
		password = "admin"
	}
	a.mutate(func(st *State) *apiError {
		seedSampleTypes(st)
		for _, u := range st.Users {
			if u.Username == username {
				return nil
			}
		}
		u := &User{
			UserID: newUUID(), Username: username, PasswordHash: hashPassword(password),
			Roles: []string{"administrator", "dispatcher"}, Active: true,
			Available: true, CapacityUnits: 1, CreatedAt: time.Now().UTC(),
		}
		st.Users[u.UserID] = u
		a.auditLocked(u.UserID, "administrator", "user.create", "user", u.UserID, true, map[string]interface{}{"bootstrap": true})
		return nil
	})
}

func cors(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		w.Header().Set("Access-Control-Allow-Origin", "*")
		w.Header().Set("Access-Control-Allow-Headers", "Authorization, Content-Type")
		w.Header().Set("Access-Control-Allow-Methods", "GET, POST, OPTIONS")
		if r.Method == "OPTIONS" {
			w.WriteHeader(204)
			return
		}
		next.ServeHTTP(w, r)
	})
}

func main() {
	dbURL := os.Getenv("DATABASE_URL")
	if dbURL == "" {
		dbURL = "postgres://postgres@127.0.0.1:5432/labdb?sslmode=disable"
	}
	ctx := context.Background()
	var pool *pgxpool.Pool
	var err error
	for i := 0; i < 30; i++ {
		pool, err = pgxpool.New(ctx, dbURL)
		if err == nil {
			err = pool.Ping(ctx)
		}
		if err == nil {
			break
		}
		time.Sleep(time.Second)
	}
	if err != nil {
		log.Fatalf("cannot connect to postgres: %v", err)
	}
	app := NewApp(pool)
	if err := app.EnsureSchema(ctx); err != nil {
		log.Fatalf("schema: %v", err)
	}
	if err := app.Load(ctx); err != nil {
		log.Fatalf("load: %v", err)
	}
	app.ensureAdmin()

	mux := http.NewServeMux()
	pub := func(p string, h http.HandlerFunc) { mux.HandleFunc(p, h) }
	aut := func(p string, h http.HandlerFunc) { mux.HandleFunc(p, app.authMiddleware(h)) }

	pub("POST /api/authenticate-user", app.authenticateUser)
	aut("POST /api/select-active-role", app.selectActiveRole)
	aut("POST /api/create-user", app.createUser)
	aut("POST /api/update-user-access", app.updateUserAccess)
	aut("GET /api/read-user/{userId}", app.readUser)
	aut("POST /api/create-location", app.createLocation)
	aut("POST /api/update-location", app.updateLocation)
	aut("POST /api/set-location-status", app.setLocationStatus)
	aut("POST /api/set-location-function-status", app.setLocationFunctionStatus)
	aut("POST /api/create-connection", app.createConnection)
	aut("POST /api/set-connection-status", app.setConnectionStatus)
	aut("POST /api/create-sample-type", app.createSampleType)
	aut("POST /api/update-sample-type", app.updateSampleType)
	aut("POST /api/configure-capacity", app.configureCapacity)
	aut("POST /api/configure-laboratory-acceptance", app.configureLaboratoryAcceptance)
	aut("POST /api/set-worker-availability", app.setWorkerAvailability)
	aut("POST /api/check-serviceability", app.checkServiceability)
	aut("POST /api/create-collection-request", app.createCollectionRequest)
	aut("POST /api/ingest-presealed-sample", app.ingestPresealedSample)
	aut("POST /api/list-role-work", app.listRoleWork)
	aut("GET /api/read-sample-state/{sampleId}", app.readSampleState)
	aut("POST /api/read-sample-lifecycle", app.readSampleLifecycle)
	aut("POST /api/read-journey-plan", app.readJourneyPlan)
	aut("POST /api/read-operations-state", app.readOperationsState)
	aut("POST /api/read-serviceability-snapshot", app.readServiceabilitySnapshot)
	aut("POST /api/accept-assignment", app.acceptAssignment)
	aut("POST /api/decline-assignment", app.declineAssignment)
	aut("POST /api/collect-and-seal-sample", app.collectAndSealSample)
	aut("POST /api/update-assignment-progress", app.updateAssignmentProgress)
	aut("POST /api/record-worker-location", app.recordWorkerLocation)
	aut("POST /api/initiate-handoff", app.initiateHandoff)
