import { useCallback, useEffect, useState } from "react";
import { api, setToken, uuid, nowIso, ApiFailure } from "./api";
import MapView from "./MapView";

interface User {
  userId: string;
  username: string;
  roles: string[];
  activeRole: string;
  assignedLocationId?: string;
}

const ROLE_LABELS: Record<string, string> = {
  requester: "Requester",
  collection_professional: "Collection Professional",
  relay_courier: "Relay Courier",
  node_handler: "Node Handler",
  laboratory_team: "Laboratory Intake Operator",
  dispatcher: "Dispatcher",
  administrator: "Administrator",
};

const WORKER_ROLES = ["collection_professional", "relay_courier", "node_handler", "laboratory_team"];

export default function App() {
  const [user, setUser] = useState<User | null>(null);
  const [tab, setTab] = useState("work");
  const [refreshKey, setRefreshKey] = useState(0);
  const refresh = useCallback(() => setRefreshKey((k) => k + 1), []);

  if (!user) return <Login onLogin={setUser} />;

  const role = user.activeRole;
  const isWorker = WORKER_ROLES.includes(role);
  const isMonitor = role === "dispatcher" || role === "administrator";

  const tabs: [string, string][] = [];
  if (role === "requester") tabs.push(["requests", "My Requests"]);
  if (isWorker) tabs.push(["work", "My Work"]);
  if (isWorker) tabs.push(["capacity", "Capacity"]);
  tabs.push(["samples", "Samples"]);
  if (isMonitor) tabs.push(["monitor", "Monitor"]);
  if (isMonitor) tabs.push(["map", "Map"]);
  if (isMonitor) tabs.push(["audit", "Audit"]);
  if (role === "administrator") tabs.push(["admin", "Administration"]);

  const activeTab = tabs.some(([k]) => k === tab) ? tab : tabs[0]?.[0] ?? "samples";

  return (
    <div>
      <header>
        <h1>Lab Sample Pickup &amp; Delivery</h1>
        <span>Signed in as {user.username}</span>
        <label htmlFor="role-select" style={{ margin: 0, color: "#cdd8ea" }}>
          Active role
        </label>
        <select
          id="role-select"
          aria-label="Active role"
          value={role}
          onChange={async (e) => {
            const r = e.target.value;
            await api("/select-active-role", { role: r });
            setUser({ ...user, activeRole: r });
            setTab("work");
          }}
        >
          <option value="" disabled>
            Select role
          </option>
          {user.roles.map((r) => (
            <option key={r} value={r}>
              {ROLE_LABELS[r] ?? r}
            </option>
          ))}
        </select>
        <button
          className="small"
          onClick={() => {
            setToken(null);
            setUser(null);
          }}
        >
          Sign out
        </button>
      </header>
      <main>
        <nav className="tabs" aria-label="Views">
          {tabs.map(([k, label]) => (
            <button
              key={k}
              className={activeTab === k ? "active" : ""}
              onClick={() => setTab(k)}
            >
              {label}
            </button>
          ))}
        </nav>
        {!role && <p>Please select the role you are currently working under.</p>}
        {role && activeTab === "requests" && <RequesterPanel user={user} refreshKey={refreshKey} refresh={refresh} />}
        {role && activeTab === "work" && isWorker && <WorkPanel user={user} refreshKey={refreshKey} refresh={refresh} />}
        {role && activeTab === "capacity" && <CapacityPanel />}
        {role && activeTab === "samples" && <SamplesPanel user={user} />}
        {role && activeTab === "monitor" && isMonitor && <MonitorPanel />}
        {role && activeTab === "map" && isMonitor && <MapPanel />}
        {role && activeTab === "audit" && isMonitor && <AuditPanel />}
        {role && activeTab === "admin" && <AdminPanel refresh={refresh} />}
      </main>
    </div>
  );
}

function Login({ onLogin }: { onLogin: (u: User) => void }) {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const [error, setError] = useState("");

  return (
    <main style={{ maxWidth: 420, margin: "80px auto" }}>
      <div className="card">
        <h2>Sign in — Lab Sample Pickup &amp; Delivery</h2>
        <form
          onSubmit={async (e) => {
            e.preventDefault();
            setError("");
            try {
              const d = await api<any>("/authenticate-user", { username, password });
              setToken(d.sessionToken);
              const u: User = {
                userId: d.userId,
                username: d.username ?? username,
                roles: d.roles ?? [],
                activeRole: d.activeRole ?? "",
                assignedLocationId: d.assignedLocationId,
              };
              if (u.roles.length === 1 && !u.activeRole) {
                await api("/select-active-role", { role: u.roles[0] });
                u.activeRole = u.roles[0];
              }
              onLogin(u);
            } catch (err) {
              setError(err instanceof ApiFailure ? err.message : "Sign in failed");
            }
          }}
        >
          <label htmlFor="username">Username</label>
          <input id="username" value={username} onChange={(e) => setUsername(e.target.value)} autoComplete="username" />
          <label htmlFor="password">Password</label>
          <input id="password" type="password" value={password} onChange={(e) => setPassword(e.target.value)} autoComplete="current-password" />
          {error && <div className="error" role="alert">{error}</div>}
          <div style={{ marginTop: 12 }}>
            <button className="primary" type="submit">Sign in</button>
          </div>
        </form>
      </div>
    </main>
  );
}

function ErrorBox({ error }: { error: string }) {
  return error ? <div className="error" role="alert">{error}</div> : null;
}

function Field({ label, value, onChange, type = "text", id }: { label: string; value: string; onChange: (v: string) => void; type?: string; id: string }) {
  return (
    <div>
      <label htmlFor={id}>{label}</label>
      <input id={id} type={type} value={value} onChange={(e) => onChange(e.target.value)} />
    </div>
  );
}

function RequesterPanel({ user, refreshKey, refresh }: { user: User; refreshKey: number; refresh: () => void }) {
  const [sampleTypes, setSampleTypes] = useState<any[]>([]);
  const [samples, setSamples] = useState<any[]>([]);
  const [checkResult, setCheckResult] = useState<any>(null);
  const [error, setError] = useState("");
  const [msg, setMsg] = useState("");
  const [form, setForm] = useState({
    lat: "12.9716", lng: "77.5946", originType: "home", sampleTypeId: "",
    earliest: "", latest: "", deadline: "", containerType: "standard",
    tempMin: "2", tempMax: "25",
  });

  const load = useCallback(async () => {
    const b = await api<any>("/ui/bootstrap", undefined, "GET");
    setSampleTypes(b.sampleTypes ?? b.operations?.sampleTypes ?? []);
    setSamples(b.requesterSamples ?? []);
  }, []);

  useEffect(() => {
    load().catch(() => {});
    api<any>("/read-operations-state", {}).then((d) => {
      if (d.sampleTypes) setSampleTypes(d.sampleTypes);
    }).catch(() => {});
  }, [load, refreshKey]);

  const set = (k: string) => (v: string) => setForm((f) => ({ ...f, [k]: v }));

  const checkBody = () => ({
    origin: { latitude: parseFloat(form.lat), longitude: parseFloat(form.lng) },
    originType: form.originType,
    sampleTypeId: form.sampleTypeId,
    requestedAt: nowIso(),
    earliestCollectionAt: form.earliest ? new Date(form.earliest).toISOString() : undefined,
    latestCollectionAt: form.latest ? new Date(form.latest).toISOString() : undefined,
    deliveryDeadline: new Date(form.deadline).toISOString(),
  });

  return (
    <div>
      <div className="card">
        <h2>Check serviceability (dry run)</h2>
        <div className="row">
          <Field id="chk-lat" label="Origin latitude" value={form.lat} onChange={set("lat")} />
          <Field id="chk-lng" label="Origin longitude" value={form.lng} onChange={set("lng")} />
          <div>
            <label htmlFor="chk-type">Sample type</label>
            <select id="chk-type" value={form.sampleTypeId} onChange={(e) => set("sampleTypeId")(e.target.value)}>
              <option value="">Select sample type</option>
              {sampleTypes.map((t) => (
                <option key={t.sampleTypeId} value={t.sampleTypeId}>{t.name}</option>
              ))}
            </select>
          </div>
          <Field id="chk-deadline" label="Delivery deadline" type="datetime-local" value={form.deadline} onChange={set("deadline")} />
        </div>
        <div style={{ marginTop: 12 }}>
          <button
            className="primary"
            onClick={async () => {
              setError(""); setCheckResult(null);
              try {
                setCheckResult(await api("/check-serviceability", checkBody()));
              } catch (e) {
                setError(e instanceof ApiFailure ? e.message : "Check failed");
              }
            }}
          >
            Check serviceability
          </button>
        </div>
        <ErrorBox error={error} />
        {checkResult && (
          <div className={checkResult.serviceable ? "ok" : "error"}>
            {checkResult.serviceable
              ? `Serviceable — estimated arrival ${checkResult.estimatedArrivalAt ?? "unknown"}`
              : `Not serviceable: ${checkResult.reason ?? "unknown reason"}`}
          </div>
        )}
      </div>

      <div className="card">
        <h2>Create collection request</h2>
        <div className="row">
          <div>
            <label htmlFor="req-origin-type">Origin type</label>
            <select id="req-origin-type" value={form.originType} onChange={(e) => set("originType")(e.target.value)}>
              <option value="home">Home</option>
              <option value="clinic">Clinic</option>
              <option value="node">Network node</option>
            </select>
          </div>
          <Field id="req-earliest" label="Earliest collection" type="datetime-local" value={form.earliest} onChange={set("earliest")} />
          <Field id="req-latest" label="Latest collection" type="datetime-local" value={form.latest} onChange={set("latest")} />
          <Field id="req-container" label="Container type" value={form.containerType} onChange={set("containerType")} />
          <Field id="req-tmin" label="Temperature min (°C)" value={form.tempMin} onChange={set("tempMin")} />
          <Field id="req-tmax" label="Temperature max (°C)" value={form.tempMax} onChange={set("tempMax")} />
        </div>
        <div style={{ marginTop: 12 }}>
          <button
            className="primary"
            onClick={async () => {
              setError(""); setMsg("");
              try {
                if (!form.sampleTypeId) throw new ApiFailure("validation", "Sample type is required");
                if (!form.deadline) throw new ApiFailure("validation", "Delivery deadline is required");
                await api("/create-collection-request", {
                  ...checkBody(),
                  containerType: form.containerType,
                  temperatureMinC: parseFloat(form.tempMin),
                  temperatureMaxC: parseFloat(form.tempMax),
                  idempotencyKey: uuid(),
                });
                setMsg("Request created.");
                refresh();
              } catch (e) {
                setError(e instanceof ApiFailure ? e.message : "Create failed");
              }
            }}
          >
            Create request
          </button>
        </div>
        <ErrorBox error={error} />
        {msg && <div className="ok">{msg}</div>}
      </div>

      <div className="card">
        <h2>My samples</h2>
        {samples.length === 0 && <p>No samples yet.</p>}
        {samples.map((s) => (
          <SampleRow key={s.sampleId} sample={s} />
        ))}
      </div>
    </div>
  );
}

function SampleRow({ sample }: { sample: any }) {
  const [open, setOpen] = useState(false);
  return (
    <div style={{ borderTop: "1px solid #eee", padding: "8px 0" }}>
      <button className="small" onClick={() => setOpen(!open)}>
        {open ? "Hide details" : "View details"}
      </button>
      <strong>Sample {sample.sampleId?.slice(0, 8)}</strong>{" "}
      <span className="badge">{sample.state?.status ?? sample.status}</span>{" "}
      {sample.locationStale && <span className="badge stale">location stale</span>}
      {open && <SampleDetail sampleId={sample.sampleId} />}
    </div>
  );
}

function SampleDetail({ sampleId }: { sampleId: string }) {
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState("");
  useEffect(() => {
    api<any>(`/read-sample-state/${sampleId}`, undefined, "GET")
      .then(setData)
      .catch((e) => setError(e instanceof ApiFailure ? e.message : "Failed to load sample"));
  }, [sampleId]);
  if (error) return <ErrorBox error={error} />;
  if (!data) return <p>Loading…</p>;
  const timeline = [...(data.timeline ?? [])].sort((a, b) => (a.eventId ?? 0) - (b.eventId ?? 0));
  const exceptions = (data.exceptions ?? []).length > 0 || data.state?.status === "exception" || data.state?.status === "expired";
  return (
    <div style={{ marginTop: 8 }}>
      <p>
        Status: <span className="badge">{data.state?.status}</span>{" "}
        {exceptions && <span className="badge exception">exception</span>}{" "}
        {data.locationStale ? <span className="badge stale">location stale</span> : <span className="badge">location fresh</span>}
      </p>
      <p>
        Current custodian: {data.currentHolderId ?? data.state?.currentHolderId ?? "—"}<br />
        Last known location: {data.latestLocation ? `${data.latestLocation.latitude}, ${data.latestLocation.longitude}` : "—"}<br />
        Last update: {data.locationRecordedAt ?? "—"}<br />
        Route progress: {(data.completedLegIds ?? []).length} leg(s) completed, {(data.activeAssignmentIds ?? []).length} active
      </p>
      <h3>Status history</h3>
      <ol className="timeline" aria-label="Status history">
        {timeline.map((e) => (
          <li key={e.eventId}>
            <strong>{e.action}</strong> — {e.occurredAt} ({e.role})
          </li>
        ))}
      </ol>
    </div>
  );
}

function WorkPanel({ user, refreshKey, refresh }: { user: User; refreshKey: number; refresh: () => void }) {
  const [work, setWork] = useState<any>({ pending: [], inProgress: [], completed: [] });
  const [error, setError] = useState("");
  const [msg, setMsg] = useState("");

  const load = useCallback(async () => {
    try {
      setWork(await api("/list-role-work", { role: user.activeRole }));
    } catch (e) {
      setError(e instanceof ApiFailure ? e.message : "Failed to load work");
    }
  }, [user.activeRole]);

  useEffect(() => {
    load();
  }, [load, refreshKey]);

  const act = async (fn: () => Promise<any>, ok: string) => {
    setError(""); setMsg("");
    try {
      await fn();
      setMsg(ok);
      await load();
      refresh();
    } catch (e) {
      setError(e instanceof ApiFailure ? e.message : "Action failed");
    }
  };

  const renderAssignment = (a: any, section: string) => (
    <div key={a.assignmentId} style={{ borderTop: "1px solid #eee", padding: "8px 0" }}>
      <strong>{a.type ?? a.assignmentType ?? "assignment"}</strong>{" "}
      <span className="badge">{a.status}</span>{" "}
      <span>ID {a.assignmentId?.slice(0, 8)}</span>{" "}
      {a.sampleId && <span>sample {a.sampleId.slice(0, 8)}</span>}
      {a.pickupLocation && <div>Pickup: {a.pickupLocation.latitude}, {a.pickupLocation.longitude}</div>}
      {a.dropoffLocation && <div>Dropoff: {a.dropoffLocation.latitude}, {a.dropoffLocation.longitude}</div>}
      <div style={{ marginTop: 6 }}>
        {section === "pending" && (
          <>
            <button className="small" onClick={() => act(() => api("/accept-assignment", { assignmentId: a.assignmentId, idempotencyKey: uuid() }), "Assignment accepted")}>Accept</button>
            <button className="small" onClick={() => act(() => api("/decline-assignment", { assignmentId: a.assignmentId, idempotencyKey: uuid() }), "Assignment declined")}>Decline</button>
          </>
        )}
        {section === "inProgress" && <AssignmentActions a={a} role={user.activeRole} act={act} />}
      </div>
    </div>
  );

  return (
    <div>
      <ErrorBox error={error} />
      {msg && <div className="ok">{msg}</div>}
      <div className="grid">
        <div className="card">
          <h2>Offered (pending)</h2>
          {work.pending.length === 0 && <p>No pending offers.</p>}
          {work.pending.map((a: any) => renderAssignment(a, "pending"))}
        </div>
        <div className="card">
          <h2>Current work</h2>
          {work.inProgress.length === 0 && <p>No work in progress.</p>}
          {work.inProgress.map((a: any) => renderAssignment(a, "inProgress"))}
        </div>
        <div className="card">
          <h2>Completed work</h2>
          {work.completed.length === 0 && <p>No completed work yet.</p>}
          {work.completed.map((a: any) => renderAssignment(a, "completed"))}
        </div>
      </div>
    </div>
  );
}

function AssignmentActions({ a, role, act }: { a: any; role: string; act: (fn: () => Promise<any>, ok: string) => void }) {
  const [lat, setLat] = useState("12.9716");
  const [lng, setLng] = useState("77.5946");
  const [temp, setTemp] = useState("20");
  const [container, setContainer] = useState("standard");
  const [receiverId, setReceiverId] = useState("");
  const [handoffId, setHandoffId] = useState("");
  const [toAssignmentId, setToAssignmentId] = useState("");
  const [labId, setLabId] = useState("");
  const [seq, setSeq] = useState(1);

  return (
    <div>
      {role === "collection_professional" && (
        <button className="small" onClick={() => act(() => api("/collect-and-seal-sample", {
          sampleId: a.sampleId, assignmentId: a.assignmentId, collectedAt: nowIso(),
          containerType: container, observedTemperatureC: parseFloat(temp), idempotencyKey: uuid(),
        }), "Sample collected and sealed")}>Record collection &amp; seal</button>
      )}
      <button className="small" onClick={() => act(() => api("/update-assignment-progress", {
        assignmentId: a.assignmentId, status: "picked_up", occurredAt: nowIso(), idempotencyKey: uuid(),
      }), "Pickup recorded")}>Record pickup</button>
      <button className="small" onClick={() => act(() => api("/update-assignment-progress", {
        assignmentId: a.assignmentId, status: "delivered", occurredAt: nowIso(), idempotencyKey: uuid(),
      }), "Delivery recorded")}>Record delivery</button>
      <div style={{ marginTop: 8 }}>
        <label htmlFor={`lat-${a.assignmentId}`}>Record current location</label>
        <input id={`lat-${a.assignmentId}`} value={lat} onChange={(e) => setLat(e.target.value)} style={{ minWidth: 90 }} aria-label="Latitude" />
        <input value={lng} onChange={(e) => setLng(e.target.value)} style={{ minWidth: 90 }} aria-label="Longitude" />
        <button className="small" onClick={() => {
          act(() => api("/record-worker-location", {
            assignmentId: a.assignmentId,
            coordinate: { latitude: parseFloat(lat), longitude: parseFloat(lng) },
            sequence: seq, recordedAt: nowIso(),
          }), "Location recorded");
          setSeq((s) => s + 1);
        }}>Record location</button>
      </div>
      <div style={{ marginTop: 8 }}>
        <label htmlFor={`cp-${a.assignmentId}`}>Handling checkpoint</label>
        <input id={`cp-${a.assignmentId}`} value={container} onChange={(e) => setContainer(e.target.value)} style={{ minWidth: 100 }} aria-label="Container type" />
        <input value={temp} onChange={(e) => setTemp(e.target.value)} style={{ minWidth: 70 }} aria-label="Observed temperature" />
        <button className="small" onClick={() => act(() => api("/record-handling-checkpoint", {
          sampleId: a.sampleId, assignmentId: a.assignmentId, containerType: container,
          observedTemperatureC: parseFloat(temp), recordedAt: nowIso(), idempotencyKey: uuid(),
        }), "Checkpoint recorded")}>Record checkpoint</button>
      </div>
      <div style={{ marginTop: 8 }}>
        <label htmlFor={`ho-${a.assignmentId}`}>Handoff (receiver user ID, to-assignment ID)</label>
        <input id={`ho-${a.assignmentId}`} value={receiverId} onChange={(e) => setReceiverId(e.target.value)} aria-label="Receiver user ID" />
        <input value={toAssignmentId} onChange={(e) => setToAssignmentId(e.target.value)} aria-label="To assignment ID" />
        <button className="small" onClick={() => act(async () => {
          const r = await api<any>("/initiate-handoff", {
            sampleId: a.sampleId, fromAssignmentId: a.assignmentId, toAssignmentId,
            receiverId, initiatedAt: nowIso(), idempotencyKey: uuid(),
          });
          setHandoffId(r.handoffId);
        }, "Handoff initiated")}>Initiate handoff</button>
        <input value={handoffId} onChange={(e) => setHandoffId(e.target.value)} aria-label="Handoff ID" placeholder="handoff id" />
        <button className="small" onClick={() => act(() => api("/confirm-handoff", {
          handoffId, confirmationSide: "sender", confirmedAt: nowIso(), idempotencyKey: uuid(),
        }), "Handoff confirmed (sender)")}>Confirm as sender</button>
        <button className="small" onClick={() => act(() => api("/confirm-handoff", {
          handoffId, confirmationSide: "receiver", confirmedAt: nowIso(), idempotencyKey: uuid(),
        }), "Handoff confirmed (receiver)")}>Confirm as receiver</button>
      </div>
      {role === "laboratory_team" && (
        <div style={{ marginTop: 8 }}>
          <label htmlFor={`lab-${a.assignmentId}`}>Laboratory receipt (laboratory ID)</label>
          <input id={`lab-${a.assignmentId}`} value={labId} onChange={(e) => setLabId(e.target.value)} aria-label="Laboratory ID" />
          <button className="small" onClick={() => act(() => api("/confirm-laboratory-receipt", {
            sampleId: a.sampleId, laboratoryId: labId, receivedAt: nowIso(), idempotencyKey: uuid(),
          }), "Sample received at laboratory")}>Confirm laboratory receipt</button>
          <button className="small" onClick={() => act(() => api("/record-laboratory-exception", {
            sampleId: a.sampleId, laboratoryId: labId, reason: "cannot_accept", occurredAt: nowIso(), idempotencyKey: uuid(),
          }), "Exception recorded")}>Record exception</button>
        </div>
      )}
    </div>
  );
}

function CapacityPanel() {
  const [locations, setLocations] = useState<any[]>([]);
  const [error, setError] = useState("");
  useEffect(() => {
    api<any>("/read-operations-state", {})
      .then((d) => setLocations(d.locations ?? []))
      .catch((e) => setError(e instanceof ApiFailure ? e.message : "Failed to load capacity"));
  }, []);
  return (
    <div className="card">
      <h2>Node &amp; laboratory capacity</h2>
      <ErrorBox error={error} />
      <table aria-label="Capacity">
        <thead>
          <tr><th>Location</th><th>Regular (avail/res/cap)</th><th>Cooled (avail/res/cap)</th></tr>
        </thead>
        <tbody>
          {locations.map((l) => (
            <tr key={l.locationId}>
              <td>{l.name}</td>
              <td>{l.capacity?.availableUnits}/{l.capacity?.reservedUnits}/{l.capacity?.capacityUnits}</td>
              <td>{l.capacity?.cooledAvailableUnits}/{l.capacity?.cooledReservedUnits}/{l.capacity?.cooledCapacityUnits}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function SamplesPanel({ user }: { user: User }) {
  const [samples, setSamples] = useState<any[]>([]);
  const [error, setError] = useState("");
  useEffect(() => {
    if (user.activeRole === "requester") {
      api<any>("/ui/bootstrap", undefined, "GET").then((b) => setSamples(b.requesterSamples ?? [])).catch((e) => setError(e.message));
    } else {
      api<any>("/read-operations-state", {}).then((d) => setSamples(d.samples ?? [])).catch((e) => setError(e.message));
    }
  }, [user.activeRole]);
  return (
    <div className="card">
      <h2>Samples</h2>
      <ErrorBox error={error} />
      {samples.length === 0 && <p>No samples visible.</p>}
      {samples.map((s) => <SampleRow key={s.sampleId} sample={s} />)}
    </div>
  );
}

function MonitorPanel() {
  const [ops, setOps] = useState<any>(null);
  const [error, setError] = useState("");
  useEffect(() => {
    api<any>("/read-operations-state", { includeWorkers: true })
      .then(setOps)
      .catch((e) => setError(e instanceof ApiFailure ? e.message : "Failed to load operations state"));
  }, []);
  if (error) return <ErrorBox error={error} />;
  if (!ops) return <p>Loading…</p>;
  const sections: [string, any[], (x: any) => string][] = [
    ["Samples", ops.samples ?? [], (s) => `${s.sampleId?.slice(0, 8)} — ${s.state?.status ?? s.status}${s.locationStale ? " (stale)" : ""}`],
    ["Workers", ops.workers ?? [], (w) => `${w.workerId?.slice(0, 8)} — ${(w.roles ?? []).join(",")} — ${w.status}${w.locationStale ? " (stale)" : ""}`],
    ["Locations", ops.locations ?? [], (l) => `${l.name} — ${l.active ? "active" : "inactive"}`],
    ["Connections", ops.connections ?? [], (c) => `${c.fromLocationId?.slice(0, 8)} → ${c.toLocationId?.slice(0, 8)} — ${c.travelMinutes} min`],
    ["Exceptions", ops.exceptions ?? [], (e) => `${e.sampleId?.slice(0, 8) ?? ""} — ${e.reason ?? e.type ?? "exception"}`],
    ["Handoffs", ops.handoffs ?? [], (h) => `${h.handoffId?.slice(0, 8)} — ${h.status}`],
  ];
  return (
    <div className="grid">
      {sections.map(([title, items, fmt]) => (
        <div className="card" key={title}>
          <h2>{title} ({items.length})</h2>
          {items.length === 0 && <p>None.</p>}
          <ul>
            {items.slice(0, 50).map((x, i) => <li key={i}>{fmt(x)}</li>)}
          </ul>
        </div>
      ))}
    </div>
  );
}

function MapPanel() {
  const [markers, setMarkers] = useState<any[]>([]);
  const [error, setError] = useState("");
  useEffect(() => {
    api<any>("/read-operations-state", { includeWorkers: true })
      .then((d) => {
        const ms: any[] = [];
        (d.locations ?? []).forEach((l: any) => {
          if (l.coordinate) ms.push({ id: l.locationId, latitude: l.coordinate.latitude, longitude: l.coordinate.longitude, label: `Location: ${l.name}`, color: "#14335c" });
        });
        (d.workers ?? []).forEach((w: any) => {
          const c = w.lastKnownLocation ?? w.coordinate;
          if (c) ms.push({ id: w.workerId, latitude: c.latitude, longitude: c.longitude, label: `Worker ${w.workerId.slice(0, 8)}`, color: "#c8372d" });
        });
        (d.samples ?? []).forEach((s: any) => {
          if (s.latestLocation) ms.push({ id: s.sampleId, latitude: s.latestLocation.latitude, longitude: s.latestLocation.longitude, label: `Sample ${s.sampleId.slice(0, 8)}`, color: "#2d7a33" });
        });
        setMarkers(ms);
      })
      .catch((e) => setError(e instanceof ApiFailure ? e.message : "Failed to load map data"));
  }, []);
  return (
    <div className="card">
      <h2>Live network map</h2>
      <ErrorBox error={error} />
      <MapView markers={markers} />
    </div>
  );
}

function AuditPanel() {
  const [query, setQuery] = useState("");
  const [entries, setEntries] = useState<any[]>([]);
  const [error, setError] = useState("");
  const search = async () => {
    setError("");
    try {
      const d = await api<any>("/search-audit-trail", { query, limit: 100 });
      setEntries(d.entries ?? []);
    } catch (e) {
      setError(e instanceof ApiFailure ? e.message : "Search failed");
    }
  };
  useEffect(() => {
    search();
  }, []);
  return (
    <div className="card">
      <h2>Audit trail</h2>
      <label htmlFor="audit-query">Search audit history</label>
      <input id="audit-query" value={query} onChange={(e) => setQuery(e.target.value)} />
      <button className="small" style={{ marginLeft: 8 }} onClick={search}>Search</button>
      <ErrorBox error={error} />
      <table aria-label="Audit entries" style={{ marginTop: 12 }}>
        <thead>
          <tr><th>Time</th><th>Actor</th><th>Role</th><th>Action</th><th>Entity</th><th>Outcome</th></tr>
        </thead>
        <tbody>
          {entries.map((e) => (
            <tr key={e.auditId ?? e.eventId}>
              <td>{e.occurredAt}</td>
              <td>{e.actorId?.slice(0, 8)}</td>
              <td>{e.actorRole ?? e.role}</td>
              <td>{e.action}</td>
              <td>{e.entityType} {e.entityId?.slice(0, 8)}</td>
              <td>{e.success ? "success" : "failure"}</td>
            </tr>
          ))}
        </tbody>
      </table>
    </div>
  );
}

function AdminPanel({ refresh }: { refresh: () => void }) {
  const [error, setError] = useState("");
  const [msg, setMsg] = useState("");
  const [loc, setLoc] = useState({ name: "", lat: "12.97", lng: "77.59", coverageKm: "5", handlingMinutes: "5" });
  const [funcs, setFuncs] = useState<string[]>(["collection_point"]);
  const [st, setSt] = useState({ name: "", containerType: "standard", tempMin: "2", tempMax: "25" });
  const [usr, setUsr] = useState({ username: "", password: "", roles: "requester" });

  const run = async (fn: () => Promise<any>, ok: string) => {
    setError(""); setMsg("");
    try {
      await fn();
      setMsg(ok);
      refresh();
    } catch (e) {
      setError(e instanceof ApiFailure ? e.message : "Action failed");
    }
  };

  const toggleFunc = (f: string) =>
    setFuncs((fs) => (fs.includes(f) ? fs.filter((x) => x !== f) : [...fs, f]));

  return (
    <div>
      <ErrorBox error={error} />
      {msg && <div className="ok">{msg}</div>}
      <div className="grid">
        <div className="card">
          <h2>Create location</h2>
          <Field id="loc-name" label="Name" value={loc.name} onChange={(v) => setLoc({ ...loc, name: v })} />
          <Field id="loc-lat" label="Latitude" value={loc.lat} onChange={(v) => setLoc({ ...loc, lat: v })} />
          <Field id="loc-lng" label="Longitude" value={loc.lng} onChange={(v) => setLoc({ ...loc, lng: v })} />
          <Field id="loc-cov" label="Coverage (km)" value={loc.coverageKm} onChange={(v) => setLoc({ ...loc, coverageKm: v })} />
          <Field id="loc-hm" label="Handling minutes" value={loc.handlingMinutes} onChange={(v) => setLoc({ ...loc, handlingMinutes: v })} />
          <fieldset style={{ marginTop: 8 }}>
            <legend>Functions</legend>
            {["collection_point", "transfer_point", "hub", "laboratory"].map((f) => (
              <label key={f} style={{ fontWeight: 400 }}>
                <input type="checkbox" checked={funcs.includes(f)} onChange={() => toggleFunc(f)} style={{ minWidth: 0 }} /> {f}
              </label>
            ))}
          </fieldset>
          <button className="primary" style={{ marginTop: 8 }} onClick={() => run(() => api("/create-location", {
            name: loc.name,
            coordinate: { latitude: parseFloat(loc.lat), longitude: parseFloat(loc.lng) },
            coverageKm: parseFloat(loc.coverageKm),
            handlingMinutes: parseInt(loc.handlingMinutes),
            active: true,
            functions: funcs,
          }), "Location created")}>Create location</button>
        </div>
        <div className="card">
          <h2>Create sample type</h2>
          <Field id="st-name" label="Name" value={st.name} onChange={(v) => setSt({ ...st, name: v })} />
          <Field id="st-container" label="Container type" value={st.containerType} onChange={(v) => setSt({ ...st, containerType: v })} />
          <Field id="st-tmin" label="Temperature min (°C)" value={st.tempMin} onChange={(v) => setSt({ ...st, tempMin: v })} />
          <Field id="st-tmax" label="Temperature max (°C)" value={st.tempMax} onChange={(v) => setSt({ ...st, tempMax: v })} />
          <button className="primary" style={{ marginTop: 8 }} onClick={() => run(() => api("/create-sample-type", {
            name: st.name, containerType: st.containerType,
            temperatureMinC: parseFloat(st.tempMin), temperatureMaxC: parseFloat(st.tempMax),
          }), "Sample type created")}>Create sample type</button>
        </div>
        <div className="card">
          <h2>Create user</h2>
          <Field id="usr-name" label="Username" value={usr.username} onChange={(v) => setUsr({ ...usr, username: v })} />
          <Field id="usr-pass" label="Initial password" type="password" value={usr.password} onChange={(v) => setUsr({ ...usr, password: v })} />
          <div>
            <label htmlFor="usr-roles">Roles (comma separated)</label>
            <input id="usr-roles" value={usr.roles} onChange={(e) => setUsr({ ...usr, roles: e.target.value })} />
          </div>
          <button className="primary" style={{ marginTop: 8 }} onClick={() => run(() => api("/create-user", {
            username: usr.username, initialPassword: usr.password,
            roles: usr.roles.split(",").map((r) => r.trim()).filter(Boolean), active: true,
          }), "User created")}>Create user</button>
        </div>
      </div>
    </div>
  );
}

